INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宁可", "is_correct": true, "explanation": "正确：「宁可」表示权衡后宁愿选前一种，后面的「也不」与之配合，与句意相符。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：「格外」修饰形容词，如「格外好看」，不能修饰「不去旅行」这样的动词短语。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：「十分」修饰形容词或心理动词，不能直接修饰「不去旅行」这样的否定动作短语，句子不通。"}, {"text": "敢情", "is_correct": false, "explanation": "语域：「敢情」是口语色彩较浓的副词，表示恍然大悟，用在这里语义不合，也不符合书面的取舍表达。"}], "explanations": {"宁可": "正确：「宁可」表示权衡后宁愿选前一种，后面的「也不」与之配合，与句意相符。", "格外": "搭配：「格外」修饰形容词，如「格外好看」，不能修饰「不去旅行」这样的动词短语。", "十分": "搭配：「十分」修饰形容词或心理动词，不能直接修饰「不去旅行」这样的否定动作短语，句子不通。", "敢情": "语域：「敢情」是口语色彩较浓的副词，表示恍然大悟，用在这里语义不合，也不符合书面的取舍表达。"}, "sentence_index": 6, "correct_answer": "宁可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宁可明天天气好。", "explanation": "这里应该用〈但愿〉。宁可表示取舍，后面要有被放弃的一方；表示希望要用〈但愿〉。"}, {"text": "雨宁可马上就停了。", "explanation": "这里应该去掉〈宁可〉，直接说「雨马上就停了」。宁可表示取舍，不能表示即将发生。"}, {"text": "天宁可黑了。", "explanation": "这里应该用〈忽然〉。宁可表示取舍，不能描述天色突然变暗这种意外变化；要用〈忽然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很宁可晚点到，也不想让大家等。", "corrected_sentence": "我宁可晚点到，也不想让大家等。", "error_description": "错误：「宁可」前多加了程度副词「很」。「宁可」本身是副词，不能再受「很」修饰，正确形式是「我宁可晚点到」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我宁可多等一会儿，就不想催别人。", "corrected_sentence": "我宁可多等一会儿，也不想催别人。", "error_description": "错误：「也不」误写成「就不」。「宁可……也不……」表示宁愿承受前一种，也不选后一种；「就不」无法表达这种取舍，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
