INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脸是头的前面,有眼睛、鼻子和嘴。", "primary_collocate": null, "pronunciation": "liǎn", "ipa": "ljɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "小孩的脸上有眼睛、鼻子和嘴。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画一张脸，要先画眼睛和鼻子。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这张脸上有两只大眼睛。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的脸正对着我，我看得很清楚。", "target_word": "脸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转过脸，看着窗外的雨。", "target_word": "脸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的脸小小的，鼻子是粉色的。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的脸朝着太阳，闭上了眼睛。", "target_word": "脸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娃娃的脸上，嘴巴小小的，眼睛圆圆的。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "镜子里，我看见了自己的脸。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈亲了一下我的脸。", "target_word": "脸", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "臉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "头的前面有眼睛鼻子和嘴的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "脸", "is_correct": true, "explanation": "「脸」（liǎn）指头的前面，有眼睛、鼻子和嘴，是正确答案。"}, {"text": "练", "is_correct": false, "explanation": "liàn（第四声）与 liǎn（第三声）声调不同，意思是练习。"}, {"text": "联", "is_correct": false, "explanation": "lián（第二声）与 liǎn（第三声）声调不同，意思是联合。"}, {"text": "两", "is_correct": false, "explanation": "liǎng 与 liǎn 韵母不同（ang 与 an），意思是两个。"}], "explanations": {"脸": "「脸」（liǎn）指头的前面，有眼睛、鼻子和嘴，是正确答案。", "练": "liàn（第四声）与 liǎn（第三声）声调不同，意思是练习。", "联": "lián（第二声）与 liǎn（第三声）声调不同，意思是联合。", "两": "liǎng 与 liǎn 韵母不同（ang 与 an），意思是两个。"}, "sentence_index": null, "correct_answer": "脸"}, "level_3": {"options": [{"text": "脸", "is_correct": true, "explanation": "「脸」是头的前面，有眼睛、鼻子和嘴，「小孩的脸上」与之相合，正确。"}, {"text": "手", "is_correct": false, "explanation": "语义：手上没有眼睛、鼻子和嘴，「小孩的手上有眼睛、鼻子和嘴」不成立。"}, {"text": "肚子", "is_correct": false, "explanation": "语义：眼睛、鼻子和嘴不长在肚子上，句子说的是五官。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：「眼睛」本身是五官之一，不能说「眼睛上有眼睛、鼻子和嘴」。"}], "explanations": {"脸": "「脸」是头的前面，有眼睛、鼻子和嘴，「小孩的脸上」与之相合，正确。", "手": "语义：手上没有眼睛、鼻子和嘴，「小孩的手上有眼睛、鼻子和嘴」不成立。", "肚子": "语义：眼睛、鼻子和嘴不长在肚子上，句子说的是五官。", "眼睛": "搭配：「眼睛」本身是五官之一，不能说「眼睛上有眼睛、鼻子和嘴」。"}, "sentence_index": 0, "correct_answer": "脸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画里有一条脸，很大很圆。", "explanation": "这里应该用〈张〉。「脸」用量词「张」，「条」用于细长的东西，不能用来数脸。"}, {"text": "他感冒了，脸一直堵着，呼吸很难受。", "explanation": "这里应该用〈鼻子〉。堵的是鼻子，脸是整个头的前面，不能说“脸堵着”。"}, {"text": "他的手冰凉，我用脸握着，很不舒服。", "explanation": "这里应该用〈手〉。握要用手，脸不能用来握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88571, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "脸", "is_correct": true, "explanation": "「脸」（liǎn）指头的前面，有眼睛、鼻子和嘴，是正确答案。"}, {"text": "恋", "is_correct": false, "explanation": "liàn（第四声）与 liǎn（第三声）声调不同，意思是恋爱。"}, {"text": "连", "is_correct": false, "explanation": "lián（第二声）与 liǎn（第三声）声调不同，意思是连接。"}, {"text": "两", "is_correct": false, "explanation": "liǎng 与 liǎn 只差韵尾（ng 与 n），意思是两个。"}], "explanations": {"脸": "「脸」（liǎn）指头的前面，有眼睛、鼻子和嘴，是正确答案。", "恋": "liàn（第四声）与 liǎn（第三声）声调不同，意思是恋爱。", "连": "lián（第二声）与 liǎn（第三声）声调不同，意思是连接。", "两": "liǎng 与 liǎn 只差韵尾（ng 与 n），意思是两个。"}, "sentence_index": null, "correct_answer": "脸"}, "level_3": {"options": [{"text": "脸", "is_correct": true, "explanation": "「脸」是头的前面，「他的脸朝着太阳」「闭上了眼睛」都与之相合，正确。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：「成绩」是抽象的评定结果，没有朝向，不能「朝着太阳」。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：「年龄」是抽象的岁数，没有朝向，不能「朝着太阳」。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「朝着太阳」说的是朝向，「声音」不能朝向太阳。"}], "explanations": {"脸": "「脸」是头的前面，「他的脸朝着太阳」「闭上了眼睛」都与之相合，正确。", "成绩": "语义：「成绩」是抽象的评定结果，没有朝向，不能「朝着太阳」。", "年龄": "语义：「年龄」是抽象的岁数，没有朝向，不能「朝着太阳」。", "声音": "搭配：「朝着太阳」说的是朝向，「声音」不能朝向太阳。"}, "sentence_index": 6, "correct_answer": "脸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张画上画着一只脸。", "explanation": "这里应该用〈张〉。「脸」用量词「张」，「只」用于动物或成对器官中的一个，不能用来数脸。"}, {"text": "他睁开脸，看了看天。", "explanation": "这里应该用〈眼睛〉。睁开的是眼睛，脸不能睁开。"}, {"text": "他冷得直跺脸。", "explanation": "这里应该用〈脚〉。跺的是脚，脸不能跺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在纸上画了一颗脸。", "corrected_sentence": "我在纸上画了一张脸。", "error_description": "「脸」的量词是「张」，「颗」用于小而圆的东西，不能用来数脸。错误形式是「一颗脸」，应改为「一张脸」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她轻轻地摸了摸孩子脸。", "corrected_sentence": "她轻轻地摸了摸孩子的脸。", "error_description": "「孩子」和「脸」之间要用「的」连接，错误形式是「孩子脸」，应改为「孩子的脸」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
