INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股票是买了它就有一小块公司的纸，也能再卖给别人。", "primary_collocate": null, "pronunciation": "gǔ piào", "ipa": "ku˨˩˦ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷留着一张旧股票。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了这家公司的股票，你就是它的小股东。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股票可以再卖给别人。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想买哪家公司的股票？", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把股票卖给了朋友。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把卖股票的钱存进了银行。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手里有股票，就拥有公司的一小部分。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股票很多人想买。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不懂股票，所以没有买过。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股票涨了，我的钱也变多了。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "股票市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "买了就拥有公司一小部分、可以转卖的凭证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股票", "is_correct": true, "explanation": "正确：“股票”是入股凭证，用“张”计量，符合“留着一张旧股票”。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“张”不用于鞋，应说“双”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾一般不会被特意留着，与“留着”的语境矛盾。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被留着，与“留着一张旧”不搭。"}], "explanations": {"股票": "正确：“股票”是入股凭证，用“张”计量，符合“留着一张旧股票”。", "鞋": "搭配：“张”不用于鞋，应说“双”。", "垃圾": "语义：垃圾一般不会被特意留着，与“留着”的语境矛盾。", "空气": "语义：空气无法被留着，与“留着一张旧”不搭。"}, "sentence_index": 0, "correct_answer": "股票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你想见哪家公司的股票？", "explanation": "这里应该用〈老板〉。见的是人，股票是有价证券，不能见。"}, {"text": "你想去哪家饭馆吃股票？", "explanation": "这里应该用〈饭〉。吃的是食物，股票不能吃。"}, {"text": "你想开哪家公司的股票？", "explanation": "这里应该用〈车〉。开的是车辆，股票不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股票", "is_correct": true, "explanation": "正确：“股票”是入股凭证，手里有它就拥有公司的一小部分。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不代表公司股份，与后半句的意思不符。"}, {"text": "土地", "is_correct": false, "explanation": "语义：土地不是入股凭证，与“公司的一小部分”不符。"}, {"text": "豆腐", "is_correct": false, "explanation": "搭配：“豆腐”无法与“拥有公司的一小部分”搭配。"}], "explanations": {"股票": "正确：“股票”是入股凭证，手里有它就拥有公司的一小部分。", "钥匙": "语义：钥匙不代表公司股份，与后半句的意思不符。", "土地": "语义：土地不是入股凭证，与“公司的一小部分”不符。", "豆腐": "搭配：“豆腐”无法与“拥有公司的一小部分”搭配。"}, "sentence_index": 6, "correct_answer": "股票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天喝股票，钱也变多了。", "explanation": "这里应该用〈水〉。喝的是饮品，股票是有价证券，不能喝。"}, {"text": "我每天穿股票，钱也变多了。", "explanation": "这里应该用〈衣服〉。穿的是衣物，股票不能穿。"}, {"text": "我每天骑股票上班，钱也变多了。", "explanation": "这里应该用〈自行车〉。骑的是车辆，股票不能骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了这家公司地股票。", "corrected_sentence": "我买了这家公司的股票。", "error_description": "错误在助词：修饰名词“股票”应用“的”，不能用“地”（“地”用于修饰动词的状语），应说“这家公司的股票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家有一把旧股票。", "corrected_sentence": "我们家有一张旧股票。", "error_description": "“把”用于有柄的东西，股票是纸质凭证，应用“张”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
