INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股份公司发给股东作为入股凭证的有价证券。", "primary_collocate": null, "pronunciation": "gǔ piào", "ipa": "ku˨˩˦ pʰjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他买了一只股票。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只股票今天涨了很多。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸喜欢看股票的消息。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用奖金买了股票。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股票很贵。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天股票一直在下跌。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他卖掉了手里的股票。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买股票有风险，要小心。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的股票上市了。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在手机上看股票。", "target_word": "股票", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "股票市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "股份公司发给股东的入股凭证，有价证券", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股票", "is_correct": true, "explanation": "正确：“股票”可以用“只”计量，符合“买了一只股票”。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“只”不用于电影，应说“部”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“只”不用于房子，应说“套”或“座”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无形，不能买，与“买了”不搭。"}], "explanations": {"股票": "正确：“股票”可以用“只”计量，符合“买了一只股票”。", "电影": "搭配：“只”不用于电影，应说“部”。", "房子": "搭配：“只”不用于房子，应说“套”或“座”。", "空气": "语义：空气无形，不能买，与“买了”不搭。"}, "sentence_index": 0, "correct_answer": "股票"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只股票每年的利息很高。", "explanation": "这里应该用〈债券〉。股票的收益是股息，按期付固定利息的是债券，不能说股票的利息。"}, {"text": "她把奖金存进了股票。", "explanation": "这里应该用〈银行〉。存钱是存进银行，股票要买，不能说存进股票。"}, {"text": "她买了一张股票，去电影院看电影。", "explanation": "这里应该用〈电影票〉。进电影院要买的是票，股票是有价证券，不能当票用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股票", "is_correct": true, "explanation": "正确：“卖掉”的对象是股票，符合“卖掉了手里的股票”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子无法卖，与“卖掉”不搭。"}, {"text": "心", "is_correct": false, "explanation": "搭配：“卖掉”不能搭配“心”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气无形，不能被卖掉。"}], "explanations": {"股票": "正确：“卖掉”的对象是股票，符合“卖掉了手里的股票”。", "影子": "语义：影子无法卖，与“卖掉”不搭。", "心": "搭配：“卖掉”不能搭配“心”。", "天气": "语义：天气无形，不能被卖掉。"}, "sentence_index": 6, "correct_answer": "股票"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃股票。", "explanation": "这里应该用〈饭〉。吃的是食物，股票是有价证券，不能吃。"}, {"text": "他每天给朋友写股票。", "explanation": "这里应该用〈信〉。写的是信件，股票是证书，要买卖，不能写。"}, {"text": "他每天开股票上班。", "explanation": "这里应该用〈车〉。开的是交通工具，股票不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买过一部股票。", "corrected_sentence": "他买过一只股票。", "error_description": "错误在量词：“部”用于电影、书籍等，股票应用“只”计量，应说“买过一只股票”，不能说“买过一部股票”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥最近开始研究这家公司地股票了。", "corrected_sentence": "哥哥最近开始研究这家公司的股票了。", "error_description": "错误在助词：修饰名词“股票”应用“的”，不能用“地”（“地”用于修饰动词的状语），应说“这家公司的股票”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
