INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88601, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "观看是用眼睛看，常常是认真地看表演或比赛。", "primary_collocate": null, "pronunciation": "guān kàn", "ipa": "kwan˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他们在现场观看世界杯。", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们去剧院观看话剧。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众正在观看舞蹈表演。", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在家里观看篮球赛直播。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友们站在路边观看游行。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐在前排观看京剧。", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生们观看了运动会开幕式。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先买票，再进去观看比赛。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想观看哪一场比赛？", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她从小就爱观看芭蕾演出。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "观看了", "label": "了体"}, {"form": "观看过", "label": "过体"}, {"form": "观看着", "label": "着体"}], "register": "书面", "sense_fingerprint": "用眼睛看，常常是认真地看表演或比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88601, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观看", "is_correct": true, "explanation": "正确：“观看”指认真地看表演或比赛，与“在现场”和“世界杯”相符。"}, {"text": "收看", "is_correct": false, "explanation": "语义：“收看”指通过电视看，与“在现场”的意思相矛盾。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，不能用来指观看世界杯。"}, {"text": "培养", "is_correct": false, "explanation": "搭配：“培养”的对象是人才、习惯，不能说“培养世界杯”。"}], "explanations": {"观看": "正确：“观看”指认真地看表演或比赛，与“在现场”和“世界杯”相符。", "收看": "语义：“收看”指通过电视看，与“在现场”的意思相矛盾。", "修": "语义：“修”指修理，不能用来指观看世界杯。", "培养": "搭配：“培养”的对象是人才、习惯，不能说“培养世界杯”。"}, "sentence_index": 0, "correct_answer": "观看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去图书馆观看了很多数学题。", "explanation": "这里应该用〈做〉。观看指看表演或比赛，做数学题要用做。"}, {"text": "周末我去养老院观看老人。", "explanation": "这里应该用〈看望〉。观看的对象是表演或比赛，去养老院探望老人要用看望。"}, {"text": "妈妈仔细观看宝宝的哭声。", "explanation": "这里应该用〈听〉。观看是用眼睛看，宝宝的哭声要用听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88601, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观看", "is_correct": true, "explanation": "正确：“观看”指认真地看表演或比赛，与“学生们观看了开幕式”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于开幕式，句子说不通。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“饲养开幕式”。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：“驾驶”指操纵车辆，开幕式不能被驾驶。"}], "explanations": {"观看": "正确：“观看”指认真地看表演或比赛，与“学生们观看了开幕式”的语境相符。", "吃": "语义：“吃”不能用于开幕式，句子说不通。", "饲养": "搭配：“饲养”的对象是动物，不能说“饲养开幕式”。", "驾驶": "语义：“驾驶”指操纵车辆，开幕式不能被驾驶。"}, "sentence_index": 6, "correct_answer": "观看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上观看报纸。", "explanation": "这里应该用〈阅读〉。观看用于表演、比赛，读报纸要用阅读。"}, {"text": "我每天早上观看广播。", "explanation": "这里应该用〈收听〉。观看用于表演、比赛；广播是用耳朵听的，要用收听。"}, {"text": "医生认真观看病人的身体。", "explanation": "这里应该用〈检查〉。观看指看表演或比赛，检查身体要用检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们昨天在现场观看一场足球赛。", "corrected_sentence": "他们昨天在现场观看了一场足球赛。", "error_description": "错误形式：“观看”后漏掉了动态助词“了”。正确形式：“观看了一场足球赛”。昨天已完成的动作要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候从来没观看了演唱会。", "corrected_sentence": "我小时候从来没观看过演唱会。", "error_description": "错误形式：“没观看了”中的“了”应改为“过”。正确形式：“没观看过演唱会”。否定过去的经历要用“没……过”，“没”与“了”不能同时使用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
