INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88602, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认真地看（表演、比赛等）。", "primary_collocate": null, "pronunciation": "guān kàn", "ipa": "kwan˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "我们一起去观看足球比赛。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上全家人观看了春节晚会。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人在体育馆观看比赛。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天观看了一场精彩的演出。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们安静地观看着表演。", "target_word": "观看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你观看过这位歌手的演唱会吗？", "target_word": "观看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众在座位上观看比赛。", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大家坐好观看表演。", "target_word": "观看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在电视上观看了开幕式。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸带我去现场观看马戏。", "target_word": "观看", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "观看了", "label": "了体"}, {"form": "观看过", "label": "过体"}, {"form": "观看着", "label": "着体"}], "register": "书面", "sense_fingerprint": "认真地看表演、比赛等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观看", "is_correct": true, "explanation": "正确：“观看”指认真地看表演或比赛，与“足球比赛”搭配，符合“一起去”的语境。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”的对象是动物，不能说“饲养足球比赛”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于比赛，“去吃足球比赛”说不通。"}, {"text": "培养", "is_correct": false, "explanation": "搭配：“培养”的对象是人才、习惯，不能说“培养足球比赛”。"}], "explanations": {"观看": "正确：“观看”指认真地看表演或比赛，与“足球比赛”搭配，符合“一起去”的语境。", "饲养": "搭配：“饲养”的对象是动物，不能说“饲养足球比赛”。", "吃": "语义：“吃”不能用于比赛，“去吃足球比赛”说不通。", "培养": "搭配：“培养”的对象是人才、习惯，不能说“培养足球比赛”。"}, "sentence_index": 0, "correct_answer": "观看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天去超市观看了很多蔬菜。", "explanation": "这里应该用〈挑选〉。观看指看表演或比赛，挑选蔬菜要用挑选。"}, {"text": "周末我去医院观看生病的奶奶。", "explanation": "这里应该用〈看望〉。观看的对象是表演或比赛，探望病人要用看望。"}, {"text": "医生认真观看病人的伤口。", "explanation": "这里应该用〈观察〉。观看偏重看表演、比赛，观察伤口、病情的变化要用观察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观看", "is_correct": true, "explanation": "正确：“观看”指认真地看表演或比赛，与“观众在座位上”的语境相符。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”指加入比赛、成为参赛者，观众只是旁观者。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：“举办”的主语须是组织者，观众不能举办比赛。"}, {"text": "指挥", "is_correct": false, "explanation": "语义：“指挥”指主持、掌控比赛进程，观众坐在座位上不能指挥比赛。"}], "explanations": {"观看": "正确：“观看”指认真地看表演或比赛，与“观众在座位上”的语境相符。", "参加": "语义：“参加”指加入比赛、成为参赛者，观众只是旁观者。", "举办": "搭配：“举办”的主语须是组织者，观众不能举办比赛。", "指挥": "语义：“指挥”指主持、掌控比赛进程，观众坐在座位上不能指挥比赛。"}, "sentence_index": 6, "correct_answer": "观看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上观看报纸。", "explanation": "这里应该用〈阅读〉。观看用于表演、比赛，读报纸要用阅读。"}, {"text": "他每天下午观看广播。", "explanation": "这里应该用〈收听〉。观看用于表演、比赛；广播是用耳朵听的，要用收听。"}, {"text": "护士认真观看病人的血压。", "explanation": "这里应该用〈检查〉。观看指看表演或比赛，测量血压、检查身体要用检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天一起观看篮球比赛。", "corrected_sentence": "我们昨天一起观看了篮球比赛。", "error_description": "错误形式：“观看”后漏掉了动态助词“了”。正确形式：“观看了篮球比赛”。昨天已完成的动作要用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没观看了这样精彩的比赛。", "corrected_sentence": "我从来没观看过这样精彩的比赛。", "error_description": "错误形式：“没”后用了“了”。正确形式：“没观看过”。“没”否定的是经历，要用“过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
