INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谈话", "is_correct": true, "explanation": "谈话：两人或多人之间交谈，正是本词的意思。"}, {"text": "碳化", "is_correct": false, "explanation": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。"}, {"text": "弹花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。"}, {"text": "糖化", "is_correct": false, "explanation": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。"}, {"text": "淡化", "is_correct": false, "explanation": "dàn（第四声）与 tán 的声母和声调都不同，淡化指使变淡或减弱，不是交谈。"}, {"text": "甜话", "is_correct": false, "explanation": "tián（第二声）与 tán 韵母不同（-ian 对 -an），甜话指好听、讨好的话，不是交谈。"}], "explanations": {"谈话": "谈话：两人或多人之间交谈，正是本词的意思。", "碳化": "tàn（第四声）与 tán（第二声）声调不同，碳化指化学上的碳化过程，不是交谈。", "弹花": "huā（第一声）与 huà（第四声）声调不同，弹花指用弓弹松棉花，不是说话。", "糖化": "táng 与 tán 韵母不同（-ang 对 -an），糖化指淀粉分解成糖，不是交谈。", "淡化": "dàn（第四声）与 tán 的声母和声调都不同，淡化指使变淡或减弱，不是交谈。", "甜话": "tián（第二声）与 tán 韵母不同（-ian 对 -an），甜话指好听、讨好的话，不是交谈。"}, "sentence_index": null, "correct_answer": "谈话"}, "level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“校长找他谈话”指校长找他当面谈事情。"}, {"text": "撒娇", "is_correct": false, "explanation": "语义：撒娇是对亲近的人任性撒痴，不用于校长找学生问话。"}, {"text": "谈判", "is_correct": false, "explanation": "搭配：谈判指双方为达成协议而协商，“校长找他谈判”不符合常用搭配。"}, {"text": "谈恋爱", "is_correct": false, "explanation": "语义：谈恋爱指男女相爱，与“问他为什么迟到”的语境不符。"}], "explanations": {"谈话": "正确：“校长找他谈话”指校长找他当面谈事情。", "撒娇": "语义：撒娇是对亲近的人任性撒痴，不用于校长找学生问话。", "谈判": "搭配：谈判指双方为达成协议而协商，“校长找他谈判”不符合常用搭配。", "谈恋爱": "语义：谈恋爱指男女相爱，与“问他为什么迟到”的语境不符。"}, "sentence_index": 0, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师一个人在教室里谈话，没有学生回应。", "explanation": "这里应该用〈自言自语〉。谈话需要两人或几人交谈，一人说话不是谈话。"}, {"text": "她谈话很慢，我们等了很久。", "explanation": "这里应该用〈说话〉。谈话指交谈这件事，不用来描述说话的速度。"}, {"text": "在菜市场，我对着摊主谈话，摊主头也不抬地忙着称菜。", "explanation": "谈话需要双方互相交流；只有一方说话、另一方不回应时，不能用谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈话", "is_correct": true, "explanation": "正确：“两位老人在公园里谈话”指两位老人在公园里交谈。"}, {"text": "上课", "is_correct": false, "explanation": "语义：上课是在学校里进行的活动，两位老人在公园里不能“上课”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是在学校或考场进行的活动，与公园的场景不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：洗澡一般在浴室或浴缸里进行，不说“在公园里洗澡”。"}], "explanations": {"谈话": "正确：“两位老人在公园里谈话”指两位老人在公园里交谈。", "上课": "语义：上课是在学校里进行的活动，两位老人在公园里不能“上课”。", "考试": "语义：考试是在学校或考场进行的活动，与公园的场景不符。", "洗澡": "搭配：洗澡一般在浴室或浴缸里进行，不说“在公园里洗澡”。"}, "sentence_index": 6, "correct_answer": "谈话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们每个月互相谈话，一写就是好几页纸。", "explanation": "这里应该用〈通信〉。谈话指口头交谈，书信往来要用通信。"}, {"text": "两位候选人在电视上谈话，拍着桌子互相大骂。", "explanation": "这里应该用〈吵架〉。谈话是平和的交谈，拍桌子互相大骂要用吵架。"}, {"text": "她一个人站在窗前谈话，没有人理她。", "explanation": "这里应该用〈自言自语〉。谈话需要两人或几人交谈，一人说话不是谈话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天找老板谈话工作。", "corrected_sentence": "我明天找老板谈话。", "error_description": "“谈话”是不及物的离合词，后面不能直接带“工作”作宾语。应删去“工作”，写作“我明天找老板谈话。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们谈话过好几次。", "corrected_sentence": "我们谈过话好几次。", "error_description": "“谈话”是离合词，体标“过”要放在“谈”后面，写作“谈过话”。“谈话过”的位置不对，应改为“我们谈过话好几次。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
