INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在去某地或返回的途中。", "primary_collocate": null, "pronunciation": "lù shang", "ipa": "lu⁵¹ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "我在路上买了一杯咖啡。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上小心，到家给我打电话。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在路上遇到了老同学。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去机场的路上，我一直在看书。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在路上吃了午饭。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在回家的路上接到了电话。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，所以我来晚了。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在路上给我发了一条消息。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在路上聊了很多。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在路上走了两个小时。", "target_word": "路上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "行进途中（过程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b561781c-ab85-4690-8dcd-c94501bb469d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书里", "is_correct": false, "explanation": "语义：书里不能买咖啡，“买”的场所不能是书。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”表示行进途中，“我在路上买了一杯咖啡”自然通顺。"}, {"text": "黑板上", "is_correct": false, "explanation": "搭配：“买”需要商店、街边等场所，黑板上不能买东西。"}, {"text": "天上", "is_correct": false, "explanation": "语义：天上不能买咖啡，句子前后矛盾。"}], "explanations": {"书里": "语义：书里不能买咖啡，“买”的场所不能是书。", "路上": "正确：“路上”表示行进途中，“我在路上买了一杯咖啡”自然通顺。", "黑板上": "搭配：“买”需要商店、街边等场所，黑板上不能买东西。", "天上": "语义：天上不能买咖啡，句子前后矛盾。"}, "sentence_index": 0, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上的厨房里做了晚饭。", "explanation": "“路上”表示行进途中，不能与“厨房里”搭配表示室内的位置，这里应直接说“在厨房里做了晚饭”。"}, {"text": "我的钥匙放在路上的卧室里。", "explanation": "“路上”表示在道路上或行进途中，不能用来指卧室里的位置，这里应去掉“路上”，直接说“放在卧室里”。"}, {"text": "工人们在路上的车间里工作。", "explanation": "“路上”不能用来指车间里的位置，这里应直接说“在车间里工作”，不用“路上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室里", "is_correct": false, "explanation": "语义：“堵车”发生在教室里不合常理，前后矛盾。"}, {"text": "路上", "is_correct": true, "explanation": "正确：“路上”表示行进途中，“路上堵车”自然通顺，解释了“来晚了”。"}, {"text": "书里", "is_correct": false, "explanation": "搭配：“堵车”的场所应是道路，“书里”不能堵车。"}, {"text": "厨房里", "is_correct": false, "explanation": "语义：厨房里不会堵车，这句的因果关系不成立。"}], "explanations": {"教室里": "语义：“堵车”发生在教室里不合常理，前后矛盾。", "路上": "正确：“路上”表示行进途中，“路上堵车”自然通顺，解释了“来晚了”。", "书里": "搭配：“堵车”的场所应是道路，“书里”不能堵车。", "厨房里": "语义：厨房里不会堵车，这句的因果关系不成立。"}, "sentence_index": 6, "correct_answer": "路上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在路上的教室里学习了两个小时。", "explanation": "“路上”表示行进途中，不能用来指教室的位置，这里的组合不符合本义项。"}, {"text": "他在路上的餐厅里吃了午饭。", "explanation": "“路上”表示行进途中，不能与“餐厅里”搭配表示室内的位置。"}, {"text": "她在路上的家里睡了一觉。", "explanation": "“路上”表示行进途中，不能用来指家里的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去火车站的路上里，我们遇到了一场大雨。", "corrected_sentence": "去火车站的路上，我们遇到了一场大雨。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“去火车站的路上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在去学校的路上里，他听了一首新歌。", "corrected_sentence": "在去学校的路上，他听了一首新歌。", "error_description": "错误：“路上”后面又加了“里”，形成重复的方位词。应去掉“里”，改为“路上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上传", "is_correct": true, "explanation": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常动作，与“下载”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是走路休息，与“下载”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”是绘画活动，与“下载”没有反义关系。"}], "correct_answer": "上传", "explanations": {"上传": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。", "睡觉": "“睡觉”是日常动作，与“下载”没有反义关系。", "散步": "“散步”是走路休息，与“下载”没有反义关系。", "画画": "“画画”是绘画活动，与“下载”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上传", "is_correct": true, "explanation": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是运动，与“下载”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”是阅读活动，与“下载”没有反义关系。"}, {"text": "做饭", "is_correct": false, "explanation": "“做饭”是烹饪活动，与“下载”没有反义关系。"}], "correct_answer": "上传", "explanations": {"上传": "正确：“上传”与“下载”是反义词，下载是把网上的东西拿到自己的设备，上传是把自己设备上的东西送到网上。", "跑步": "“跑步”是运动，与“下载”没有反义关系。", "读书": "“读书”是阅读活动，与“下载”没有反义关系。", "做饭": "“做饭”是烹饪活动，与“下载”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下载是把网上的东西拿到自己的手机或电脑里。", "primary_collocate": null, "pronunciation": "xià zài", "ipa": "ɕja˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我想下载一个新的听歌软件。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上下载了一部电影。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你会下载这个游戏吗？", "target_word": "下载", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把网上的照片下载到了电脑里。", "target_word": "下载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先下载这个软件，再打开它。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天晚上下载了一本小说。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没下载过这个软件。", "target_word": "下载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里的软件都是我自己下载的。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里没有网，我没法下载电影。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他正在下载孩子喜欢的动画片。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下载了", "label": "体标"}, {"form": "下载过", "label": "体标"}, {"form": "下载量", "label": "复合"}], "register": "中性", "sense_fingerprint": "下载：日常上网时把歌、电影、软件等拿到自己的手机或电脑里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下载", "is_correct": true, "explanation": "正确：“下载”表示把网上的软件拿到自己的设备上，与“听歌软件”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能用来搭配“软件”，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，与“软件”的意思不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用来搭配“软件”，只能用于清洁物品。"}], "explanations": {"下载": "正确：“下载”表示把网上的软件拿到自己的设备上，与“听歌软件”搭配。", "吃": "搭配：“吃”不能用来搭配“软件”，句子说不通。", "唱": "语义：“唱”指发声演唱，与“软件”的意思不符。", "洗": "搭配：“洗”不能用来搭配“软件”，只能用于清洁物品。"}, "sentence_index": 0, "correct_answer": "下载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把照片下载到了网上。", "explanation": "这里应该用〈上传〉。下载是把网上的东西拿到自己的设备，把照片放到网上要用上传。"}, {"text": "我把照片下载给了朋友。", "explanation": "这里应该用〈发送〉。下载是从网上获取东西，不能把自己的照片送给别人。"}, {"text": "我在书店下载了一本书。", "explanation": "这里应该用〈购买〉。下载是通过网络获取，不能在书店里下载。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下载", "is_correct": true, "explanation": "正确：“下载”与“过”搭配，表示没有做过把软件拿到设备上的动作。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用来搭配“软件”。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不能用于“软件”。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感觉气味，与“软件”的意思不符。"}], "explanations": {"下载": "正确：“下载”与“过”搭配，表示没有做过把软件拿到设备上的动作。", "煮": "搭配：“煮”用于食物，不能用来搭配“软件”。", "喂": "搭配：“喂”的对象是人或动物，不能用于“软件”。", "闻": "语义：“闻”指用鼻子感觉气味，与“软件”的意思不符。"}, "sentence_index": 6, "correct_answer": "下载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把动画片下载给了孩子。", "explanation": "这里应该用〈送给〉。下载是把网上的东西拿到自己的设备，不能把动画片送给别人。"}, {"text": "我在店里下载了一套西装。", "explanation": "这里应该用〈租〉。下载是通过网络获取，不能在店里下载西装。"}, {"text": "这本书是在工厂下载的。", "explanation": "这里应该用〈印刷〉。下载是通过网络获取，不能在工厂里下载实物书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这部电影下载。", "corrected_sentence": "他把这部电影下载了。", "error_description": "错误：用“把”字句时，动词后面缺少“了”或其他补语。正确：应说“他把这部电影下载了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那部电影下载手机里了。", "corrected_sentence": "我把那部电影下载到手机里了。", "error_description": "错误：表示文件传送到某处，终点要用介词“到”，这里漏掉了“到”，不能说“下载手机里”。正确：应说“下载到手机里了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上传", "is_correct": true, "explanation": "正确：“上传”与“下载”是反义词，下载是把网络上的文件拿到自己的设备，上传是把自己设备上的文件送到网络上。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”是日常动作，与“下载”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是走路休息，与“下载”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”是绘画活动，与“下载”没有反义关系。"}], "correct_answer": "上传", "explanations": {"上传": "正确：“上传”与“下载”是反义词，下载是把网络上的文件拿到自己的设备，上传是把自己设备上的文件送到网络上。", "睡觉": "“睡觉”是日常动作，与“下载”没有反义关系。", "散步": "“散步”是走路休息，与“下载”没有反义关系。", "画画": "“画画”是绘画活动，与“下载”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上传", "is_correct": true, "explanation": "正确：“上传”与“下载”是反义词，下载是把网络上的文件拿到自己的设备，上传是把自己设备上的文件送到网络上。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是运动，与“下载”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”是阅读活动，与“下载”没有反义关系。"}, {"text": "做饭", "is_correct": false, "explanation": "“做饭”是烹饪活动，与“下载”没有反义关系。"}], "correct_answer": "上传", "explanations": {"上传": "正确：“上传”与“下载”是反义词，下载是把网络上的文件拿到自己的设备，上传是把自己设备上的文件送到网络上。", "跑步": "“跑步”是运动，与“下载”没有反义关系。", "读书": "“读书”是阅读活动，与“下载”没有反义关系。", "做饭": "“做饭”是烹饪活动，与“下载”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过网络将文件、软件等从远处传送到自己的设备上。", "primary_collocate": null, "pronunciation": "xià zài", "ipa": "ɕja˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他从公司服务器下载了这份文件。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下载这个软件需要连接网络。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网速太慢，文件下载了一个小时。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从邮箱里下载了客户发来的合同。", "target_word": "下载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份资料下载到你的电脑上。", "target_word": "下载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下载过很多学习用的软件。", "target_word": "下载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点这个按钮，就可以下载文件。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络断了，文件没有下载完。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要求员工从网站下载新版软件。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你下载的那个文件打不开。", "target_word": "下载", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下载了", "label": "体标"}, {"form": "下载过", "label": "体标"}, {"form": "下载量", "label": "复合"}], "register": "中性", "sense_fingerprint": "下载：通过网络把文件、软件从服务器或远处传送到自己的设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1fc457-8ada-4586-9ab8-800b096dd014') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下载", "is_correct": true, "explanation": "正确：“下载”表示通过网络从服务器把文件拿到自己的设备上，与“从公司服务器”搭配。"}, {"text": "上传", "is_correct": false, "explanation": "语义：“上传”是把东西送到服务器上，与“从服务器”获取文件的方向相反。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”指用力分开，不能用来表示从服务器获取文件。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指分开或割开，不能用来表示从服务器获取文件。"}], "explanations": {"下载": "正确：“下载”表示通过网络从服务器把文件拿到自己的设备上，与“从公司服务器”搭配。", "上传": "语义：“上传”是把东西送到服务器上，与“从服务器”获取文件的方向相反。", "撕": "搭配：“撕”指用力分开，不能用来表示从服务器获取文件。", "切": "搭配：“切”指分开或割开，不能用来表示从服务器获取文件。"}, "sentence_index": 0, "correct_answer": "下载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把合同下载给了客户。", "explanation": "这里应该用〈寄〉。下载是从网上获取东西，不能把自己的合同送给客户。"}, {"text": "我下载了那份快递。", "explanation": "这里应该用〈签收〉。快递是实物，不能通过网络下载。"}, {"text": "我从商店下载了一台电脑。", "explanation": "这里应该用〈买〉。下载是通过网络获取，不能在商店里下载实物电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下载", "is_correct": true, "explanation": "正确：“下载”表示通过按钮把文件拿到设备上，与“就可以……文件”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能用来搭配“文件”。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用来搭配“文件”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洗，用在“文件”上意思不对。"}], "explanations": {"下载": "正确：“下载”表示通过按钮把文件拿到设备上，与“就可以……文件”搭配。", "喝": "搭配：“喝”的对象是液体，不能用来搭配“文件”。", "煮": "搭配：“煮”用于食物，不能用来搭配“文件”。", "洗": "语义：“洗”指清洗，用在“文件”上意思不对。"}, "sentence_index": 6, "correct_answer": "下载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把照片下载在了墙上。", "explanation": "这里应该用〈贴〉。下载是把网上的东西拿到设备里，不能下载到墙上。"}, {"text": "他从树上下载了一个苹果。", "explanation": "这里应该用〈摘〉。下载只用于网上的文件和软件，不能用于树上的苹果。"}, {"text": "农民在田里下载了麦子。", "explanation": "这里应该用〈收割〉。下载只用于网上的文件和软件，不能用于田里的庄稼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从网站下载的一个新软件。", "corrected_sentence": "他从网站下载了一个新软件。", "error_description": "错误：动态助词“了”写成了“的”，句子缺少谓语，成了名词短语。正确：应说“下载了一个新软件”，用“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "照片已经下载电脑里了。", "corrected_sentence": "照片已经下载到电脑里了。", "error_description": "错误：表示文件传送到某处，终点要用介词“到”，这里漏掉了“到”，不能说“下载电脑里”。正确：应说“下载到电脑里了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b07d782-30c7-4f8f-bb66-34d0efb7eb3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
