INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指过去或将来的某个时间。", "primary_collocate": null, "pronunciation": "nà shí", "ipa": "na˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "明年春天我毕业，那时我想去旅行。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我就回国了，那时再见面吧。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你长大，那时你会明白的。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时的学校没有电脑。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五年以后，那时我可能住在上海。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时他刚到北京，一个朋友也没有。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们三年后上大学，那时家里会很安静。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到了那时就知道了。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们第一次见面是在冬天，那时下着雪。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时的我不爱读书。", "target_word": "那时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那時", "label": "繁体"}, {"form": "那时候", "label": "复合"}], "register": "中性", "sense_fingerprint": "那时：指前文提到的过去或将来的某个时间点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那时", "is_correct": true, "explanation": "正确：“那时”指明年以后的某个时候，与“明年春天我毕业”的将来语境相合。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指已经过去的一年，与“明年春天我毕业”的将来语境冲突。"}, {"text": "上个星期", "is_correct": false, "explanation": "搭配：“上个星期”指已经过去的一周，不能与“明年春天我毕业”并列作时间状语。"}, {"text": "小时候", "is_correct": false, "explanation": "语义：“小时候”指童年，与“明年春天我毕业”所说的未来计划冲突。"}], "explanations": {"那时": "正确：“那时”指明年以后的某个时候，与“明年春天我毕业”的将来语境相合。", "去年": "语义：“去年”指已经过去的一年，与“明年春天我毕业”的将来语境冲突。", "上个星期": "搭配：“上个星期”指已经过去的一周，不能与“明年春天我毕业”并列作时间状语。", "小时候": "语义：“小时候”指童年，与“明年春天我毕业”所说的未来计划冲突。"}, "sentence_index": 0, "correct_answer": "那时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去那时吃饭。", "explanation": "这里应该用〈那里〉。“去”后面要接地点，而“那时”只表示时间。"}, {"text": "我住在那时。", "explanation": "这里应该用〈那里〉。“住在”后要接地点，而“那时”只表示时间，不能指地方。"}, {"text": "我的猫叫那时。", "explanation": "语义：“那时”是时间词，不是名字，不能用来给动物命名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那时", "is_correct": true, "explanation": "正确：“那时”指孩子们上大学以后的某个时候，与“三年后上大学”的将来语境相合。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指过去，与“三年后上大学”的将来语境冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指已经过去的一天，与“三年后”的将来安排冲突。"}, {"text": "从前", "is_correct": false, "explanation": "语域：“从前”多用于叙述往事，与“孩子们三年后上大学”这种口语化的将来安排不搭配。"}], "explanations": {"那时": "正确：“那时”指孩子们上大学以后的某个时候，与“三年后上大学”的将来语境相合。", "以前": "语义：“以前”指过去，与“三年后上大学”的将来语境冲突。", "昨天": "语义：“昨天”指已经过去的一天，与“三年后”的将来安排冲突。", "从前": "语域：“从前”多用于叙述往事，与“孩子们三年后上大学”这种口语化的将来安排不搭配。"}, "sentence_index": 6, "correct_answer": "那时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把那时放进了书包。", "explanation": "语义：“那时”是时间词，不能作“放”的对象，这里应该换成〈笔〉之类的具体物品。"}, {"text": "你要是不同意，那时我就不去了。", "explanation": "这里应该用〈那么〉。“那时”只表示时间，不能表示“这样的话”的推论。"}, {"text": "那时打了我一拳，我很生气。", "explanation": "语义：“那时”是时间词，不能作动作的施事。这里应该换成指人的词，如〈他〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时我住在学校那时。", "corrected_sentence": "那时我住在学校。", "error_description": "错误形式：「那时我住在学校那时。」正确形式：「那时我住在学校。」“那时”只需在句首出现一次，句末重复的“那时”是多余的，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那时我还很没有工作。", "corrected_sentence": "那时我还没有工作。", "error_description": "错误形式：「那时我还很没有工作。」正确形式：「那时我还没有工作。」“很”是程度副词，不能修饰否定词“没有”，这里多出的“很”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
