INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88637, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "长年是一年到头，很多年都这样。", "primary_collocate": null, "pronunciation": "cháng nián", "ipa": "tʂʰaŋ˧˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "老人长年睡得很早。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的湖长年结着冰。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈长年工作，没有休息过。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长年看书，眼睛不太好。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生长年站着工作，很累。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方长年都很绿。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥长年住在国外。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民长年在地里干活。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店长年卖同一种面包。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她长年穿着一件蓝衣服。", "target_word": "长年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "長年", "label": "繁体"}, {"form": "长年累月", "label": "复合"}], "register": "中性", "sense_fingerprint": "长年：整年、多年都这样，说明情况长期不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88637, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "长年", "is_correct": true, "explanation": "正确：“长年”表示长期一直如此，与“老人长年睡得很早”的长期习惯相合。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指事情忽然发生，不能描述老人长期的睡眠习惯。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上发生，与“长年”所说的长期习惯不合。"}, {"text": "一时", "is_correct": false, "explanation": "搭配：“一时”指一段短时间，不与“睡得很早”这种长期习惯搭配。"}], "explanations": {"长年": "正确：“长年”表示长期一直如此，与“老人长年睡得很早”的长期习惯相合。", "突然": "语义：“突然”指事情忽然发生，不能描述老人长期的睡眠习惯。", "立刻": "语义：“立刻”指马上发生，与“长年”所说的长期习惯不合。", "一时": "搭配：“一时”指一段短时间，不与“睡得很早”这种长期习惯搭配。"}, "sentence_index": 0, "correct_answer": "长年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他收到消息后长年去了医院。", "explanation": "这里应该用〈立刻〉。“长年”表示长期一直如此，不能修饰“去医院”这样的一次性动作。"}, {"text": "他长年很快就做完了作业。", "explanation": "这里应该用〈马上〉。“长年”表示长时间持续，不能和表示短时间内完成的说法搭配。"}, {"text": "他长年看了三次书。", "explanation": "这里的“长年”表示持续不断，这里却限定了一个具体的次数，应该用〈一共〉或〈每年〉这类表示数量或周期的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88637, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长年", "is_correct": true, "explanation": "正确：“长年”表示多年一直如此，与“我哥哥长年住在国外”的长期状态相合。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指就在现场，不能修饰“住在国外”这种长期居住的状态。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”指急忙，不能用来修饰长期居住的状态。"}, {"text": "顺便", "is_correct": false, "explanation": "搭配：“顺便”修饰顺手做的动作，不与“住在国外”这种长期状态搭配。"}], "explanations": {"长年": "正确：“长年”表示多年一直如此，与“我哥哥长年住在国外”的长期状态相合。", "当场": "语义：“当场”指就在现场，不能修饰“住在国外”这种长期居住的状态。", "连忙": "语义：“连忙”指急忙，不能用来修饰长期居住的状态。", "顺便": "搭配：“顺便”修饰顺手做的动作，不与“住在国外”这种长期状态搭配。"}, "sentence_index": 6, "correct_answer": "长年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我偶尔长年去一次公园。", "explanation": "这里应该用〈有时候〉。“长年”表示一年到头、持续不断，不能和表示不常发生的词搭配。"}, {"text": "他长年在这个房间待了一会儿。", "explanation": "这里应该用〈暂时〉。“长年”表示多年持续，不能用来说很短的时间。"}, {"text": "他长年明天去北京。", "explanation": "这里应该用〈某一天〉之类的时间词。“长年”表示长期持续，不能指一个具体的将来日子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐在家很长年做饭。", "corrected_sentence": "我姐姐在家长年做饭。", "error_description": "错误形式：「我姐姐在家很长年做饭。」正确形式：「我姐姐在家长年做饭。」“长年”是副词，不能被程度副词“很”修饰，这里多出的“很”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我奶奶长年了在公园散步。", "corrected_sentence": "我奶奶长年在公园散步。", "error_description": "错误形式：「我奶奶长年了在公园散步。」正确形式：「我奶奶长年在公园散步。」“了”是完成标记，不能加在“长年”后面，这里多出的“了”使句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
