INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电台是发出声音节目的地方，人们用收音机就能听到。", "primary_collocate": null, "pronunciation": "diàn tái", "ipa": "tjɛn˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我在车里听电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上都听电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台晚上有很好听的音乐。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收音机里的电台声音很清楚。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢听电台里的故事。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开收音机，找到了一个电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台白天放新闻，晚上放音乐。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里信号不好，听不到电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候，爸爸常常听电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台的信号很弱，我常常收不到。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電台", "label": "繁体"}, {"form": "广播电台", "label": "复合"}], "register": "中性", "sense_fingerprint": "电台：用收音机收听的、发出声音节目的广播台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "搭配：“听”只搭配可以听的声音或节目，“报纸”是用来读的，不能说“听报纸”。"}, {"text": "电台", "is_correct": true, "explanation": "“电台”指播送声音节目的频道，人们用收音机收听，与“听”搭配。"}, {"text": "杂志", "is_correct": false, "explanation": "搭配：“杂志”是印刷品，要用“读”，不能与“听”搭配。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：镜子不能播放声音节目，句子说的是在车里收听。"}], "explanations": {"报纸": "搭配：“听”只搭配可以听的声音或节目，“报纸”是用来读的，不能说“听报纸”。", "电台": "“电台”指播送声音节目的频道，人们用收音机收听，与“听”搭配。", "杂志": "搭配：“杂志”是印刷品，要用“读”，不能与“听”搭配。", "镜子": "语义：镜子不能播放声音节目，句子说的是在车里收听。"}, "sentence_index": 0, "correct_answer": "电台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们城市里有一只电台。", "explanation": "量词“只”不用于电台，此处应用“家”或“个”。"}, {"text": "我把电台的画面调亮了一些。", "explanation": "这里应该用〈电视〉。电台只播放声音节目，没有画面，不能说“调亮电台的画面”。"}, {"text": "我每天晚上看电台。", "explanation": "这里应该用〈电视〉。电台只能听，不能用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "语义：电影放映的是影片，句子中“白天放新闻，晚上放音乐”是播送节目，不符合电影的内容。"}, {"text": "电台", "is_correct": true, "explanation": "“电台”指播放节目的频道，句中“白天放新闻，晚上放音乐”指它的节目安排。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不能播放新闻和音乐。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“放”可以用于节目、音乐，不能用于“窗户”。"}], "explanations": {"电影": "语义：电影放映的是影片，句子中“白天放新闻，晚上放音乐”是播送节目，不符合电影的内容。", "电台": "“电台”指播放节目的频道，句中“白天放新闻，晚上放音乐”指它的节目安排。", "花园": "语义：花园不能播放新闻和音乐。", "窗户": "搭配：“放”可以用于节目、音乐，不能用于“窗户”。"}, "sentence_index": 6, "correct_answer": "电台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈每天都在电台里做饭。", "explanation": "这里应该用〈厨房〉。电台是播送节目的地方，做饭要在厨房进行，不能在电台里做饭。"}, {"text": "我们城市里有一位电台。", "explanation": "量词“位”用于人，电台不能用“位”来计数，此处应用“家”或“个”。"}, {"text": "他打电台说今天会下雨。", "explanation": "这里应该用〈电话〉。“打电话”可以打给人或机构，“打电台”不这么说，收听电台要用“听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天早上在厨房看电台。", "corrected_sentence": "我每天早上在厨房听电台。", "error_description": "错误形式“看电台”，正确形式“听电台”。电台播送的是声音节目，要用“听”，不能用“看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐每天晚上都听一只电台的音乐节目。", "corrected_sentence": "我姐姐每天晚上都听电台的音乐节目。", "error_description": "错误形式在“电台”前多用了量词“一只”，正确形式直接说“电台的音乐节目”。“电台”前不用“只”，这里多余的量词要删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
