INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "广播电台的简称，用无线电广播节目的机构。", "primary_collocate": null, "pronunciation": "diàn tái", "ipa": "tjɛn˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "她在电台工作，是一名主持人。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电台成立了二十年。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台请我去讲我的故事。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给电台打电话，想点一首歌。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市有三家电台。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想去电台当主持人。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台的工作人员都很忙。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电台邀请了一位老师来做节目。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家电台的办公室在市中心。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电台做了十年新闻工作。", "target_word": "电台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "電台", "label": "繁体"}, {"form": "广播电台", "label": "复合"}], "register": "中性", "sense_fingerprint": "电台：广播电台这个机构，有主持人和工作人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "医生", "is_correct": false, "explanation": "搭配：“在……工作”后接工作场所，“医生”是职业，不指地点，不能说“在医生工作”。"}, {"text": "电台", "is_correct": true, "explanation": "“电台”指广播机构，有主持人和工作人员，此处说她在电台工作，是主持人。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不播送节目，不能与“主持人”搭配。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不播送节目，不能与“主持人”搭配。"}], "explanations": {"医生": "搭配：“在……工作”后接工作场所，“医生”是职业，不指地点，不能说“在医生工作”。", "电台": "“电台”指广播机构，有主持人和工作人员，此处说她在电台工作，是主持人。", "超市": "语义：超市不播送节目，不能与“主持人”搭配。", "银行": "语义：银行不播送节目，不能与“主持人”搭配。"}, "sentence_index": 0, "correct_answer": "电台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去电台买了一些蔬菜。", "explanation": "这里应该用〈超市〉。电台是广播机构，不卖东西，买菜要去超市。"}, {"text": "我们城市有一条电台。", "explanation": "量词“条”多用于长条形事物，广播机构应用“家”，不说“一条电台”。"}, {"text": "他在电台喂了十年老虎。", "explanation": "这里应该用〈动物园〉。电台是广播机构，不饲养动物，喂老虎要在动物园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“……的工作人员”指某个机构的员工，“天气”不是机构，不能这样搭配。"}, {"text": "电台", "is_correct": true, "explanation": "“电台”指广播机构，有工作人员，此处说的是电台的工作人员。"}, {"text": "学生", "is_correct": false, "explanation": "搭配：“学生”是人，不能直接说“学生的工作人员”，表示机构的员工时用“学生会”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能作为机构的名称来修饰“工作人员”。"}], "explanations": {"天气": "语义：“……的工作人员”指某个机构的员工，“天气”不是机构，不能这样搭配。", "电台": "“电台”指广播机构，有工作人员，此处说的是电台的工作人员。", "学生": "搭配：“学生”是人，不能直接说“学生的工作人员”，表示机构的员工时用“学生会”。", "感冒": "语义：“感冒”是疾病，不能作为机构的名称来修饰“工作人员”。"}, "sentence_index": 6, "correct_answer": "电台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电台看了十年病。", "explanation": "这里应该用〈医院〉。“看病”要在医院进行，电台是广播机构，不能在那里看病。"}, {"text": "这家电台每年生产两万辆汽车。", "explanation": "这里应该用〈汽车厂〉。电台是广播机构，不生产汽车，生产汽车的是工厂。"}, {"text": "他给电台上了一堂数学课。", "explanation": "这里应该用〈学校〉。电台是广播机构，不能成为上课的对象，上数学课要在学校或补习班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一台电台的主持人。", "corrected_sentence": "他是一家电台的主持人。", "error_description": "错误形式“一台电台”，正确形式“一家电台”。作为广播机构，电台的量词是“家”，“台”用于设备。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我朋友在一台电台实习。", "corrected_sentence": "我朋友在一家电台实习。", "error_description": "错误形式“一台电台”，正确形式“一家电台”。作为广播机构，电台的量词是“家”，“台”用于设备。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
