INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88649, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "预期是事情还没发生，先想好它会是什么样。", "primary_collocate": null, "pronunciation": "yù qī", "ipa": "y˥˩ t͡ɕʰi˥", "syllable_count": 2, "sentences": [{"text": "这次考试的成绩比我的预期好。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的效果达到了大家的预期。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的销量低于公司的预期。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个结果不符合我的预期。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这份工作的预期很高。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜超出了我的预期。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的预期和现实不一样。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结果完全在预期之中。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这次旅行没有太高的预期。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们的努力换来了好于预期的结果。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：事前想好的结果或期望，可与结果比较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：预期（yù qī），意思是事情发生前想好的结果或期望。"}, {"text": "雨期", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨季。"}, {"text": "语气", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）、qì（第四声）与 qī（第一声）声调都不同，意思是说话的口气。"}, {"text": "玉器", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是玉制的器物。"}, {"text": "续期", "is_correct": false, "explanation": "xù 与 yù 的开头辅音不同（x 与零声母 y），意思是延长期限。"}, {"text": "误期", "is_correct": false, "explanation": "wù 与 yù 的韵母不同（u 与 ü），意思是耽误了期限。"}], "explanations": {"预期": "正确：预期（yù qī），意思是事情发生前想好的结果或期望。", "雨期": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨季。", "语气": "yǔ（第三声）与 yù（第四声）、qì（第四声）与 qī（第一声）声调都不同，意思是说话的口气。", "玉器": "qì（第四声）与 qī（第一声）声调不同，意思是玉制的器物。", "续期": "xù 与 yù 的开头辅音不同（x 与零声母 y），意思是延长期限。", "误期": "wù 与 yù 的韵母不同（u 与 ü），意思是耽误了期限。"}, "sentence_index": null, "correct_answer": "预期"}, "level_3": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：“预期”是名词，指事前想好的结果，与“比我的……好”的比较相配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：考试成绩与年龄不能比较好坏。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”不能用“好”来评价，应说“高”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：考试成绩与脾气没有可比性。"}], "explanations": {"预期": "正确：“预期”是名词，指事前想好的结果，与“比我的……好”的比较相配。", "年龄": "语义：考试成绩与年龄不能比较好坏。", "身高": "搭配：“身高”不能用“好”来评价，应说“高”。", "脾气": "语义：考试成绩与脾气没有可比性。"}, "sentence_index": 0, "correct_answer": "预期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张优惠券的预期是三个月。", "explanation": "这里应该用〈有效期〉。预期指对结果的料想，不表示票券能使用的时限，要用有效期。"}, {"text": "这次比赛的预期是三局两胜。", "explanation": "这里应该用〈赛制〉。预期指对结果的料想，不表示比赛的规则，三局两胜是赛制。"}, {"text": "这次活动的预期是打五折。", "explanation": "这里应该用〈折扣〉。预期指对结果的料想，不表示价格上的优惠，打折要说折扣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88649, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：“预期”是名词，指事前想好的结果，与“和现实不一样”相配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是能与现实相比较的设想，句子无法成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不是事前的设想，与“和现实不一样”不搭。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能与“和现实不一样”组成表示设想的句子。"}], "explanations": {"预期": "正确：“预期”是名词，指事前想好的结果，与“和现实不一样”相配。", "颜色": "语义：“颜色”不是能与现实相比较的设想，句子无法成立。", "体重": "语义：体重是身体的数值，不是事前的设想，与“和现实不一样”不搭。", "脚步": "搭配：“脚步”不能与“和现实不一样”组成表示设想的句子。"}, "sentence_index": 6, "correct_answer": "预期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张票的预期是第三排。", "explanation": "这里应该用〈座位〉。预期指对结果的料想，不表示座位所在。"}, {"text": "这件衣服的预期是大号。", "explanation": "这里应该用〈尺码〉。预期指对结果的料想，不表示衣服的尺寸，要用尺码。"}, {"text": "这辆车的预期是三个轮子。", "explanation": "这里应该用〈结构〉。预期指对结果的料想，不表示车辆的构造，要用结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个结果超出了大家预期。", "corrected_sentence": "这个结果超出了大家的预期。", "error_description": "名词“预期”前要用“的”连接定语“大家”，应说“大家的预期”；去掉“的”，“大家预期”就成了动词短语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这次比赛的预期高很。", "corrected_sentence": "他对这次比赛的预期很高。", "error_description": "程度副词“很”应放在形容词“高”前面，说“预期很高”；“预期高很”语序错误，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
