INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先期待或料想。", "primary_collocate": null, "pronunciation": "yù qī", "ipa": "y˥˩ t͡ɕʰi˥", "syllable_count": 2, "sentences": [{"text": "我预期今年的销量会增加。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预期明年利润会上升。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预期会遇到很多困难。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家预期下个月天气会变冷。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们预期这场比赛会很精彩。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预期病人三天后能出院。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板预期这个月会有很多客人。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人预期他会赢。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早就预期到考试会很难。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家预期明天会下大雨。", "target_word": "预期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词：事情发生前先料想或期待结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：预期（yù qī），意思是事先期待或料想。"}, {"text": "雨期", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨季。"}, {"text": "语气", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）、qì（第四声）与 qī（第一声）声调都不同，意思是说话的口气。"}, {"text": "玉器", "is_correct": false, "explanation": "qì（第四声）与 qī（第一声）声调不同，意思是玉制的器物。"}, {"text": "续期", "is_correct": false, "explanation": "xù 与 yù 的开头辅音不同（x 与零声母 y），意思是延长期限。"}, {"text": "误期", "is_correct": false, "explanation": "wù 与 yù 的韵母不同（u 与 ü），意思是耽误了期限。"}], "explanations": {"预期": "正确：预期（yù qī），意思是事先期待或料想。", "雨期": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨季。", "语气": "yǔ（第三声）与 yù（第四声）、qì（第四声）与 qī（第一声）声调都不同，意思是说话的口气。", "玉器": "qì（第四声）与 qī（第一声）声调不同，意思是玉制的器物。", "续期": "xù 与 yù 的开头辅音不同（x 与零声母 y），意思是延长期限。", "误期": "wù 与 yù 的韵母不同（u 与 ü），意思是耽误了期限。"}, "sentence_index": null, "correct_answer": "预期"}, "level_3": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：“预期”表示事先料想，与“会增加”的推测相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，销量不能吃。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场地或物品，销量不能打扫。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指回想过去，与表示将来的“会增加”矛盾。"}], "explanations": {"预期": "正确：“预期”表示事先料想，与“会增加”的推测相符。", "吃": "搭配：“吃”的对象是食物，销量不能吃。", "打扫": "搭配：“打扫”的对象是场地或物品，销量不能打扫。", "回忆": "语义：“回忆”指回想过去，与表示将来的“会增加”矛盾。"}, "sentence_index": 0, "correct_answer": "预期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力预期那扇门，门终于开了。", "explanation": "这里应该用〈推〉。预期是事先料想，不表示用力移动物体，推门要用推。"}, {"text": "我们已经预期了两间房间。", "explanation": "这里应该用〈预订〉。预期是料想结果，不表示事先定下房间，订房要用预订。"}, {"text": "我们把行李预期到楼上。", "explanation": "这里应该用〈搬〉。预期是料想，不表示把东西从一处挪到另一处，搬行李要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预期", "is_correct": true, "explanation": "正确：“预期”表示事先料想，与“会有很多客人”的推测相符。"}, {"text": "招待", "is_correct": false, "explanation": "搭配：“招待”的对象是人，不能与“会有很多客人”组成这样的句子。"}, {"text": "赶走", "is_correct": false, "explanation": "语义：“赶走”是把人驱离，与“会有很多客人”的意思相反。"}, {"text": "扣除", "is_correct": false, "explanation": "搭配：“扣除”的对象是金额或数量，不能说扣除客人会有很多。"}], "explanations": {"预期": "正确：“预期”表示事先料想，与“会有很多客人”的推测相符。", "招待": "搭配：“招待”的对象是人，不能与“会有很多客人”组成这样的句子。", "赶走": "语义：“赶走”是把人驱离，与“会有很多客人”的意思相反。", "扣除": "搭配：“扣除”的对象是金额或数量，不能说扣除客人会有很多。"}, "sentence_index": 6, "correct_answer": "预期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在树林里预期丢失的钥匙。", "explanation": "这里应该用〈寻找〉。预期是料想结果，不表示到处找东西。"}, {"text": "我们昨天预期了一台新电脑。", "explanation": "这里应该用〈购买〉。预期是料想，不表示买下东西，要用购买。"}, {"text": "工人预期了那台坏掉的机器。", "explanation": "这里应该用〈修理〉。预期表示料想，不表示把机器修好，修机器要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动他预期得很成功。", "corrected_sentence": "这次活动他预期会很成功。", "error_description": "“预期”后不能直接接补语“得很成功”，应改为“预期会很成功”，用“会”引出后面的小句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没预期了他会来。", "corrected_sentence": "我没预期他会来。", "error_description": "“没”表示否定，不能与“了”同用：否定句中的“没”后面不加“了”，应说“我没预期他会来”，不说“我没预期了他会来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
