INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88655, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "没有什么就是一点儿也没有，所指的人或东西一个也不存在。", "primary_collocate": null, "pronunciation": "méi yǒu shén me", "ipa": "meɪ˧˥ joʊ˨˩˦ ʂən˧˥ mə", "syllable_count": 4, "sentences": [{"text": "冰箱里没有什么吃的。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天没有什么要做的。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的房间里没有什么东西。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有什么好看的。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我口袋里没有什么钱。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上没有什么书。", "target_word": "没有什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对这件事没有什么办法。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天的电影没有什么意思。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里没有什么人。", "target_word": "没有什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里没有什么可怕的。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "几乎没有任何东西或内容,泛指无", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有什么", "is_correct": true, "explanation": "正确：“没有什么”表示冰箱里一样能吃的东西也没有，符合句意。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，不指食物，“冰箱里别人吃的”说不通。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子会变成疑问句，与“冰箱里”的陈述不符。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能与“吃的”这类食物搭配。"}], "explanations": {"没有什么": "正确：“没有什么”表示冰箱里一样能吃的东西也没有，符合句意。", "别人": "语义：“别人”指他人，不指食物，“冰箱里别人吃的”说不通。", "谁": "语义：“谁”是疑问代词，句子会变成疑问句，与“冰箱里”的陈述不符。", "大家": "搭配：“大家”指人群，不能与“吃的”这类食物搭配。"}, "sentence_index": 0, "correct_answer": "没有什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的菜太多了，没有什么可以点的。", "explanation": "这里应该用〈有很多〉。没有什么表示一点儿也没有，与“菜太多了”矛盾；说菜多要用“有很多可以点的”。"}, {"text": "我今天很开心，没有什么可高兴的。", "explanation": "这里应该用〈有〉。没有什么可高兴的表示没有值得高兴的事，与“很开心”矛盾；想说有值得高兴的事，要说“有很多可高兴的”。"}, {"text": "这本书的内容非常丰富，每一页都有很多字，但书里没有什么字。", "explanation": "这里应该用〈有很多〉。没有什么字表示一个字也没有，与“内容非常丰富，每一页都有很多字”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有什么", "is_correct": true, "explanation": "正确：“没有什么办法”表示一点办法也没有，符合句意。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”是疑问代词，句子会变成疑问，不符合陈述语气。"}, {"text": "人家", "is_correct": false, "explanation": "搭配：“人家”指他人，不能直接修饰“办法”，“人家办法”说不通。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”作定语需带“的”，“自己办法”不能成立。"}], "explanations": {"没有什么": "正确：“没有什么办法”表示一点办法也没有，符合句意。", "哪些": "语义：“哪些”是疑问代词，句子会变成疑问，不符合陈述语气。", "人家": "搭配：“人家”指他人，不能直接修饰“办法”，“人家办法”说不通。", "自己": "搭配：“自己”作定语需带“的”，“自己办法”不能成立。"}, "sentence_index": 6, "correct_answer": "没有什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个公园每天都有很多游客，可是园里没有什么人。", "explanation": "这里应该用〈有很多〉。没有什么人表示一个人也没有，与“每天都有很多游客”矛盾。"}, {"text": "这次考试我考得很好，我对它没有什么办法。", "explanation": "这里应该用〈有〉。没有什么办法表示一点办法也没有，与“考得很好”矛盾。"}, {"text": "我的电脑运行很快，它没有什么速度。", "explanation": "这里应该用〈快〉。没有什么速度表示一点速度也没有，与“运行很快”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间里没有什么的家具。", "corrected_sentence": "这个房间里没有什么家具。", "error_description": "错误：在“什么”和“家具”之间多加了“的”。正确：“没有什么”直接修饰名词，应说“没有什么家具”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书包里很没有什么文具。", "corrected_sentence": "书包里没有什么文具。", "error_description": "错误：在“没有什么”前多加了程度副词“很”。正确：“没有什么”表示一点也没有，不能被“很”修饰，应说“书包里没有什么文具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
