INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88656, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "表示不存在任何事物,或表示不要紧、不在乎。", "primary_collocate": null, "pronunciation": "méi yǒu shén me", "ipa": "meɪ˧˥ joʊ˨˩˦ ʂən˧˥ mə", "syllable_count": 4, "sentences": [{"text": "没有什么,你别担心。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有什么,我自己可以做。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“对不起。”“没有什么。”", "target_word": "没有什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "摔了一下,没有什么,不疼。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "迟到五分钟没有什么,别着急。", "target_word": "没有什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点小错没有什么,下次小心就好。", "target_word": "没有什么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这没有什么大不了的。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对我来说,这没有什么。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有什么比健康更重要。", "target_word": "没有什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界上没有什么能让他放弃。", "target_word": "没有什么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示不要紧、不在乎,或不存在任何事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88656, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有什么", "is_correct": true, "explanation": "正确：“没有什么，你别担心”表示不要紧，符合句意。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子会变成疑问，不能表示“不要紧”。"}, {"text": "哪些", "is_correct": false, "explanation": "语义：“哪些”表示疑问或指定范围，不能表示“不要紧”。"}, {"text": "每个", "is_correct": false, "explanation": "搭配：“每个”后面需要名词，不能单独出现在这里。"}], "explanations": {"没有什么": "正确：“没有什么，你别担心”表示不要紧，符合句意。", "谁": "语义：“谁”是疑问代词，句子会变成疑问，不能表示“不要紧”。", "哪些": "语义：“哪些”表示疑问或指定范围，不能表示“不要紧”。", "每个": "搭配：“每个”后面需要名词，不能单独出现在这里。"}, "sentence_index": 0, "correct_answer": "没有什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子上摆了三本书，但上面没有什么书。", "explanation": "这里应该用〈有〉。没有什么书表示一本书也没有，与“摆了三本书”矛盾。"}, {"text": "这件事很要紧，它没有什么。", "explanation": "没有什么表示不要紧，与“很要紧”直接矛盾。"}, {"text": "这个箱子里装满了衣服，我却说里面没有什么衣服。", "explanation": "这里应该用〈有很多〉。没有什么衣服表示一件也没有，与“装满了衣服”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有什么", "is_correct": true, "explanation": "正确：“没有什么大不了的”表示不算什么大事，符合句意。"}, {"text": "哪样", "is_correct": false, "explanation": "语义：“哪样”是疑问代词，句子会变成疑问，不能表示“不算什么”。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，不能指“这”这件事，句子说不通。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指人群，不能作“这”的修饰语来表示事情的程度。"}], "explanations": {"没有什么": "正确：“没有什么大不了的”表示不算什么大事，符合句意。", "哪样": "语义：“哪样”是疑问代词，句子会变成疑问，不能表示“不算什么”。", "别人": "语义：“别人”指他人，不能指“这”这件事，句子说不通。", "大家": "搭配：“大家”指人群，不能作“这”的修饰语来表示事情的程度。"}, "sentence_index": 6, "correct_answer": "没有什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天生产上万件产品，我却说它没有什么产品。", "explanation": "这里应该用〈有〉。没有什么产品表示一件也没有，与“每天生产上万件产品”矛盾。"}, {"text": "他很努力，他的决心没有什么。", "explanation": "这里应该用〈很大〉。没有什么表示不要紧，与“很努力”矛盾；说决心大要用“很大”。"}, {"text": "这个小镇有很多景点，但镇上没有什么景点可以去。", "explanation": "这里应该用〈有很多〉。没有什么景点表示一个景点也没有，与“有很多景点”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次失败很没有什么，下次努力就好。", "corrected_sentence": "这次失败没有什么，下次努力就好。", "error_description": "错误：在“没有什么”前多加了程度副词“很”。正确：“没有什么”表示不要紧，不能被“很”修饰，应说“这次失败没有什么，下次努力就好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这事不没有什么大不了的。", "corrected_sentence": "这事没有什么大不了的。", "error_description": "错误：在“没有什么”前多加了否定词“不”，形成“不没有”的双重否定，句意混乱。正确：应说“这事没有什么大不了的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
