INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "为何是问原因,就是为什么。", "primary_collocate": null, "pronunciation": "wèi hé", "ipa": "weɪ˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "她为何一直看着窗外？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为何要把门关上？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问妈妈，月亮为何会跟着人走。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为何不愿意跟我们去？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不懂，你为何这么做。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为何下雨天路上人这么少？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为何换了工作？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为何对我说谢谢？", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上没说这座桥为何建在这里。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事为何会这样，我想不明白。", "target_word": "为何", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语疑问词，问原因，就是为什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为何", "is_correct": true, "explanation": "为何是疑问代词，问原因，相当于“为什么”，此处问“一直看着窗外”的原因。"}, {"text": "何时", "is_correct": false, "explanation": "语义：“何时”问时间，句子问的是原因，不是时间。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”问方式，句子问的是原因，不是方式。"}, {"text": "如何", "is_correct": false, "explanation": "搭配：“如何”一般不用来问“一直看着”这类持续动作的原因，此处用“为何”。"}], "explanations": {"为何": "为何是疑问代词，问原因，相当于“为什么”，此处问“一直看着窗外”的原因。", "何时": "语义：“何时”问时间，句子问的是原因，不是时间。", "怎样": "语义：“怎样”问方式，句子问的是原因，不是方式。", "如何": "搭配：“如何”一般不用来问“一直看着”这类持续动作的原因，此处用“为何”。"}, "sentence_index": 0, "correct_answer": "为何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的歌唱得为何？", "explanation": "这里应该用〈怎么样〉：她的歌唱得怎么样？“为何”只问原因，不问状态。"}, {"text": "会议为何地点举行？", "explanation": "这里应该用〈在哪里〉：会议在哪里举行？「为何」只问原因，不能用来问地点。"}, {"text": "他是为何人？", "explanation": "这里应该用〈谁〉：他是谁？「为何」只问原因，不能用来问人的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为何", "is_correct": true, "explanation": "为何是疑问代词，问原因，相当于“为什么”，此处问“换了工作”的原因。"}, {"text": "几时", "is_correct": false, "explanation": "语义：“几时”问时间，不问原因。"}, {"text": "哪次", "is_correct": false, "explanation": "语义：“哪次”问次序，不问原因。"}, {"text": "哪样", "is_correct": false, "explanation": "搭配：“哪样”问样式，不能用来问“换了工作”的原因。"}], "explanations": {"为何": "为何是疑问代词，问原因，相当于“为什么”，此处问“换了工作”的原因。", "几时": "语义：“几时”问时间，不问原因。", "哪次": "语义：“哪次”问次序，不问原因。", "哪样": "搭配：“哪样”问样式，不能用来问“换了工作”的原因。"}, "sentence_index": 6, "correct_answer": "为何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他喜欢为何水果？", "explanation": "这里应该用〈什么〉：他喜欢什么水果？“为何”只问原因，不能问种类。"}, {"text": "书架上为何几本书？", "explanation": "这里应该用〈多少〉：书架上有多少本书？「为何」只问原因，不能用来问数量。"}, {"text": "这是为何的伞？", "explanation": "这里应该用〈谁〉：这是谁的伞？“为何”只问原因，不问所属。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈为何什么这么早就出门了？", "corrected_sentence": "妈妈为何这么早就出门了？", "error_description": "错误形式：“妈妈为何什么这么早就出门了”。正确形式：“妈妈为何这么早就出门了”。“为何”已是疑问词，句中多加的“什么”造成两个疑问词叠用，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同事们为何了都离开了公司？", "corrected_sentence": "同事们为何都离开了公司？", "error_description": "错误形式：“同事们为何了都离开了公司”。正确形式：“同事们为何都离开了公司”。“为何”是疑问代词，不带“了”，后面直接接副词“都”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "“解放”指使人摆脱压迫或控制，与“统治”的支配关系相反。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中活动，与“统治”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”指用笔作画，与“统治”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "“写作”指写文章，与“统治”没有反义关系。"}], "correct_answer": "解放", "explanations": {"解放": "“解放”指使人摆脱压迫或控制，与“统治”的支配关系相反。", "游泳": "“游泳”指在水中活动，与“统治”没有反义关系。", "画画": "“画画”指用笔作画，与“统治”没有反义关系。", "写作": "“写作”指写文章，与“统治”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "“解放”指使人摆脱压迫或控制，与“统治”的支配关系相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "“跳舞”指随着音乐做动作，与“统治”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来不做事情，与“统治”没有反义关系。"}, {"text": "洗衣", "is_correct": false, "explanation": "“洗衣”指洗衣服，与“统治”没有反义关系。"}], "correct_answer": "解放", "explanations": {"解放": "“解放”指使人摆脱压迫或控制，与“统治”的支配关系相反。", "跳舞": "“跳舞”指随着音乐做动作，与“统治”没有反义关系。", "休息": "“休息”指停下来不做事情，与“统治”没有反义关系。", "洗衣": "“洗衣”指洗衣服，与“统治”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "统治是有权力的人管着一个国家或很多人。", "primary_collocate": null, "pronunciation": "tǒng zhì", "ipa": "tʰʊŋ˨˩˦ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "国王用法律统治他的人民。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有很大的权力，统治着很多人。", "target_word": "统治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家由一个女王统治。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前这里由一个大家族统治。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他统治这个国家的时候，人们过得很苦。", "target_word": "统治", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王统治人民，也要保护人民。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人想统治这座城市。", "target_word": "统治", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好国王不会只靠害怕来统治人们。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他统治了这个国家四十年。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人统治很多人，并不容易。", "target_word": "统治", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "统治着", "label": "体标"}, {"form": "统治了", "label": "体标"}, {"form": "統治", "label": "繁体"}], "register": "书面", "sense_fingerprint": "有权力的人管着国家或很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指有权力的人管着一个国家或很多人，是本题的正确答案。"}, {"text": "同质", "is_correct": false, "explanation": "tǒng zhì（第三声）与 tóng zhì（第二声）只有第一个音节声调不同，“同质”意思是性质相同。"}, {"text": "通知", "is_correct": false, "explanation": "tōng zhī 与 tǒng zhì 两个音节的声调都不同，“通知”意思是告知。"}, {"text": "统计", "is_correct": false, "explanation": "zhì（zh 声母）与 jì（j 声母）不同，“统计”意思是对数据进行汇总计算。"}], "explanations": {"统治": "“统治”指有权力的人管着一个国家或很多人，是本题的正确答案。", "同质": "tǒng zhì（第三声）与 tóng zhì（第二声）只有第一个音节声调不同，“同质”意思是性质相同。", "通知": "tōng zhī 与 tǒng zhì 两个音节的声调都不同，“通知”意思是告知。", "统计": "zhì（zh 声母）与 jì（j 声母）不同，“统计”意思是对数据进行汇总计算。"}, "sentence_index": null, "correct_answer": "统治"}, "level_3": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指凭权力管理人民，与“用法律”搭配，句意通顺。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”与“用法律”管理人民的做法相矛盾，句意不通。"}, {"text": "打扮", "is_correct": false, "explanation": "搭配：“打扮”指修饰外表，不能与“他的人民”搭配表示管理。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面要接歌曲等对象，不能说“唱他的人民”。"}], "explanations": {"统治": "“统治”指凭权力管理人民，与“用法律”搭配，句意通顺。", "逃避": "语义：“逃避”与“用法律”管理人民的做法相矛盾，句意不通。", "打扮": "搭配：“打扮”指修饰外表，不能与“他的人民”搭配表示管理。", "唱": "搭配：“唱”后面要接歌曲等对象，不能说“唱他的人民”。"}, "sentence_index": 0, "correct_answer": "统治"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗由他统治。", "explanation": "这里应该用〈创作〉。“统治”只用于国家、地区或人群，写诗要用“创作”。"}, {"text": "这只猫由她统治。", "explanation": "这里应该用〈照料〉。“统治”只用于国家、地区或人群，照顾小动物要用“照料”。"}, {"text": "他统治了这个问题一个下午。", "explanation": "这里应该用〈思考〉。“统治”不能用来形容思考问题，应说“思考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统治", "is_correct": true, "explanation": "“统治”指凭权力管理一座城市，与“那个人想”的意图相符。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“这座城市”作宾语。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体等，不能与“这座城市”搭配，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能支配城市，不能说“哭这座城市”。"}], "explanations": {"统治": "“统治”指凭权力管理一座城市，与“那个人想”的意图相符。", "睡": "配价：“睡”是不及物动词，不能带“这座城市”作宾语。", "洗": "搭配：“洗”的对象是衣物或身体等，不能与“这座城市”搭配，句意不通。", "哭": "搭配：“哭”不能支配城市，不能说“哭这座城市”。"}, "sentence_index": 6, "correct_answer": "统治"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位医生统治着这里的病人。", "explanation": "这里应该用〈照顾〉。“统治”指凭权力管理人群，医生对病人要用“照顾”。"}, {"text": "他统治了这个文件夹里的每个文件。", "explanation": "这里应该用〈整理〉。“统治”只用于国家、地区或人群，整理文件要用“整理”。"}, {"text": "他统治了这个月的工资。", "explanation": "这里应该用〈花〉。“统治”只用于国家、地区或人群，花钱要用“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这些人统治。", "corrected_sentence": "他把这些人统治了很多年。", "error_description": "“把”字句中的动词后面要有其他成分（如“了很多年”），不能只说“把这些人统治”，应为“把这些人统治了很多年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88673, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个暴君是一个残酷的统治人。", "corrected_sentence": "那个暴君是一个残酷的统治者。", "error_description": "表示“掌权统治的人”要用“统治者”，“统治人”不是常用的词，应为“统治者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
