INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "不如是比另一个差一点，没有它好。", "primary_collocate": null, "pronunciation": "bù rú", "ipa": "pu˥˩ ɻu˧˥", "syllable_count": 2, "sentences": [{"text": "我的汉语不如他好。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不如昨天热。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车不如骑车快。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟跑得不如哥哥快。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜不如那家好吃。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的字不如姐姐写得漂亮。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服不如那件便宜。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩不如以前好。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在城里不如住在乡下安静。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种面料不如那种柔软。", "target_word": "不如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词：A不如B，A比B稍差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：不如（bù rú），意思是比不上，没有它好。"}, {"text": "哺乳", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、rǔ（第三声）与 rú（第二声）声调都不同，意思是给婴儿喂奶。"}, {"text": "步入", "is_correct": false, "explanation": "rù（第四声）与 rú（第二声）声调不同，意思是走进。"}, {"text": "补入", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）、rù（第四声）与 rú（第二声）声调都不同，意思是补充加入。"}], "explanations": {"不如": "正确：不如（bù rú），意思是比不上，没有它好。", "哺乳": "bǔ（第三声）与 bù（第四声）、rǔ（第三声）与 rú（第二声）声调都不同，意思是给婴儿喂奶。", "步入": "rù（第四声）与 rú（第二声）声调不同，意思是走进。", "补入": "bǔ（第三声）与 bù（第四声）、rù（第四声）与 rú（第二声）声调都不同，意思是补充加入。"}, "sentence_index": null, "correct_answer": "不如"}, "level_3": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：“不如”表示比不上，与“他好”的比较相符。"}, {"text": "超过", "is_correct": false, "explanation": "配价：“超过”后已直接带比较对象，不能再接形容词“好”作补语。"}, {"text": "赶上", "is_correct": false, "explanation": "语义：“赶上”指追上，不表示比较优劣的结果，与“他好”不符。"}, {"text": "胜过", "is_correct": false, "explanation": "搭配：“胜过”本身已表示比较，后面不能再接“好”，应说“胜过他”。"}], "explanations": {"不如": "正确：“不如”表示比不上，与“他好”的比较相符。", "超过": "配价：“超过”后已直接带比较对象，不能再接形容词“好”作补语。", "赶上": "语义：“赶上”指追上，不表示比较优劣的结果，与“他好”不符。", "胜过": "搭配：“胜过”本身已表示比较，后面不能再接“好”，应说“胜过他”。"}, "sentence_index": 0, "correct_answer": "不如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的菜不如那家，所以这家的菜更好吃。", "explanation": "这里应该用〈强于〉。“不如那家”说这家较差，后半句却说这家更好吃，前后矛盾。"}, {"text": "这台电脑比那台快，所以不如那台。", "explanation": "这里应该用〈胜过〉。前半句说明更快，“不如”说明更差，前后矛盾。"}, {"text": "我不如他高，所以我比他高。", "explanation": "这里应该用〈高于〉。“不如”说明比不上，与后半句“我比他高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不如", "is_correct": true, "explanation": "正确：“不如”表示比不上，与“那件便宜”的比较相符。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”是选择的动作，不能用来比较价格高低。"}, {"text": "试穿", "is_correct": false, "explanation": "语义：“试穿”是试衣服的动作，与“那件便宜”的比较无关。"}, {"text": "打折", "is_correct": false, "explanation": "配价：“打折”要接金额或比例，不能以“那件”作为比较对象。"}], "explanations": {"不如": "正确：“不如”表示比不上，与“那件便宜”的比较相符。", "挑选": "语义：“挑选”是选择的动作，不能用来比较价格高低。", "试穿": "语义：“试穿”是试衣服的动作，与“那件便宜”的比较无关。", "打折": "配价：“打折”要接金额或比例，不能以“那件”作为比较对象。"}, "sentence_index": 6, "correct_answer": "不如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次比赛不如我，所以我输了。", "explanation": "这里前后矛盾：“不如”说他较差，我应当领先，后半句却说我输了，应改用〈领先〉。"}, {"text": "姐姐唱歌不如妹妹，所以妹妹唱得比姐姐差。", "explanation": "这里前后矛盾：“不如”说明前者比后者差，后半句却说后者比前者差，应改用〈超过〉。"}, {"text": "这条路不如那条路长，所以这条路比那条路还长。", "explanation": "这里应该用〈比…短〉。“不如”说前者不及后者，后半句却说更长，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹跑不如姐姐快。", "corrected_sentence": "妹妹跑得不如姐姐快。", "error_description": "“跑”后漏了补语标记“得”。应说“跑得不如姐姐快”，“得”引出“不如”的比较短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条裙子很不如那条便宜。", "corrected_sentence": "这条裙子不如那条便宜。", "error_description": "“不如”比较结构前不能加程度副词“很”，应去掉“很”，说“不如那条便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "随着是前面的事变了,后面的事也跟着变。", "primary_collocate": null, "pronunciation": "suí zhe", "ipa": "sweɪ˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "随着天气变冷,人们都穿上厚衣服。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着年龄变大,他越来越爱安静。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着时间过去,她慢慢忘了这件事。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着城市变大,路也越来越多。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着天色变黑,街上的人少了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着作业增多,他睡得越来越晚。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着价格上涨,买东西的人少了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着春天到来,花都开了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着孩子长大,父母也慢慢变老了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着天气变热,吃冰的人多了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "随着:介词:前面的事变化,后面的事跟着变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“天气变冷，人们穿厚衣服”的句意。"}, {"text": "朝", "is_correct": false, "explanation": "语义：朝表示方向，不能表示天气变化引起后续变化。"}, {"text": "沿着", "is_correct": false, "explanation": "语义：沿着表示沿路线行走，不能说“沿着天气变冷”。"}, {"text": "向", "is_correct": false, "explanation": "搭配：向后面接方向或对象，不能接“天气变冷”这样的事件。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“天气变冷，人们穿厚衣服”的句意。", "朝": "语义：朝表示方向，不能表示天气变化引起后续变化。", "沿着": "语义：沿着表示沿路线行走，不能说“沿着天气变冷”。", "向": "搭配：向后面接方向或对象，不能接“天气变冷”这样的事件。"}, "sentence_index": 0, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们随着河边散步。", "explanation": "这里应该用〈沿着〉。随着表示一件事变化时另一件事跟着变化，不表示沿路线行走。"}, {"text": "随着有你，我才没迟到。", "explanation": "这里应该用〈幸亏〉。随着表示伴随变化，不能表示幸亏这种原因。"}, {"text": "随着他是班长，大家都很听话。", "explanation": "这里应该用〈因为〉。随着表示后一事物跟着前一事物的变化而变化，“是班长”是固定状态，不会变化，表示原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“价格上涨，买东西的人少了”的句意。"}, {"text": "凭", "is_correct": false, "explanation": "语义：凭表示凭借的依据，不能说“凭价格上涨”。"}, {"text": "按照", "is_correct": false, "explanation": "语义：按照表示依据某种标准，不能说“按照价格上涨”。"}, {"text": "比", "is_correct": false, "explanation": "搭配：比用于比较两个事物，不能接“价格上涨”这样的事件。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“价格上涨，买东西的人少了”的句意。", "凭": "语义：凭表示凭借的依据，不能说“凭价格上涨”。", "按照": "语义：按照表示依据某种标准，不能说“按照价格上涨”。", "比": "搭配：比用于比较两个事物，不能接“价格上涨”这样的事件。"}, "sentence_index": 6, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事随着老师负责。", "explanation": "这里应该用〈由〉。随着表示伴随变化，不能用来引出负责的人。"}, {"text": "我随着老师问好。", "explanation": "这里应该用〈向〉。随着表示后一事物跟着前一事物变化，不能引出问好的对象，应说“向老师问好”。"}, {"text": "我们随着大家的力量完成了任务。", "explanation": "这里应该用〈依靠〉。随着表示伴随变化，不能表示凭借或依赖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "随着了收入增加，人们买的东西越来越多了。", "corrected_sentence": "随着收入增加，人们买的东西越来越多了。", "error_description": "“了”不能放在“随着”后面。正确形式是“随着收入增加”，“随着了收入增加”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "随着的年龄增长，他越来越喜欢运动。", "corrected_sentence": "随着年龄增长，他越来越喜欢运动。", "error_description": "“随着”后面不能直接加“的”。正确形式是“随着年龄增长”，“随着的年龄增长”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
