INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88690, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词,表示后一事物跟着前一事物的变化而变化。", "primary_collocate": null, "pronunciation": "suí zhe", "ipa": "sweɪ˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "随着生活变好,大家的笑容也多了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着河水上涨,小船也慢慢升高。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着她的汉语越来越好，她的朋友也多了。", "target_word": "随着", "complexity_tier": "T3", "furigana": "suí zhe", "sentence_source": "generated"}, {"text": "随着工作增加,他每天回家更晚。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着车速加快,风声也变大了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着夜越来越深,外面安静下来。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着人口增加,城里的房子越来越贵。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着技术进步,手机的功能越来越多。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着冬天到来,河水慢慢结冰了。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着学生变多,学校又盖了新楼。", "target_word": "随着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "随着:介词:后一事物跟着前一事物变化而变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“生活变好，笑容多了”的句意。"}, {"text": "凭", "is_correct": false, "explanation": "语义：凭表示凭借的依据，不能说“凭生活变好”。"}, {"text": "按照", "is_correct": false, "explanation": "语义：按照表示依据某种标准，与“生活变好”不搭。"}, {"text": "比", "is_correct": false, "explanation": "搭配：比用于比较，不能接“生活变好”这样的变化过程。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“生活变好，笑容多了”的句意。", "凭": "语义：凭表示凭借的依据，不能说“凭生活变好”。", "按照": "语义：按照表示依据某种标准，与“生活变好”不搭。", "比": "搭配：比用于比较，不能接“生活变好”这样的变化过程。"}, "sentence_index": 0, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作随着他负责。", "explanation": "这里应该用〈由〉。随着表示伴随变化，不能用来引出负责的人。"}, {"text": "随着他提醒，我才没忘。", "explanation": "这里应该用〈幸亏〉。随着表示伴随变化，不能表示幸亏这种原因。"}, {"text": "随着她是老师，大家都很尊敬她。", "explanation": "这里应该用〈因为〉。随着表示后一事物跟着前一事物的变化而变化，“是老师”是静止的状态，表示原因要用因为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随着", "is_correct": true, "explanation": "随着：表示后一件事跟着前一件事的变化而变化，符合“人口增加，房子越来越贵”的句意。"}, {"text": "朝", "is_correct": false, "explanation": "语义：朝表示方向，不能说“朝人口增加”。"}, {"text": "沿着", "is_correct": false, "explanation": "语义：沿着表示沿路线行走，不能说“沿着人口增加”。"}, {"text": "向", "is_correct": false, "explanation": "搭配：向后面接方向或对象，不能接“人口增加”这样的事件。"}], "explanations": {"随着": "随着：表示后一件事跟着前一件事的变化而变化，符合“人口增加，房子越来越贵”的句意。", "朝": "语义：朝表示方向，不能说“朝人口增加”。", "沿着": "语义：沿着表示沿路线行走，不能说“沿着人口增加”。", "向": "搭配：向后面接方向或对象，不能接“人口增加”这样的事件。"}, "sentence_index": 6, "correct_answer": "随着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "随着他很高，大家都很喜欢他。", "explanation": "这里应该用〈因为〉。随着表示后一事物跟着前一事物变化，“很高”是静止状态，不会变化，表示原因要用因为。"}, {"text": "我随着朋友打招呼。", "explanation": "这里应该用〈向〉。随着表示后一事物跟着前一事物变化，不能引出打招呼的对象，应说“向朋友打招呼”。"}, {"text": "妈妈随着我一块饼干。", "explanation": "这里应该用〈给〉。随着表示伴随变化，不能表示给予，应说“给我一块饼干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "随着的工资提高，他的生活好多了。", "corrected_sentence": "随着工资提高，他的生活好多了。", "error_description": "“随着”后面不能直接加“的”。正确形式是“随着工资提高”，“随着的工资提高”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "随着着天气变凉，树叶慢慢黄了。", "corrected_sentence": "随着天气变凉，树叶慢慢黄了。", "error_description": "“着”重复出现了。正确形式是“随着天气变凉”，“随着着”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
