INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88699, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不满是心里不高兴，觉得不够好。", "primary_collocate": null, "pronunciation": "bù mǎn", "ipa": "pu˥˩ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "员工对工资有很多不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把心里的不满都说出来了。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客向经理说出了自己的不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的不满大家都听到了。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的不满越来越多。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师听到了学生们的不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直不说话，是因为心里有不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信写了很多对公司的不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么不满，可以直接告诉我。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用哭来表示对妈妈的不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不满情绪", "label": "复合"}], "register": "口语", "sense_fingerprint": "名词，指心里不高兴、觉得不够好的感受，常说“有不满”“表示不满”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88699, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满 bù mǎn，名词，指心里不高兴、觉得不够好的感受。"}, {"text": "不瞒", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，“不瞒”意思是不隐瞒。"}, {"text": "不慢", "is_correct": false, "explanation": "mǎn（第三声）与 màn（第四声）声调不同，“不慢”意思是速度不慢。"}, {"text": "不管", "is_correct": false, "explanation": "声母 m 与 g 不同，声调相同（mǎn／guǎn），“不管”意思是不去管、不论。"}], "explanations": {"不满": "不满 bù mǎn，名词，指心里不高兴、觉得不够好的感受。", "不瞒": "mǎn（第三声）与 mán（第二声）声调不同，“不瞒”意思是不隐瞒。", "不慢": "mǎn（第三声）与 màn（第四声）声调不同，“不慢”意思是速度不慢。", "不管": "声母 m 与 g 不同，声调相同（mǎn／guǎn），“不管”意思是不去管、不论。"}, "sentence_index": null, "correct_answer": "不满"}, "level_3": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满：名词，指对工资的不高兴，与“很多”搭配，符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来说对工资有很多身材。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能说员工对工资有很多价格。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能说对工资有很多颜色。"}], "explanations": {"不满": "不满：名词，指对工资的不高兴，与“很多”搭配，符合句意。", "身材": "体貌：“身材”指人的体形，不能用来说对工资有很多身材。", "价格": "语义：“价格”指钱数，不能说员工对工资有很多价格。", "颜色": "语义：“颜色”指色彩，不能说对工资有很多颜色。"}, "sentence_index": 0, "correct_answer": "不满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的不满很小。", "explanation": "这里应该用〈缺陷〉。不满指人心里的情绪，不能指衣服本身的问题，衣服的问题要用“缺陷”来说。"}, {"text": "这个机器的不满很大。", "explanation": "这里应该用〈故障〉。不满是人的情绪，不能指机器出了问题，机器出问题要用“故障”。"}, {"text": "这支笔的不满很长。", "explanation": "这里应该用〈长度〉。不满是心里的情绪，没有长短，表示长短要用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88699, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满 bù mǎn，名词，指心里不高兴、觉得不够好的感受。"}, {"text": "不忙", "is_correct": false, "explanation": "máng（第二声）与 mǎn（第三声）声调不同，韵尾 ng 与 n 不同，“不忙”意思是不急迫。"}, {"text": "不眠", "is_correct": false, "explanation": "mián（第二声）与 mǎn（第三声）声调不同，韵母 ian 与 an 不同，“不眠”意思是睡不着觉。"}, {"text": "不晚", "is_correct": false, "explanation": "mǎn 与 wǎn 声母不同，声调相同，“不晚”意思是时间不迟。"}], "explanations": {"不满": "不满 bù mǎn，名词，指心里不高兴、觉得不够好的感受。", "不忙": "máng（第二声）与 mǎn（第三声）声调不同，韵尾 ng 与 n 不同，“不忙”意思是不急迫。", "不眠": "mián（第二声）与 mǎn（第三声）声调不同，韵母 ian 与 an 不同，“不眠”意思是睡不着觉。", "不晚": "mǎn 与 wǎn 声母不同，声调相同，“不晚”意思是时间不迟。"}, "sentence_index": null, "correct_answer": "不满"}, "level_3": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满：名词，指心里的不高兴，与“心里有”搭配，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，心里不能有体重。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来说心里有身高。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，心里不能有长度。"}], "explanations": {"不满": "不满：名词，指心里的不高兴，与“心里有”搭配，符合句意。", "体重": "语义：“体重”指身体的重量，心里不能有体重。", "身高": "体貌：“身高”指人的高矮，不能用来说心里有身高。", "长度": "语义：“长度”指长短，心里不能有长度。"}, "sentence_index": 6, "correct_answer": "不满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把他的不满煮熟了。", "explanation": "这里应该用〈饭菜〉。不满是心里的情绪，不能被煮熟，煮要用于食物。"}, {"text": "孩子的不满很开心。", "explanation": "这里应该用〈高兴〉。不满是心里不高兴的情绪，不能用来形容开心的样子。"}, {"text": "这个孩子的不满很甜。", "explanation": "这里应该用〈味道〉。不满是心里的情绪，没有甜咸，甜咸要用“味道”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88699, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "顾客心里有很多不满过。", "corrected_sentence": "顾客心里有很多不满。", "error_description": "错误：“不满”后多出了“过”。“过”表示经历，不能放在名词“不满”后作句尾，应删去。正确：“顾客心里有很多不满。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88699, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这件事有一台不满。", "corrected_sentence": "他对这件事有一种不满。", "error_description": "量词错误：“不满”的情绪应该用量词“种”，“台”用于机器、电器，不能用于不满。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满意", "is_correct": true, "explanation": "满意：对人或事物感到称心，与“不满”意思相反。"}, {"text": "勤快", "is_correct": false, "explanation": "“勤快”指勤劳爱干活，与“不满”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“不满”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不紧张、不费力，与“不满”没有反义关系。"}], "correct_answer": "满意", "explanations": {"满意": "满意：对人或事物感到称心，与“不满”意思相反。", "勤快": "“勤快”指勤劳爱干活，与“不满”没有反义关系。", "清楚": "“清楚”指明白、不模糊，与“不满”没有反义关系。", "轻松": "“轻松”指不紧张、不费力，与“不满”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满意", "is_correct": true, "explanation": "满意：对人或事物感到称心，与“不满”意思相反。"}, {"text": "凉快", "is_correct": false, "explanation": "“凉快”指温度低、舒服，与“不满”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“不满”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”指光线充足，与“不满”没有反义关系。"}], "correct_answer": "满意", "explanations": {"满意": "满意：对人或事物感到称心，与“不满”意思相反。", "凉快": "“凉快”指温度低、舒服，与“不满”没有反义关系。", "整齐": "“整齐”指排列有序，与“不满”没有反义关系。", "明亮": "“明亮”指光线充足，与“不满”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，对人或事物不满意。", "primary_collocate": null, "pronunciation": "bù mǎn", "ipa": "pu˥˩ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对这家饭店的服务很不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对我今天的工作不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人对房间的价格不满，就走了。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我的成绩很不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里不满，可是没有说话。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都对新的规定不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不满地看了我一眼。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对现在的生活一点儿也不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们对考试的时间非常不满。", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是对我的办法不满？", "target_word": "不满", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不满意", "label": "复合"}], "register": "口语", "sense_fingerprint": "形容词，表示对人或事物不满意，常说“对……不满”“很不满”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满 bù mǎn，形容词，表示对人或事物不满意。"}, {"text": "不慢", "is_correct": false, "explanation": "mǎn（第三声）与 màn（第四声）声调不同，“不慢”意思是速度不慢。"}, {"text": "不瞒", "is_correct": false, "explanation": "mǎn（第三声）与 mán（第二声）声调不同，“不瞒”意思是不隐瞒。"}, {"text": "不晚", "is_correct": false, "explanation": "mǎn 与 wǎn 声母不同，声调相同，“不晚”意思是时间不迟。"}], "explanations": {"不满": "不满 bù mǎn，形容词，表示对人或事物不满意。", "不慢": "mǎn（第三声）与 màn（第四声）声调不同，“不慢”意思是速度不慢。", "不瞒": "mǎn（第三声）与 mán（第二声）声调不同，“不瞒”意思是不隐瞒。", "不晚": "mǎn 与 wǎn 声母不同，声调相同，“不晚”意思是时间不迟。"}, "sentence_index": null, "correct_answer": "不满"}, "level_3": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满：对服务感到不满意，与“很”搭配，符合句意。"}, {"text": "响亮", "is_correct": false, "explanation": "语义：“响亮”形容声音大，不能用来形容服务。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：“宽敞”形容空间大，不能用来形容服务。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的外形，不能用来形容服务。"}], "explanations": {"不满": "不满：对服务感到不满意，与“很”搭配，符合句意。", "响亮": "语义：“响亮”形容声音大，不能用来形容服务。", "宽敞": "语义：“宽敞”形容空间大，不能用来形容服务。", "高大": "体貌：“高大”形容人或建筑的外形，不能用来形容服务。"}, "sentence_index": 0, "correct_answer": "不满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这位失去亲人的朋友很不满。", "explanation": "这里应该用〈同情〉。不满表示对人或事物不满意，对不幸的人表示怜悯要用“同情”。"}, {"text": "他对音乐很不满，却每天都高兴地唱歌。", "explanation": "这里应该用〈喜爱〉。“不满”表示对人或事物不满意，与“高兴地唱歌”语义矛盾，喜欢音乐要用“喜爱”。"}, {"text": "我对凶猛的老虎很不满。", "explanation": "这里应该用〈害怕〉。不满表示对人或事物不满意，对危险的东西感到恐惧要用“害怕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满 bù mǎn，形容词，表示对人或事物不满意。"}, {"text": "不忙", "is_correct": false, "explanation": "máng（第二声）与 mǎn（第三声）声调不同，韵尾 ng 与 n 不同，“不忙”意思是不急迫。"}, {"text": "不免", "is_correct": false, "explanation": "miǎn 与 mǎn 只差介音 i，声调相同（第三声），“不免”意思是难以避免。"}, {"text": "不管", "is_correct": false, "explanation": "声母 m 与 g 不同，声调相同（mǎn／guǎn），“不管”意思是不去管、不论。"}], "explanations": {"不满": "不满 bù mǎn，形容词，表示对人或事物不满意。", "不忙": "máng（第二声）与 mǎn（第三声）声调不同，韵尾 ng 与 n 不同，“不忙”意思是不急迫。", "不免": "miǎn 与 mǎn 只差介音 i，声调相同（第三声），“不免”意思是难以避免。", "不管": "声母 m 与 g 不同，声调相同（mǎn／guǎn），“不管”意思是不去管、不论。"}, "sentence_index": null, "correct_answer": "不满"}, "level_3": {"options": [{"text": "不满", "is_correct": true, "explanation": "不满：形容词，修饰“看”的方式时可用“不满地”，符合句意。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，不能修饰“看”的方式。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容面积广，不能修饰看一眼的动作。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人的身材，不能说“矮小地看了我一眼”。"}], "explanations": {"不满": "不满：形容词，修饰“看”的方式时可用“不满地”，符合句意。", "雪白": "语义：“雪白”形容颜色，不能修饰“看”的方式。", "辽阔": "语义：“辽阔”形容面积广，不能修饰看一眼的动作。", "矮小": "体貌：“矮小”形容人的身材，不能说“矮小地看了我一眼”。"}, "sentence_index": 6, "correct_answer": "不满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对天上的月亮很不满。", "explanation": "这里应该用〈欣赏〉。不满表示对人或事物不满意，对美好的事物表示赞赏要用“欣赏”。"}, {"text": "我对这盆盛开的花很不满。", "explanation": "这里应该用〈喜爱〉。不满表示不满意，对花草表示喜欢要用“喜爱”。"}, {"text": "他对眼前美丽的日出很不满。", "explanation": "这里应该用〈赞叹〉。不满表示不满意，对美景表示赞叹要用“赞叹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这个安排很不满。", "corrected_sentence": "我对这个安排很不满。", "error_description": "介词漏用：“不满”要说“对……不满”，应为“我对这个安排很不满”，不能省略“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都对这项规定很不满地。", "corrected_sentence": "大家都对这项规定很不满。", "error_description": "错误：句末多出“地”。“不满地”需要后接动词修饰，此处句末没有动词，应删去“地”，写作“很不满”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
