INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88708, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "客观事物在人的头脑中留下的形象。", "primary_collocate": null, "pronunciation": "yìn xiàng", "ipa": "in˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老家的样子还留在我的印象里。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我印象中海边的日落最美。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对那个小镇的印象是安静。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次见面，他给人的印象很友好。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家在我的印象中很干净。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留给大家的印象是爱笑。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行让我对这个城市有了新印象。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我的印象里，奶奶总是很忙。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片和我的印象不一样。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在同学们的印象中很严格。", "target_word": "印象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：事物在头脑中形成的整体形象或看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88708, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象 yìn xiàng，指事物在头脑中留下的形象或看法。"}, {"text": "音像", "is_correct": false, "explanation": "yīn（第一声）与 yìn（第四声）声调不同，“音像”指声音和图像，意思不同。"}, {"text": "映像", "is_correct": false, "explanation": "yìng（第四声）与 yìn（第四声）韵母不同（ing 与 in），“映像”指映在屏幕上的像。"}, {"text": "音响", "is_correct": false, "explanation": "yīn 与 yìn 声调不同，xiǎng 与 xiàng 声调也不同，“音响”指声音设备。"}], "explanations": {"印象": "印象 yìn xiàng，指事物在头脑中留下的形象或看法。", "音像": "yīn（第一声）与 yìn（第四声）声调不同，“音像”指声音和图像，意思不同。", "映像": "yìng（第四声）与 yìn（第四声）韵母不同（ing 与 in），“映像”指映在屏幕上的像。", "音响": "yīn 与 yìn 声调不同，xiǎng 与 xiàng 声调也不同，“音响”指声音设备。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象：与“留在……里”搭配，指留在头脑中的形象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气的状况，不能说“留在我的天气里”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来说老家的样子。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“留在……里”不能接“脾气”，脾气不会留在某处。"}], "explanations": {"印象": "印象：与“留在……里”搭配，指留在头脑中的形象。", "天气": "语义：“天气”指大气的状况，不能说“留在我的天气里”。", "身高": "体貌：“身高”指人的高矮，不能用来说老家的样子。", "脾气": "搭配：“留在……里”不能接“脾气”，脾气不会留在某处。"}, "sentence_index": 0, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯水的印象很烫。", "explanation": "这里应该用〈温度〉。印象是头脑中的形象，不能说烫或凉，冷热要用“温度”。"}, {"text": "这首歌的印象很好听。", "explanation": "这里应该用〈声音〉。印象指留在脑中的形象，不能说好听，好听用于声音。"}, {"text": "这条河的印象很长。", "explanation": "这里应该用〈长度〉。印象不能说长短，表示长短要用“长度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88708, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象 yìn xiàng，指事物在头脑中留下的形象或看法。"}, {"text": "进项", "is_correct": false, "explanation": "jìn 与 yìn 只差声母（j 与零声母），声调相同（第四声），“进项”指收入、进账。"}, {"text": "引向", "is_correct": false, "explanation": "yǐn（第三声）与 yìn（第四声）声调不同，“引向”指把人或事物引到某个方向。"}, {"text": "信箱", "is_correct": false, "explanation": "xìn 与 yìn 声母不同；xiāng（第一声）与 xiàng（第四声）声调不同，“信箱”指收信的箱子。"}], "explanations": {"印象": "印象 yìn xiàng，指事物在头脑中留下的形象或看法。", "进项": "jìn 与 yìn 只差声母（j 与零声母），声调相同（第四声），“进项”指收入、进账。", "引向": "yǐn（第三声）与 yìn（第四声）声调不同，“引向”指把人或事物引到某个方向。", "信箱": "xìn 与 yìn 声母不同；xiāng（第一声）与 xiàng（第四声）声调不同，“信箱”指收信的箱子。"}, "sentence_index": null, "correct_answer": "印象"}, "level_3": {"options": [{"text": "印象", "is_correct": true, "explanation": "印象：与“有了新”搭配，指对城市形成的新的看法。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来指一个城市。"}, {"text": "楼房", "is_correct": false, "explanation": "语义：“楼房”是建筑，旅行不能让人对城市有新楼房。"}, {"text": "门票", "is_correct": false, "explanation": "语义：“门票”是入场的凭证，不能说对城市有新门票。"}], "explanations": {"印象": "印象：与“有了新”搭配，指对城市形成的新的看法。", "身材": "体貌：“身材”指人的体形，不能用来指一个城市。", "楼房": "语义：“楼房”是建筑，旅行不能让人对城市有新楼房。", "门票": "语义：“门票”是入场的凭证，不能说对城市有新门票。"}, "sentence_index": 6, "correct_answer": "印象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的印象很重。", "explanation": "这里应该用〈重量〉。印象没有轻重，表示轻重要用“重量”。"}, {"text": "这件衣服的印象很圆。", "explanation": "这里应该用〈形状〉。印象不能说圆扁，表示形状要用“形状”。"}, {"text": "这道菜的印象很咸。", "explanation": "这里应该用〈味道〉。印象不能有咸淡，咸淡要用“味道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, v