INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "伟大是特别了不起,让人佩服。", "primary_collocate": null, "pronunciation": "wěi dà", "ipa": "weɪ˨˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈是一个很伟大的人。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了孩子放弃了自己的工作，真伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师一辈子帮助穷孩子，他很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的爱是世界上最伟大的爱。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救了落水的小孩，大家都说他伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钱都给了穷人，这种爱心很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天照顾生病的老人，这种行为很伟大。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我心里，爷爷是个伟大的英雄。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒着危险去帮助病人，真伟大！", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为朋友做了这么多，你太伟大了。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更伟大", "label": "比较形式"}, {"form": "最伟大", "label": "最高级形式"}], "register": "中性", "sense_fingerprint": "人的品行或做法特别了不起，让人佩服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容妈妈的品格，句子是在赞美她。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：“渺小”与句中赞美妈妈的语气相反，不能说妈妈渺小。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”与“妈妈”的亲近关系相矛盾，不能说妈妈是陌生的人。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“人”这一身份不自然。"}], "explanations": {"伟大": "正确。“伟大”形容妈妈的品格，句子是在赞美她。", "渺小": "语义：“渺小”与句中赞美妈妈的语气相反，不能说妈妈渺小。", "陌生": "语义：“陌生”与“妈妈”的亲近关系相矛盾，不能说妈妈是陌生的人。", "巨大": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“人”这一身份不自然。"}, "sentence_index": 0, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故造成的损失非常伟大。", "explanation": "这里应该用〈巨大〉。“伟大”形容人的品格、事业的崇高，不用来形容损失这类程度。"}, {"text": "这家公司的规模非常伟大。", "explanation": "这里应该用〈庞大〉。规模的大小用“庞大”，“伟大”只用于人的品格或成就，不说公司的规模。"}, {"text": "那朵花非常伟大。", "explanation": "这里应该用〈美丽〉。形容景物的外观用“美丽”，“伟大”用于人的品格和成就，不形容花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容照顾病人这种行为的崇高，与句意一致。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：照顾生病的老人是关爱的表现，“残忍”与句意相反。"}, {"text": "可耻", "is_correct": false, "explanation": "语义：“可耻”是负面评价，照顾生病的老人是善行，与句意相反。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”与“每天照顾生病的老人”的关心态度矛盾。"}], "explanations": {"伟大": "正确。“伟大”形容照顾病人这种行为的崇高，与句意一致。", "残忍": "语义：照顾生病的老人是关爱的表现，“残忍”与句意相反。", "可耻": "语义：“可耻”是负面评价，照顾生病的老人是善行，与句意相反。", "冷淡": "语义：“冷淡”与“每天照顾生病的老人”的关心态度矛盾。"}, "sentence_index": 6, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种药的效果非常伟大。", "explanation": "这里应该用〈显著〉。效果、变化的明显程度用“显著”，“伟大”只用于人的品格、事业等。"}, {"text": "他这次考试考得很伟大。", "explanation": "这里应该用〈优秀〉。考试成绩和表现用“优秀”，“伟大”不用来评价成绩。"}, {"text": "这间房间很伟大。", "explanation": "这里应该用〈干净〉。房间的整洁用“干净”，“伟大”不用来形容房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我见过的最伟大得老师。", "corrected_sentence": "他是我见过的最伟大的老师。", "error_description": "错误：“伟大得老师”；正确：“伟大的老师”。修饰名词要用结构助词“的”，“得”用于动词或形容词后连接补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对家乡的贡献很的伟大。", "corrected_sentence": "他对家乡的贡献很伟大。", "error_description": "错误：“很的伟大”；正确：“很伟大”。程度副词“很”与形容词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平凡", "is_correct": true, "explanation": "正确。“平凡”与“不平凡”的“伟大”相对，指普通、不突出。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”指清楚明白，与“伟大”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”指反应慢，与“伟大”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”指温度低，与“伟大”没有反义关系。"}], "correct_answer": "平凡", "explanations": {"平凡": "正确。“平凡”与“不平凡”的“伟大”相对，指普通、不突出。", "清晰": "“清晰”指清楚明白，与“伟大”没有反义关系。", "迟钝": "“迟钝”指反应慢，与“伟大”没有反义关系。", "寒冷": "“寒冷”指温度低，与“伟大”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平凡", "is_correct": true, "explanation": "正确。“平凡”与“不平凡”的“伟大”相对，指普通、不突出。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”指质地硬，与“伟大”没有反义关系。"}, {"text": "懒惰", "is_correct": false, "explanation": "“懒惰”指不愿劳动，与“伟大”在这一义上没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "“潮湿”指含水分多，与“伟大”没有反义关系。"}], "correct_answer": "平凡", "explanations": {"平凡": "正确。“平凡”与“不平凡”的“伟大”相对，指普通、不突出。", "坚硬": "“坚硬”指质地硬，与“伟大”没有反义关系。", "懒惰": "“懒惰”指不愿劳动，与“伟大”在这一义上没有反义关系。", "潮湿": "“潮湿”指含水分多，与“伟大”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "品格、才能、成就等崇高而不平凡。", "primary_collocate": null, "pronunciation": "wěi dà", "ipa": "weɪ˨˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "爱因斯坦是一位伟大的科学家。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一项伟大的发明。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅是中国伟大的文学家。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部伟大的作品影响了很多人。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们完成了一件伟大的工程。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城是古代人民创造的伟大奇迹。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生取得了伟大的成就。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "伟大的音乐家贝多芬耳朵听不见，还写出了好音乐。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们伟大的祖国有五千年的历史。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位伟大的诗人写了很多名诗。", "target_word": "伟大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更伟大", "label": "比较形式"}, {"form": "最伟大", "label": "最高级形式"}], "register": "书面", "sense_fingerprint": "人物、成就、作品等崇高而不平凡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容爱因斯坦的成就和品格，与句意一致。"}, {"text": "渺小", "is_correct": false, "explanation": "语义：爱因斯坦是著名科学家，“渺小”与句中的敬佩语气相反。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：爱因斯坦是家喻户晓的人物，“陌生”与句意矛盾。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“科学家”这类人物身份不自然。"}], "explanations": {"伟大": "正确。“伟大”形容爱因斯坦的成就和品格，与句意一致。", "渺小": "语义：爱因斯坦是著名科学家，“渺小”与句中的敬佩语气相反。", "陌生": "语义：爱因斯坦是家喻户晓的人物，“陌生”与句意矛盾。", "巨大": "搭配：“巨大”多修饰体积、数量或影响，直接修饰“科学家”这类人物身份不自然。"}, "sentence_index": 0, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的人口非常伟大。", "explanation": "这里应该用〈庞大〉。人口的多少用“庞大”，“伟大”不用来形容人口。"}, {"text": "她这学期的成绩很伟大。", "explanation": "这里应该用〈优秀〉。成绩和表现用“优秀”，“伟大”用于人的品格或事业，不评价成绩。"}, {"text": "这碗汤的味道非常伟大。", "explanation": "这里应该用〈鲜美〉。味道用“鲜美”或“好喝”，“伟大”不用来评价味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伟大", "is_correct": true, "explanation": "正确。“伟大”形容成就的崇高，与“取得”搭配自然。"}, {"text": "残忍", "is_correct": false, "explanation": "语义：“残忍”是负面评价，与句中肯定成就的语气相矛盾。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：“幼稚”指不成熟，与“成就”的褒义不符。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体，不能修饰成就。"}], "explanations": {"伟大": "正确。“伟大”形容成就的崇高，与“取得”搭配自然。", "残忍": "语义：“残忍”是负面评价，与句中肯定成就的语气相矛盾。", "幼稚": "语义：“幼稚”指不成熟，与“成就”的褒义不符。", "笨重": "搭配：“笨重”形容物体，不能修饰成就。"}, "sentence_index": 6, "correct_answer": "伟大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜非常伟大。", "explanation": "这里应该用〈美味〉。菜肴的味道用“美味”，“伟大”用于人的品格和成就，不用来评价菜。"}, {"text": "这面旗子的颜色非常伟大。", "explanation": "这里应该用〈鲜艳〉。颜色的鲜明用“鲜艳”，“伟大”不用来形容颜色。"}, {"text": "这张桌子擦得很伟大。", "explanation": "这里应该用〈干净〉。桌面的整洁用“干净”，“伟大”不用来形容擦桌子的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是中国最伟大得作家之一。", "corrected_sentence": "他是中国最伟大的作家之一。", "error_description": "错误：“伟大得作家”；正确：“伟大的作家”。修饰名词要用结构助词“的”，“得”用于补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88712, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家的作品很的伟大。", "corrected_sentence": "这位画家的作品很伟大。", "error_description": "错误：“很的伟大”；正确：“很伟大”。程度副词“很”与形容词之间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可喜", "is_correct": true, "explanation": "正确：“可喜”指值得高兴，与“可惜”的遗憾相对。"}, {"text": "清楚", "is_correct": false, "explanation": "与“可惜”没有反义关系，“清楚”形容明白、分明，意思不相对。"}, {"text": "结实", "is_correct": false, "explanation": "与“可惜”没有反义关系，“结实”形容物体牢固。"}, {"text": "安静", "is_correct": false, "explanation": "与“可惜”没有反义关系，“安静”形容声音或环境平静。"}], "correct_answer": "可喜", "explanations": {"可喜": "正确：“可喜”指值得高兴，与“可惜”的遗憾相对。", "清楚": "与“可惜”没有反义关系，“清楚”形容明白、分明，意思不相对。", "结实": "与“可惜”没有反义关系，“结实”形容物体牢固。", "安静": "与“可惜”没有反义关系，“安静”形容声音或环境平静。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可惜是事情没有做成，心里觉得有点难过。", "primary_collocate": null, "pronunciation": "kě xī", "ipa": "kʰɤ˨˩˦ ɕi˥", "syllable_count": 2, "sentences": [{"text": "真可惜，我们差一分就赢了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的电影票卖完了，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没考上大学，大家都觉得可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你没来看比赛，太可惜了。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，我们没去成公园，真可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次机会没抓住，他觉得很可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "差五分钟没赶上火车，真可惜！", "target_word": "可惜", "complexity_tier": "T3", "furigana": "chà wǔ fēnzhōng méi gǎn shàng huǒchē, zhēn kěxī!", "sentence_source": "generated"}, {"text": "她没能参加朋友的婚礼，觉得很可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛下雨取消了，多可惜啊。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情没办成，我也觉得有点可惜。", "target_word": "可惜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "形容词，事情没有做成或错过机会，心里觉得遗憾难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a80dc5a-ece4-49d6-9e08-b096bd7cfe24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：听到的是“可惜”（kě xī），指事情没做成而心里遗憾。"}, {"text": "可喜", "is_correct": false, "explanation": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。"}, {"text": "可心", "is_correct": false, "explanation": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。"}, {"text": "可期", "is_correct": false, "explanation": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}], "explanations": {"可惜": "正确：听到的是“可惜”（kě xī），指事情没做成而心里遗憾。", "可喜": "xǐ（第三声）与 xī（第一声）声调不同，“可喜”意思是值得高兴。", "可心": "xīn 比 xī 多一个鼻音韵尾 -n，“可心”意思是称心如意。", "可期": "qī 与 xī 声母不同（q / x），“可期”意思是值得期待，如“前途可期”。"}, "sentence_index": null, "correct_answer": "可惜"}, "level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“真可惜”表示事情没做成而遗憾，与“差一分就赢了”相符。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：“可爱”多用于人或小动物，不能评价比赛的失利结果。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”表示高兴，与“差一分就赢了”的失利语境相反。"}, {"text": "丰富", "is_correct": false, "explanation": "搭配：“丰富”修饰经验、内容等，不能用来评价比赛结果。"}], "explanations": {"可惜": "正确：“真可惜”表示事情没做成而遗憾，与“差一分就赢了”相符。", "可爱": "搭配：“可爱”多用于人或小动物，不能评价比赛的失利结果。", "快乐": "语义：“快乐”表示高兴，与“差一分就赢了”的失利语境相反。", "丰富": "搭配：“丰富”修饰经验、内容等，不能用来评价比赛结果。"}, "sentence_index": 0, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只流浪狗饿得站不起来，真可惜。", "explanation": "这里应该用〈可怜〉。“可惜”表示事情没做成或好东西被浪费的遗憾；形容动物处境悲惨、令人同情时要用“可怜”。"}, {"text": "他这次考试进步很大，真是可惜。", "explanation": "这里应该用〈可喜〉。进步是值得高兴的事，“可惜”表达遗憾，与语境的感情相反，应该用“可喜”。"}, {"text": "这个宝宝真可惜，大家都喜欢逗她。", "explanation": "这里应该用〈可爱〉。“可惜”表示遗憾惋惜，形容讨人喜欢的小孩要用“可爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可惜", "is_correct": true, "explanation": "正确：“真可惜”表示遗憾，与“差五分钟没赶上火车”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与没赶上车的遗憾语境不符。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”说价格，不能用来评价没赶上车这件事。"}, {"text": "整齐", "is_correct": false, "explanation": "体貌：“整齐”形容排列或外貌，不能用于描述没赶上火车的情况。"}], "explanations": {"可惜": "正确：“真可惜”表示遗憾，与“差五分钟没赶上火车”相符。", "热闹": "语义：“热闹”形容场面喧闹，与没赶上车的遗憾语境不符。", "便宜": "搭配：“便宜”说价格，不能用来评价没赶上车这件事。", "整齐": "体貌：“整齐”形容排列或外貌，不能用于描述没赶上火车的情况。"}, "sentence_index": 6, "correct_answer": "可惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个朋友很可惜，什么事都愿意帮你。", "explanation": "这里应该用〈可靠〉。“可惜”表示事情没做成而遗憾，不能用来形容人值得信赖；说人靠得住要用“可靠”。"}, {"text": "他的态度很可惜，我们要小心。", "explanation": "这里应该用〈可疑〉。“可惜”表示惋惜，不能用来形容令人起疑的态度。"}, {"text": "这次演出结束后，我的心情很可惜。", "explanation": "这里应该用〈平静〉。“可惜”是惋惜的感情，不能描述心情平和的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次没去成，太可惜的。", "corrected_sentence": "这次没去成，太可惜了。", "error_description": "错误：句末用“的”，“太可惜的”不能单独作谓语，表示感叹要用“了”。正确：“太可惜了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88715, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没能参加决赛，我觉得太很可惜。", "corrected_sentence": "他没能参加决赛，我觉得很可惜。", "error_description": "错误：“太”和“很”同时修饰“可惜”，程度副词不能重叠。正确：去掉“太”，说“很可惜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88716, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "可喜", "is_correct": true, "explanation": "正确：“可喜”指值得高兴，与令人惋惜的“可惜”相对。"}, {"text": "结实", "is_correct": false, "explanation": "与“可惜”没有反义关系，“结实”形容物体牢固。"}, {"text": "辛苦", "is_correct": false, "explanation": "与“可惜”没有反义关系，“辛苦”形容劳累。"}, {"text": "清楚", "is_correct": false, "explanation": "与“可惜”没有反义关系，“清楚”形容明白、分明。"}], "correct_answer": "可喜", "explanations": {"可喜": "正确：“可喜”指值得高兴，与令人惋惜的“可惜”相对。", "结实": "与“可惜”没有反义关系，“结实”形容物体牢固。", "辛苦": "与“可惜”没有反义关系，“辛苦”形容劳累。", "清楚": "与“可惜”没有反义关系，“清楚”形容明白、分明。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd701370-4319-4638-b207-2ed683efa027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
