INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大概的内容;主要的意思。", "primary_collocate": null, "pronunciation": "dà yào", "ipa": "ta⁵¹ jɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "你先把这件事的大要告诉我。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的大要是一个男孩寻找回家的路。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同太长，我只看了大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旅行的大要写在日记里。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇新闻的大要很容易懂。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把比赛的大要告诉大家。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没时间细读，只看了书的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲了一下这个办法的大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的大要大家都知道。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写出你们的活动大要。", "target_word": "大要", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "大概的内容，主要的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b561781c-ab85-4690-8dcd-c94501bb469d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。大要指事情的主要内容，可以先告诉对方，与这里的语境相符。"}, {"text": "插图", "is_correct": false, "explanation": "搭配：“告诉”的对象是信息，插图是图像，不能被告诉。"}, {"text": "页码", "is_correct": false, "explanation": "语义：页码是编号，不是事情的内容，与“这件事的”不相符。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的数量，不能用来说明一件事的情况。"}], "explanations": {"大要": "正确。大要指事情的主要内容，可以先告诉对方，与这里的语境相符。", "插图": "搭配：“告诉”的对象是信息，插图是图像，不能被告诉。", "页码": "语义：页码是编号，不是事情的内容，与“这件事的”不相符。", "字数": "语义：字数是文字的数量，不能用来说明一件事的情况。"}, "sentence_index": 0, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇课文的大要我背得很熟，连每一句原话都能一字不差地说出来。", "explanation": "这里应该用〈原文〉。大要只是大概的内容，不包括每一句原话；一字不差地说出每句原话要用〈原文〉。"}, {"text": "他给我讲了一把旅行的大要。", "explanation": "量词用错：〈把〉用于有柄的器具，大要是讲述的内容，应该用〈段〉或〈份〉。"}, {"text": "他躲在大要后面哭了一场。", "explanation": "这里把大要当成了实物，应该说“躲在树后面”。〈树〉是实物，大要是抽象的内容，不能用来挡身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大要", "is_correct": true, "explanation": "正确。大要是书的主要内容，没时间细读时只看大要是合理的。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是书的内容，与“只看了书的”不相符。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：心跳是身体的活动，不是可以“看”的内容，与“只看了书的”语境矛盾。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“看”的对象是文字或图像，“音量”是声音的大小，不能说“看音量”。"}], "explanations": {"大要": "正确。大要是书的主要内容，没时间细读时只看大要是合理的。", "饭菜": "语义：饭菜是食物，不是书的内容，与“只看了书的”不相符。", "心跳": "语义：心跳是身体的活动，不是可以“看”的内容，与“只看了书的”语境矛盾。", "音量": "搭配：“看”的对象是文字或图像，“音量”是声音的大小，不能说“看音量”。"}, "sentence_index": 6, "correct_answer": "大要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把活动大要写成了三十页，连每个人的座位都标得清清楚楚。", "explanation": "这里应该用〈详细方案〉。大要是简要的概括；写成三十页、连座位都标出的是〈详细方案〉，不是大要。"}, {"text": "我们为活动准备了一只大要，放在桌子上等大家来取。", "explanation": "量词用错：〈只〉用于动物，大要应该用〈份〉。"}, {"text": "我们把这次会议的大要一字不差地抄进了笔记本，连发言人的停顿和咳嗽都记下来了。", "explanation": "这里应该用〈逐字记录〉。大要只是简要的概括；一字不差、连停顿和咳嗽都记下的是〈逐字记录〉，不是大要。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他读了完这份计划的大要。", "corrected_sentence": "他读完了这份计划的大要。", "error_description": "错误在补语位置：“读完”是动补结构，“了”应放在补语之后，正确说法是“读完了”；“读了完”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我看了一根活动大要。", "corrected_sentence": "他给我看了一份活动大要。", "error_description": "错误在量词：“根”用于细长条状之物，“大要”是文字材料，量词应用“份”，不能用“根”。正确说法是“一份活动大要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
