INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敲门。", "primary_collocate": null, "pronunciation": "dǎ mén", "ipa": "ta²¹⁴ mən³⁵", "syllable_count": 2, "sentences": [{"text": "进房间以前，要先打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打门三下，里面有人说“请进”。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不会打门，只会在门口叫。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快递员在门口打门，没人开。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁在打门？去开一下门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打门以后，听到里面有脚步声。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打门打了半天，也没人来开。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，我以为是有人打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别用脚打门，会吓到里面的人。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝醉了，在别人家门口大声打门。", "target_word": "打门", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了门", "label": "完成体"}, {"form": "打过门", "label": "经历体"}], "register": "中性", "sense_fingerprint": "打门：敲门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
