ompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打门", "is_correct": true, "explanation": "正确：“他打门打了半天”，“打门”是用手敲门，可以持续很久。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”不是敲击动作，不能和“打了半天，也没人来开”连用。"}, {"text": "看书", "is_correct": false, "explanation": "搭配：“看书打了半天”不成立，句中的动作不是看书。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步打了半天”不通，“也没人来开”与散步无关。"}], "explanations": {"打门": "正确：“他打门打了半天”，“打门”是用手敲门，可以持续很久。", "微笑": "语义：“微笑”不是敲击动作，不能和“打了半天，也没人来开”连用。", "看书": "搭配：“看书打了半天”不成立，句中的动作不是看书。", "散步": "搭配：“散步打了半天”不通，“也没人来开”与散步无关。"}, "sentence_index": 6, "correct_answer": "打门"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿起手机打门给客户，谈好了合同。", "explanation": "打电话要说〈打〉电话，“打门”不能指打电话。"}, {"text": "老师在黑板上打门，写了一道数学题。", "explanation": "写字要说〈写〉，“打门”不能指写字。"}, {"text": "她在车站打门，等了三个小时的火车。", "explanation": "等车要说〈等〉，“打门”不能指等待。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打门过，没人来开。", "corrected_sentence": "我打过门，没人来开。", "error_description": "体标错误：“过”应紧跟动词，说“打过门”，不说“打门过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口打门得很响，人都醒了。", "corrected_sentence": "他在门口打门打得很响，人都醒了。", "error_description": "补语错误：“打得很响”作补语时要重复动词“打”，应说“打门打得很响”，不说“打门得很响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
