INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "换是把旧的拿走,放上另一个。", "primary_collocate": null, "pronunciation": "huàn", "ipa": "xwan˥˩", "syllable_count": 1, "sentences": [{"text": "灯坏了，爸爸正在换灯泡。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遥控器没电了，要换电池。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个星期都给我换床单。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼缸里的水太脏了，该换水了。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太旧了，我想换一双新的。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士每天给他换药。", "target_word": "换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机屏幕坏了，修理店可以给你换屏幕。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服湿了，快回房间换衣服。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌布脏了，我换了一块新的。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车胎没气了，他蹲在路边换轮胎。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换了", "label": "体标"}, {"form": "换过", "label": "体标"}, {"form": "换着", "label": "体标"}, {"form": "换换", "label": "重叠"}, {"form": "更换", "label": "复合"}, {"form": "換", "label": "繁体"}], "register": "通用", "sense_fingerprint": "拿走旧的或坏的,换上新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是拿走旧的，放上新的。"}, {"text": "环", "is_correct": false, "explanation": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。"}, {"text": "晃", "is_correct": false, "explanation": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。"}, {"text": "慌", "is_correct": false, "explanation": "慌 huāng 与 huàn 韵尾不同（ng／n），声调也不同，意思是慌张。"}], "explanations": {"换": "正确：换 huàn，意思是拿走旧的，放上新的。", "环": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。", "欢": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。", "晃": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。", "慌": "慌 huāng 与 huàn 韵尾不同（ng／n），声调也不同，意思是慌张。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“爸爸正在换灯泡”表示更换坏了的灯泡，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：灯泡不能吃，“吃灯泡”说不通。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜等，不能与“灯泡”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用于灯泡。"}], "explanations": {"换": "正确：“爸爸正在换灯泡”表示更换坏了的灯泡，符合句意。", "吃": "语义：灯泡不能吃，“吃灯泡”说不通。", "穿": "搭配：“穿”用于衣服、鞋袜等，不能与“灯泡”搭配。", "唱": "语义：“唱”指发声演唱，不能用于灯泡。"}, "sentence_index": 0, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我饿了，该换饭了。", "explanation": "这里应该用〈吃〉。换表示更换物件，饭要说“吃饭”。"}, {"text": "车坏了，该换汽油了。", "explanation": "这里应该用〈加〉。换是拿走旧的放上新的，汽油要加不要换。"}, {"text": "他的成绩太差，我们换一下他的身高吧。", "explanation": "这里应该用〈长〉。换表示更换物件，身高不能更换，要说“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是拿走旧的，放上新的。"}, {"text": "缓", "is_correct": false, "explanation": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān（第一声）与 huàn（第四声）只差声调，意思是高兴。"}, {"text": "环", "is_correct": false, "explanation": "环 huán（第二声）与 huàn（第四声）只差声调，意思是圆环。"}, {"text": "惯", "is_correct": false, "explanation": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。"}], "explanations": {"换": "正确：换 huàn，意思是拿走旧的，放上新的。", "缓": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。", "欢": "欢 huān（第一声）与 huàn（第四声）只差声调，意思是高兴。", "环": "环 huán（第二声）与 huàn（第四声）只差声调，意思是圆环。", "惯": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“修理店可以给你换屏幕”表示更换坏掉的屏幕，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用于屏幕。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能与“屏幕”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢弃，不表示更换屏幕，“给你扔屏幕”意思相反。"}], "explanations": {"换": "正确：“修理店可以给你换屏幕”表示更换坏掉的屏幕，符合句意。", "唱": "语义：“唱”指发声演唱，不能用于屏幕。", "喝": "搭配：“喝”的对象是液体，不能与“屏幕”搭配。", "扔": "语义：“扔”指丢弃，不表示更换屏幕，“给你扔屏幕”意思相反。"}, "sentence_index": 6, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蹲在路边换水，车胎没气了。", "explanation": "这里应该用〈打〉。换水是更换液体，车胎没气要打气，不能换水。"}, {"text": "车胎没气了，他蹲在路边换空气。", "explanation": "这里应该说〈打气〉。换表示更换物件，空气不能更换。"}, {"text": "车胎没气了，他蹲在路边换了一个年纪。", "explanation": "换表示更换物件，年纪不能更换，这句说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书桌的抽屉坏了，爸爸已经换了好了。", "corrected_sentence": "书桌的抽屉坏了，爸爸已经换好了。", "error_description": "错误：补语“好”前多了“了”。正确：表示动作已完成时应说“换好了”，“了”放在补语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水管漏了，师傅正在换了水管。", "corrected_sentence": "水管漏了，师傅正在换水管。", "error_description": "错误：“正在”和“了”不能同时用在一个动作上。正确：表示正在进行时只用“正在”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
