INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿一样东西去换取另一样;更换;变换。", "primary_collocate": null, "pronunciation": "huàn", "ipa": "xwan˥˩", "syllable_count": 1, "sentences": [{"text": "我想用这本旧书换一本新书。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这里可以换钱吗？", "target_word": "换", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和你换一下座位，可以吗？", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到人民广场要换二号线。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题太难了，我们换一个吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹拿苹果跟我换了一块蛋糕。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把美元换成人民币。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不通，我们换一条走吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机不好用，为什么不换一个新的？", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩换着看这本书吧。", "target_word": "换", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "换了", "label": "体标"}, {"form": "换过", "label": "体标"}, {"form": "换着", "label": "体标"}, {"form": "换换", "label": "重叠"}, {"form": "交换", "label": "复合"}, {"form": "換", "label": "繁体"}], "register": "通用", "sense_fingerprint": "用一样东西交换另一样,或把一事物变成另一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是用一样东西交换另一样，或把一事物变成另一个。"}, {"text": "环", "is_correct": false, "explanation": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。"}, {"text": "晃", "is_correct": false, "explanation": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。"}, {"text": "花", "is_correct": false, "explanation": "花 huā 与 huàn 韵尾和声调都不同，意思是花朵。"}, {"text": "慌", "is_correct": false, "explanation": "慌 huāng 与 huàn 韵尾不同（ng／n），声调也不同，意思是慌张。"}], "explanations": {"换": "正确：换 huàn，意思是用一样东西交换另一样，或把一事物变成另一个。", "环": "环 huán（第二声）与 huàn（第四声）声调不同，意思是圆环。", "欢": "欢 huān（第一声）与 huàn（第四声）声调不同，意思是高兴。", "晃": "晃 huàng 与 huàn 韵尾不同（ng／n），意思是晃动。", "花": "花 huā 与 huàn 韵尾和声调都不同，意思是花朵。", "慌": "慌 huāng 与 huàn 韵尾不同（ng／n），声调也不同，意思是慌张。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“用这本旧书换一本新书”表示以旧换新，符合句意。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄，“用这本旧书寄一本新书”说不通。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”指把东西卖出换钱，不能表示用旧书换取新书。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”需要借入方和借出方，句中没有“借”的对象，说不通。"}], "explanations": {"换": "正确：“用这本旧书换一本新书”表示以旧换新，符合句意。", "寄": "语义：“寄”指邮寄，“用这本旧书寄一本新书”说不通。", "卖": "语义：“卖”指把东西卖出换钱，不能表示用旧书换取新书。", "借": "配价：“借”需要借入方和借出方，句中没有“借”的对象，说不通。"}, "sentence_index": 0, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想和你换一下年龄，这样我就能早点上大学了。", "explanation": "这里应该用〈长〉。换表示交换，年龄不能交换，要说“长大”。"}, {"text": "我想换一下我的出生日期，让自己早点长大。", "explanation": "出生日期不能更换，“换”在这里说不通，应表达为“想早点长大”。"}, {"text": "他的成绩太差，我们换一下他的身高吧。", "explanation": "这里应该用〈长〉。换表示交换或更换，身高不能交换，要说“长高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：换 huàn，意思是交换或更换。"}, {"text": "缓", "is_correct": false, "explanation": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。"}, {"text": "欢", "is_correct": false, "explanation": "欢 huān（第一声）与 huàn（第四声）只差声调，意思是高兴。"}, {"text": "环", "is_correct": false, "explanation": "环 huán（第二声）与 huàn（第四声）只差声调，意思是圆环。"}, {"text": "惯", "is_correct": false, "explanation": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。"}], "explanations": {"换": "正确：换 huàn，意思是交换或更换。", "缓": "缓 huǎn（第三声）与 huàn（第四声）声调不同，意思是慢或缓解。", "欢": "欢 huān（第一声）与 huàn（第四声）只差声调，意思是高兴。", "环": "环 huán（第二声）与 huàn（第四声）只差声调，意思是圆环。", "惯": "惯 guàn 与 huàn 只差声母（g／h），意思是习惯。"}, "sentence_index": null, "correct_answer": "换"}, "level_3": {"options": [{"text": "换", "is_correct": true, "explanation": "正确：“把美元换成人民币”表示兑换货币，符合句意。"}, {"text": "存", "is_correct": false, "explanation": "语义：“存”指把钱存入银行，不能表示兑换货币。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“花”指消费，“花成人民币”不成立。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”指获得收益，不表示货币之间的兑换。"}], "explanations": {"换": "正确：“把美元换成人民币”表示兑换货币，符合句意。", "存": "语义：“存”指把钱存入银行，不能表示兑换货币。", "花": "搭配：“花”指消费，“花成人民币”不成立。", "赚": "语义：“赚”指获得收益，不表示货币之间的兑换。"}, "sentence_index": 6, "correct_answer": "换"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这本书换给你，我什么也不要。", "explanation": "这里应该用〈送〉。“换”要求对方给出另一样东西，“什么也不要”与之矛盾。"}, {"text": "他借了我的伞，还没换给我钱。", "explanation": "借来的伞应说“还”，“换给我钱”与借伞这一情节不符。"}, {"text": "你付了五十块，我应该换你十块钱。", "explanation": "这里应该用〈找〉。找是找回多付的钱；“换”表示用一样换另一样，这里不能说“换你十块钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把日元换人民币。", "corrected_sentence": "我想把日元换成人民币。", "error_description": "错误：漏掉了补语“成”。正确：表示把一样东西变成另一样时，要说“换成”，不能只说“换”加宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们可以把欧元换到人民币。", "corrected_sentence": "我们可以把欧元换成人民币。", "error_description": "错误：补语用错，把“成”写成了“到”。正确：表示把一样变成另一样时要用“成”，“到”表示到达某处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去指已经过去的时间，与“将来”是时间上的一对反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是具体的家具，与时间概念的“将来”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是地理事物，与“将来”没有反义关系。"}, {"text": "草原", "is_correct": false, "explanation": "草原是地理环境，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去指已经过去的时间，与“将来”是时间上的一对反义词。", "桌子": "桌子是具体的家具，与时间概念的“将来”没有反义关系。", "河流": "河流是地理事物，与“将来”没有反义关系。", "草原": "草原是地理环境，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去与将来是时间上相对的一对反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是房屋的构件，与时间概念的“将来”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是具体的物体，与“将来”没有反义关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "牛奶是饮品，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去与将来是时间上相对的一对反义词。", "窗户": "窗户是房屋的构件，与时间概念的“将来”没有反义关系。", "石头": "石头是具体的物体，与“将来”没有反义关系。", "牛奶": "牛奶是饮品，与“将来”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来是还没有到的以后的日子。", "primary_collocate": null, "pronunciation": "jiāng lái", "ipa": "tɕjɑŋ˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "我将来想当医生。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来的日子还很长。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你将来想住在哪里？", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了将来，他现在努力学习。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来有一天，我要去看海。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不知道将来会怎么样。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在为将来的生活存钱。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的将来很重要。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要想一想将来。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来我有了钱，就买大房子。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "还没到的以后的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指还没到的以后的日子。"}, {"text": "向来", "is_correct": false, "explanation": "xiàng lái（第四声）与 jiāng lái（第一声）声母不同（x/j），意思是一向、从来，与“将来”不同。"}, {"text": "上来", "is_correct": false, "explanation": "shàng lái（第四声）与 jiāng lái（第一声）声母不同（sh/j），意思是走上来，与“将来”不同。"}, {"text": "进来", "is_correct": false, "explanation": "jìn lái（第四声）与 jiāng lái（第一声）韵母不同（in/iang），意思是走进来。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指还没到的以后的日子。", "向来": "xiàng lái（第四声）与 jiāng lái（第一声）声母不同（x/j），意思是一向、从来，与“将来”不同。", "上来": "shàng lái（第四声）与 jiāng lái（第一声）声母不同（sh/j），意思是走上来，与“将来”不同。", "进来": "jìn lái（第四声）与 jiāng lái（第一声）韵母不同（in/iang），意思是走进来。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“我___想当医生”需要表示以后时间的词，“将来”与“想当医生”的志向相合。"}, {"text": "今天", "is_correct": false, "explanation": "语义：“今天”限定在当天，而“想当医生”是长远的志向，不能只限于一天。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午”是一个时段，不能与表示长远理想的“想当医生”搭配。"}, {"text": "终于", "is_correct": false, "explanation": "副词“终于”表示经过一段过程后才出现的结果，与“我___想当医生”这种长远志向搭配不当。"}], "explanations": {"将来": "正确答案。“我___想当医生”需要表示以后时间的词，“将来”与“想当医生”的志向相合。", "今天": "语义：“今天”限定在当天，而“想当医生”是长远的志向，不能只限于一天。", "下午": "搭配：“下午”是一个时段，不能与表示长远理想的“想当医生”搭配。", "终于": "副词“终于”表示经过一段过程后才出现的结果，与“我___想当医生”这种长远志向搭配不当。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完饭将来，我们去散步。", "explanation": "这里应该用〈以后〉。将来指较远的未来，紧接着吃完饭的先后顺序要用以后。"}, {"text": "我们以前是同学，将来他去了上海。", "explanation": "这里应该用〈后来〉。将来只指还没到的时间，这句说的是已经发生的事，要用后来。"}, {"text": "我将来明天要去医院。", "explanation": "这里不能用〈将来〉。〈将来〉指较远、尚未确定的时间，与“明天”矛盾；应直接去掉〈将来〉，说“我明天要去医院。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指还没到的以后的日子。"}, {"text": "近来", "is_correct": false, "explanation": "jìn lái（第四声）与 jiāng lái 韵母不同（in/iang），意思是最近以来。"}, {"text": "讲理", "is_correct": false, "explanation": "jiǎng lǐ 与 jiāng lái 声调不同，lǐ 与 lái 韵母也不同，意思是讲道理。"}, {"text": "江南", "is_correct": false, "explanation": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。"}, {"text": "刚来", "is_correct": false, "explanation": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指还没到的以后的日子。", "近来": "jìn lái（第四声）与 jiāng lái 韵母不同（in/iang），意思是最近以来。", "讲理": "jiǎng lǐ 与 jiāng lái 声调不同，lǐ 与 lái 韵母也不同，意思是讲道理。", "江南": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。", "刚来": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“为___的生活存钱”需要指向以后的时间，“将来”符合存钱为未来准备的语义。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”是已经过去的人生阶段，不能作为存钱要为之准备的时间。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，与为以后的生活存钱的目的相矛盾。"}, {"text": "往年", "is_correct": false, "explanation": "搭配：“往年”指以前的年份，与“为……的生活存钱”搭配不当。"}], "explanations": {"将来": "正确答案。“为___的生活存钱”需要指向以后的时间，“将来”符合存钱为未来准备的语义。", "童年": "语义：“童年”是已经过去的人生阶段，不能作为存钱要为之准备的时间。", "当年": "语义：“当年”指过去的某一年，与为以后的生活存钱的目的相矛盾。", "往年": "搭配：“往年”指以前的年份，与“为……的生活存钱”搭配不当。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只将来很光明。", "explanation": "这里应该用〈个〉，不能用〈只〉。将来是抽象的时间，常说“一个光明的将来”，〈只〉用错了量词。"}, {"text": "他的将来已经过去了。", "explanation": "这里不能用〈将来〉指已经过去的时间。〈将来〉指还没有到的时间，已经过去的时间应该用〈以前〉。"}, {"text": "他很擅长回忆将来。", "explanation": "这里应该用〈展望〉。“回忆”针对已经发生的事，将来指还没有到的时间，不能回忆；谈论还没到的时间要用〈展望〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我将来了想去北京工作。", "corrected_sentence": "我将来想去北京工作。", "error_description": "“将来”是表示未来的时间名词，后面不能加“了”。正确的说法是“我将来想去北京工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一个光明将来。", "corrected_sentence": "他有一个光明的将来。", "error_description": "“将来”前的修饰语“光明”需要加“的”。正确的说法是“光明的将来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "正确答案。过去指已经过去的时间，与“将来”是时间上相对的一对反义词。"}, {"text": "书包", "is_correct": false, "explanation": "书包是具体的物品，与“将来”没有反义关系。"}, {"text": "茶杯", "is_correct": false, "explanation": "茶杯是具体的器物，与“将来”没有反义关系。"}, {"text": "山峰", "is_correct": false, "explanation": "山峰是地理事物，与“将来”没有反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "正确答案。过去指已经过去的时间，与“将来”是时间上相对的一对反义词。", "书包": "书包是具体的物品，与“将来”没有反义关系。", "茶杯": "茶杯是具体的器物，与“将来”没有反义关系。", "山峰": "山峰是地理事物，与“将来”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
