INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "现在以后的时间；未来。", "primary_collocate": null, "pronunciation": "jiāng lái", "ipa": "tɕjɑŋ˥ lai˧˥", "syllable_count": 2, "sentences": [{"text": "将来的世界会更方便。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对将来很有信心。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来天气会越来越热。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不远的将来，人们会坐飞船旅行。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题将来还要再谈。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们该为将来做好准备。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将来她一定会成功。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总想过去，多想想将来。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司将来会越做越大。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把将来的计划写在了本子上。", "target_word": "将来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "现在以后的时间，未来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。"}, {"text": "向来", "is_correct": false, "explanation": "xiàng lái（第四声）与 jiāng lái（第一声）声母不同（x/j），意思是一向、从来。"}, {"text": "上来", "is_correct": false, "explanation": "shàng lái（第四声）与 jiāng lái（第一声）声母不同（sh/j），意思是走上来。"}, {"text": "进来", "is_correct": false, "explanation": "jìn lái（第四声）与 jiāng lái（第一声）韵母不同（in/iang），意思是走进来。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。", "向来": "xiàng lái（第四声）与 jiāng lái（第一声）声母不同（x/j），意思是一向、从来。", "上来": "shàng lái（第四声）与 jiāng lái（第一声）声母不同（sh/j），意思是走上来。", "进来": "jìn lái（第四声）与 jiāng lái（第一声）韵母不同（in/iang），意思是走进来。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“___的世界会更方便”是对未来的预测，“将来”符合这一语义。"}, {"text": "过去", "is_correct": false, "explanation": "语义：“会”表示对未来的预测，与指已经过去的“过去”相矛盾。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，不能与表示未来预测的“会更方便”搭配。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”是过去的人生阶段，不能作为会变得更方便的世界的时间。"}], "explanations": {"将来": "正确答案。“___的世界会更方便”是对未来的预测，“将来”符合这一语义。", "过去": "语义：“会”表示对未来的预测，与指已经过去的“过去”相矛盾。", "当年": "语义：“当年”指过去的某一年，不能与表示未来预测的“会更方便”搭配。", "童年": "语义：“童年”是过去的人生阶段，不能作为会变得更方便的世界的时间。"}, "sentence_index": 0, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年买了房子，将来又搬走了。", "explanation": "这里应该用〈后来〉。将来只指还没到的时间，这句说的是去年已经发生的事，要用后来。"}, {"text": "我们吃完饭将来就去上课。", "explanation": "这里应该用〈以后〉。将来指较远的未来，紧接着吃完饭的先后顺序要用以后。"}, {"text": "这一只将来很遥远。", "explanation": "这里应该用〈个〉，不能用〈只〉。将来是抽象的时间，量词要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。"}, {"text": "讲理", "is_correct": false, "explanation": "jiǎng lǐ 与 jiāng lái 声调不同，lǐ 与 lái 韵母也不同，意思是讲道理。"}, {"text": "江南", "is_correct": false, "explanation": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。"}, {"text": "刚来", "is_correct": false, "explanation": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}], "explanations": {"将来": "正确答案。将来 jiāng lái 指现在以后的时间，即未来。", "讲理": "jiǎng lǐ 与 jiāng lái 声调不同，lǐ 与 lái 韵母也不同，意思是讲道理。", "江南": "jiāng nán 与 jiāng lái 的第二个音节声母不同（n/l），意思是长江以南的地区。", "刚来": "gāng lái（第一声）与 jiāng lái 声母不同（g/j），意思是刚到。"}, "sentence_index": null, "correct_answer": "将来"}, "level_3": {"options": [{"text": "将来", "is_correct": true, "explanation": "正确答案。“___她一定会成功”是对未来的判断，“将来”符合这一语义。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指刚刚过去的时间，与“一定会成功”的未来判断相矛盾。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指已经过去的一年，不能与表示未来判断的“一定会成功”搭配。"}, {"text": "眼前", "is_correct": false, "explanation": "搭配：“眼前”指当前的时刻，与“一定会成功”这种对长远结果的判断搭配不当。"}], "explanations": {"将来": "正确答案。“___她一定会成功”是对未来的判断，“将来”符合这一语义。", "刚才": "语义：“刚才”指刚刚过去的时间，与“一定会成功”的未来判断相矛盾。", "去年": "语义：“去年”指已经过去的一年，不能与表示未来判断的“一定会成功”搭配。", "眼前": "搭配：“眼前”指当前的时刻，与“一定会成功”这种对长远结果的判断搭配不当。"}, "sentence_index": 6, "correct_answer": "将来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把已经发生的将来写在了本子上。", "explanation": "这里不能用〈将来〉指已经发生的事。〈将来〉只指还没有到的时间，应改为“她把已经发生的事写在了本子上”。"}, {"text": "她把昨天的将来写在了本子上。", "explanation": "这里不能用〈将来〉指昨天这样已经过去的时间。〈将来〉只指还没有到的时间，应改为“她把昨天的计划写在了本子上”。"}, {"text": "她把一只将来写在了本子上。", "explanation": "这里应该用〈个〉，不能用〈只〉。将来是抽象的时间，量词要用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "将来了我们会有更多机会。", "corrected_sentence": "将来我们会有更多机会。", "error_description": "“将来”是表示未来的时间词，后面不能加“了”。正确的说法是“将来我们会有更多机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们将来以后会在北京工作。", "corrected_sentence": "我们将来会在北京工作。", "error_description": "“将来”与“以后”都表示时间，不能叠加使用。正确的说法是“我们将来会在北京工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "本来是说一开始就是这样的。", "primary_collocate": null, "pronunciation": "běn lái", "ipa": "pən˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "这本来是一家小饭店，现在很大了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来住在上海，后来搬到了北京。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本来不喜欢吃辣的，现在天天吃。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河本来很干净，现在有点脏了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来想去，可是下雨了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她本来是老师，后来开了一家店。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明本来很害羞，现在爱说话了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里本来没有路，是大家走出来的。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来打算坐火车去，但是票卖完了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子本来是白色的，用久了变黄了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本来就", "label": "搭配"}, {"form": "本來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "副词,指一开始的情况,后来有了变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示始终如此，与后半句“现在很大了”的变化相矛盾。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示一开始的情况，与“现在很大了”形成前后变化，句意正确。"}, {"text": "刚", "is_correct": false, "explanation": "体貌：“刚”表示刚刚发生的情况，不能说明一开始就是这样，与后文的变化不搭。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，不能说明这家店一开始的性质。"}], "explanations": {"一直": "语义：“一直”表示始终如此，与后半句“现在很大了”的变化相矛盾。", "本来": "本来表示一开始的情况，与“现在很大了”形成前后变化，句意正确。", "刚": "体貌：“刚”表示刚刚发生的情况，不能说明一开始就是这样，与后文的变化不搭。", "偶尔": "语义：“偶尔”表示不时发生，不能说明这家店一开始的性质。"}, "sentence_index": 0, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本来这条河这么脏啊！", "explanation": "这里应该用〈原来〉。原来用于说话人忽然发现真相时的感叹，本来只说明原先的状态，不能表示“才发现”。"}, {"text": "这条河本来变脏了。", "explanation": "这里应该用〈突然〉。突然表示事情忽然发生，本来只说明一开始的情况，不能表示变脏这一突然的变化。"}, {"text": "他本来又迟到了。", "explanation": "这里应该用〈又〉。又表示再次发生，本来表示一开始的情况，不能表示“再次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”指从未如此，多与否定连用，与“很害羞，现在爱说话了”的前后变化不符。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示一开始的性格，与“现在爱说话了”形成变化，句意正确。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，句中没有意外的语境，不能用来说明性格原先如何。"}, {"text": "赶快", "is_correct": false, "explanation": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“很害羞”这样的状态。"}], "explanations": {"从来": "语义：“从来”指从未如此，多与否定连用，与“很害羞，现在爱说话了”的前后变化不符。", "本来": "本来表示一开始的性格，与“现在爱说话了”形成变化，句意正确。", "竟然": "语义：“竟然”表示出乎意料，句中没有意外的语境，不能用来说明性格原先如何。", "赶快": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“很害羞”这样的状态。"}, "sentence_index": 6, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市本来渐渐热闹起来了。", "explanation": "这里应该用〈渐渐〉。渐渐描述逐步变化的过程，本来只说明一开始的情况，不能描述这种逐步的变化。"}, {"text": "经过三年努力，他本来学会了游泳。", "explanation": "这里应该用〈终于〉。终于表示经过努力最终实现，本来表示原先的情况，与“经过三年努力”的过程相矛盾。"}, {"text": "我本来在路上遇见了他，真巧。", "explanation": "这里应该用〈恰好〉。恰好表示碰巧遇上，本来只说明原先的情况，不能表达“碰巧”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个公园本来了一片荒地，现在变成了花园。", "corrected_sentence": "这个公园本来是一片荒地，现在变成了花园。", "error_description": "“本来”后面不能接动态助词“了”，应改为判断动词“是”，写作“这个公园本来是一片荒地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我本来不就爱喝咖啡，最近却天天喝。", "corrected_sentence": "我本来就不爱喝咖啡，最近却天天喝。", "error_description": "“就”应放在“本来”之后，写作“本来就”。“不就”与“本来”的组合中“就”位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
