INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88760, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词,表示原先、起初;也表示理应如此。", "primary_collocate": null, "pronunciation": "běn lái", "ipa": "pən˨˩˦ lai˧˥", "syllable_count": 2, "sentences": [{"text": "这件事本来就是你的错，应该道歉。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子本来就应该多睡觉。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生本来就要认真学习。", "target_word": "本来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你本来可以早点告诉我的。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人身体本来不好，不要让他太累。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我本来要出门，朋友突然来了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本来想休息一会儿，电话又响了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题本来很简单，你想得太难了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都是朋友，互相帮助本来就是应该的。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子本来是租的，现在我们买下来了。", "target_word": "本来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本来就", "label": "搭配"}, {"form": "本來", "label": "繁体"}], "register": "通用", "sense_fingerprint": "副词,指原先的情况,或表示事理上本该如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“就是你的错”这种既定判断冲突，句意不通。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示原先就是这样、理应如此，与“就是你的错，应该道歉”的语气一致。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不时发生，不能用来断定“这件事就是你的错”。"}, {"text": "并不", "is_correct": false, "explanation": "语义：“并不”表示否定，与“就是你的错”的判断相反，句意不通。"}], "explanations": {"突然": "语义：“突然”表示事情忽然发生，与“就是你的错”这种既定判断冲突，句意不通。", "本来": "本来表示原先就是这样、理应如此，与“就是你的错，应该道歉”的语气一致。", "偶尔": "语义：“偶尔”表示不时发生，不能用来断定“这件事就是你的错”。", "并不": "语义：“并不”表示否定，与“就是你的错”的判断相反，句意不通。"}, "sentence_index": 0, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本来你是老师！", "explanation": "这里应该用〈原来〉。原来用于说话人忽然发现真相时的感叹，本来只说明原先的身份或状态，不能表示“才知道”的惊讶。"}, {"text": "他才五岁，本来就考上了大学。", "explanation": "这里应该用〈竟然〉。竟然表示出乎意料的惊讶，本来只说明原先的情况或理应如此，句中没有惊讶的语气。"}, {"text": "我想早点睡，本来下雨了。", "explanation": "这里应该用〈偏偏〉。偏偏表示与预想或期望相反，本来只说明原先的情况，不能表达“与期望相反”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赶快", "is_correct": false, "explanation": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“想休息”这种心理活动的计划。"}, {"text": "本来", "is_correct": true, "explanation": "本来表示原先的打算，与后面“电话又响了”形成转折，句意通顺。"}, {"text": "居然", "is_correct": false, "explanation": "语义：“居然”表示出乎意料，句中没有意外的语境，与“想休息一会儿”的计划不符。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指从未如此，多与否定连用，与“想休息一会儿”的具体计划不符。"}], "explanations": {"赶快": "搭配：“赶快”多修饰要立即进行的动作，不能修饰“想休息”这种心理活动的计划。", "本来": "本来表示原先的打算，与后面“电话又响了”形成转折，句意通顺。", "居然": "语义：“居然”表示出乎意料，句中没有意外的语境，与“想休息一会儿”的计划不符。", "从来": "语义：“从来”指从未如此，多与否定连用，与“想休息一会儿”的具体计划不符。"}, "sentence_index": 6, "correct_answer": "本来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我猜他会迟到，他本来迟到了。", "explanation": "这里应该用〈果然〉。果然表示与预料相符，本来只说明原先的情况，不能表达“预料应验”。"}, {"text": "下雨了，我本来回家了。", "explanation": "这里应该用〈赶紧〉。赶紧表示急切地马上行动，本来只说明原先的情况，句中没有急迫的意思。"}, {"text": "经过努力，我本来考上了。", "explanation": "这里应该用〈终于〉。终于表示经过努力最后实现，本来只说明原先的情况，句中没有“最后得到结果”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的事故本来司机的错。", "corrected_sentence": "这次的事故本来是司机的错。", "error_description": "“本来”后面的判断动词“是”不能省略，应写作“本来是司机的错”。“本来司机的错”缺少“是”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没本来打算去，是朋友硬拉我去的。", "corrected_sentence": "我没打算去，是朋友硬拉我去的。", "error_description": "“本来”不能插在否定词“没”和动词“打算”之间，多出的“本来”应删去，写作“我没打算去”。删去后句子意思不变。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
