INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88765, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "户是住在一起的一家人。", "primary_collocate": null, "pronunciation": "hù", "ipa": "xu˥˩", "syllable_count": 1, "sentences": [{"text": "这个小区有一百户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一户就是住在一起的一家人。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家是一户普通人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这一户有五口人。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三代人住在一起，是一户大家庭。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请每户交一份表格。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁那户人家养了一只猫。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这户的爷爷奶奶都住在家里。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼里有两户搬走了。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一户的人今天都出门了。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戶", "label": "繁体"}, {"form": "农户", "label": "复合"}, {"form": "住户", "label": "复合"}], "register": "中性", "sense_fingerprint": "住在一起的一家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88765, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。户 hù 指住在一起的一家人。"}, {"text": "虎", "is_correct": false, "explanation": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。"}, {"text": "呼", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是胡须或胡同。"}], "explanations": {"户": "正确答案。户 hù 指住在一起的一家人。", "虎": "hǔ（第三声）与 hù（第四声）声调不同，意思是老虎。", "呼": "hū（第一声）与 hù（第四声）声调不同，意思是呼喊。", "胡": "hú（第二声）与 hù（第四声）声调不同，意思是胡须或胡同。"}, "sentence_index": null, "correct_answer": "户"}, "level_3": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。“这个小区有一百___”需要按家计数的量词，“户”符合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”用于计量小动物或成对的物品，不能用于计数小区的住户。"}, {"text": "扇", "is_correct": false, "explanation": "搭配：“扇”用于计量门窗，与“小区有一百”的住户搭配不当。"}, {"text": "张", "is_correct": false, "explanation": "语义：“张”用于计量平面的物品，不能用来计数小区的住户。"}], "explanations": {"户": "正确答案。“这个小区有一百___”需要按家计数的量词，“户”符合。", "只": "语义：“只”用于计量小动物或成对的物品，不能用于计数小区的住户。", "扇": "搭配：“扇”用于计量门窗，与“小区有一百”的住户搭配不当。", "张": "语义：“张”用于计量平面的物品，不能用来计数小区的住户。"}, "sentence_index": 0, "correct_answer": "户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一户树很高。", "explanation": "这里应该用〈棵〉。户只用于家庭，计算树要用〈棵〉。"}, {"text": "我们公司有一百户员工。", "explanation": "这里应该用〈名〉。户只用于计算家庭，计算员工要用〈名〉。"}, {"text": "这一户狗很聪明。", "explanation": "这里应该用〈只〉。户只用于家庭，计算狗要用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88765, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。户 hù 指住在一起的一家人。"}, {"text": "湖", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是湖泊。"}, {"text": "壶", "is_correct": false, "explanation": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。"}, {"text": "忽", "is_correct": false, "explanation": "hū（第一声）与 hù（第四声）声调不同，意思是忽然。"}], "explanations": {"户": "正确答案。户 hù 指住在一起的一家人。", "湖": "hú（第二声）与 hù（第四声）声调不同，意思是湖泊。", "壶": "hú（第二声）与 hù（第四声）声调不同，意思是水壶。", "忽": "hū（第一声）与 hù（第四声）声调不同，意思是忽然。"}, "sentence_index": null, "correct_answer": "户"}, "level_3": {"options": [{"text": "户", "is_correct": true, "explanation": "正确答案。“隔壁那___人家养了一只猫”需要按家计数的量词，“户”符合。"}, {"text": "位", "is_correct": false, "explanation": "语域：“位”是敬称，用来数有身份的人，不能用来指一户人家。"}, {"text": "间", "is_correct": false, "explanation": "语义：“间”用于计量房屋，不能用来指人家。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于计量山、楼等大型物体，与“人家”搭配不当。"}], "explanations": {"户": "正确答案。“隔壁那___人家养了一只猫”需要按家计数的量词，“户”符合。", "位": "语域：“位”是敬称，用来数有身份的人，不能用来指一户人家。", "间": "语义：“间”用于计量房屋，不能用来指人家。", "座": "搭配：“座”用于计量山、楼等大型物体，与“人家”搭配不当。"}, "sentence_index": 6, "correct_answer": "户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的户一直很和睦。", "explanation": "这里应该用〈家〉。〈户〉指住在一起的一家人这一单位，不能说“我家的户”来表示家庭的和睦；这种意思要用〈家〉。"}, {"text": "他推开了那扇户。", "explanation": "这里应该用〈门〉。现代汉语中“户”不指门，门才指门扇。"}, {"text": "全校都是这一户的学生。", "explanation": "这里应该用〈名〉或〈个〉，不能用〈户〉。户只用于家庭，计算学生不能用〈户〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
