INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88766, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人家；家庭。", "primary_collocate": null, "pronunciation": "hù", "ipa": "xu˥˩", "syllable_count": 1, "sentences": [{"text": "我们村有三十多户人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家是村里最穷的一户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼住着四十户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每户都有一台电视。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下有一户人家。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有五户人家。", "target_word": "户", "complexity_tier": "T3", "furigana": "zhè tiáo jiē shàng yǒu wǔ hù rén jiā", "sentence_source": "generated"}, {"text": "全村一共两百户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是新搬来的一户。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一户的孩子都在外地工作。", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一户的灯还亮着？", "target_word": "户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "戶", "label": "繁体"}, {"form": "农户", "label": "复合"}, {"form": "住户", "label": "复合"}], "register": "中性", "sense_fingerprint": "人家，家庭（按家计数）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =