INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "原有的东西消失了,不再有。", "primary_collocate": null, "pronunciation": "méi le", "ipa": "mei˧˥ lɤ", "syllable_count": 2, "sentences": [{"text": "我的手机放在桌上，一转身就没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停以后，天上的云都没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了以后，家里的笑声也没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的蛋糕怎么一会儿就没了？", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，那条小河没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不哭了，疼的感觉也慢慢没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天放在这儿的钱，今天没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡醒以后，头疼没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生气，好心情全没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子拆了，小时候的回忆也没了。", "target_word": "没了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有了", "label": "完整形式"}], "register": "口语", "sense_fingerprint": "原来存在的东西或感觉消失，不见了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：没了 méi le，表示原有的东西不见了。"}, {"text": "美了", "is_correct": false, "explanation": "měi（第三声）与 méi（第二声）只差声调，意思是变美。"}, {"text": "赔了", "is_correct": false, "explanation": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是亏了钱。"}, {"text": "肥了", "is_correct": false, "explanation": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}], "explanations": {"没了": "正确：没了 méi le，表示原有的东西不见了。", "美了": "měi（第三声）与 méi（第二声）只差声调，意思是变美。", "赔了": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是亏了钱。", "肥了": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}, "sentence_index": null, "correct_answer": "没了"}, "level_3": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：“没了”表示手机不见了，与“一转身”的语境相合。"}, {"text": "长大了", "is_correct": false, "explanation": "搭配：“长大”说人或动物，不能说手机长大了。"}, {"text": "会说话了", "is_correct": false, "explanation": "语义：手机不会说话，句意不通。"}, {"text": "发芽了", "is_correct": false, "explanation": "搭配：“发芽”只用于植物，不能用于手机。"}], "explanations": {"没了": "正确：“没了”表示手机不见了，与“一转身”的语境相合。", "长大了": "搭配：“长大”说人或动物，不能说手机长大了。", "会说话了": "语义：手机不会说话，句意不通。", "发芽了": "搭配：“发芽”只用于植物，不能用于手机。"}, "sentence_index": 0, "correct_answer": "没了"}, "level_6": {"correct_sentence_index": 5, "wrong_sentences": [{"text": "这座城市以前没了地铁，去年才开通。", "explanation": "这里应该用〈没有〉。没了表示原来有、后来消失，地铁以前从来没有，不能说没了。"}, {"text": "这家店的客流量比以前没了，老板很担心。", "explanation": "这里应该用〈减少〉。没了表示全部消失，客流量只是下降，不能用“比以前没了”这样的说法。"}, {"text": "他的爷爷去年没了，我们都很难过。", "explanation": "这里表示“去世”的委婉说法，指人死亡，与本题“东西消失、不再有”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_e