INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：没了 méi le，表示原有的东西不见了。"}, {"text": "魅了", "is_correct": false, "explanation": "mèi（第四声）与 méi（第二声）只差声调，意思是迷住、吸引。"}, {"text": "陪了", "is_correct": false, "explanation": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。"}, {"text": "肥了", "is_correct": false, "explanation": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}], "explanations": {"没了": "正确：没了 méi le，表示原有的东西不见了。", "魅了": "mèi（第四声）与 méi（第二声）只差声调，意思是迷住、吸引。", "陪了": "péi（第二声）与 méi（第二声）声母不同（p 与 m），意思是陪伴。", "肥了": "féi（第二声）与 méi（第二声）声母不同（f 与 m），意思是变胖。"}, "sentence_index": null, "correct_answer": "没了"}, "level_3": {"options": [{"text": "没了", "is_correct": true, "explanation": "正确：“没了”表示钱不见了，与“今天”的语境相合。"}, {"text": "醒了", "is_correct": false, "explanation": "语义：钱不会醒来，句意不通。"}, {"text": "生病了", "is_correct": false, "explanation": "搭配：“生病”只用于人或动物，不能用于钱。"}, {"text": "退休了", "is_correct": false, "explanation": "语义：钱不会退休，句意不通。"}], "explanations": {"没了": "正确：“没了”表示钱不见了，与“今天”的语境相合。", "醒了": "语义：钱不会醒来，句意不通。", "生病了": "搭配：“生病”只用于人或动物，不能用于钱。", "退休了": "语义：钱不会退休，句意不通。"}, "sentence_index": 6, "correct_answer": "没了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的人口没了，比去年多了一百万。", "explanation": "这里应该用〈增加〉。没了表示全部消失，人口只是增多，不能说没了。"}, {"text": "这次考试的成绩没了，我比上次进步了十分。", "explanation": "这里应该用〈提高〉。没了表示原有的东西全部消失，成绩是变好，不能说没了。"}, {"text": "这个公园的面积没了，比以前大了不少。", "explanation": "这里应该用〈扩大〉。没了表示全部消失，面积只是变大，不能说没了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一转身，桌上的饼干就不没了。", "corrected_sentence": "妈妈一转身，桌上的饼干就没了。", "error_description": "错误：“不没了”。应改为“没了”。“没”本身已表示否定，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只小猫跑进巷子以后就没了了。", "corrected_sentence": "那只小猫跑进巷子以后就没了。", "error_description": "错误：“没了了”。应改为“没了”。“没了”中的“了”已经表示完成，后面不能再加一个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮形容光线或颜色，与两人感情好坏没有反义关系。"}, {"text": "高大", "is_correct": false, "explanation": "高大形容身材或事物的体积，与“要好”没有反义关系。"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋形容做事认真努力，与“要好”描述的感情关系无关。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。", "明亮": "明亮形容光线或颜色，与两人感情好坏没有反义关系。", "高大": "高大形容身材或事物的体积，与“要好”没有反义关系。", "勤奋": "勤奋形容做事认真努力，与“要好”描述的感情关系无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏远", "is_correct": true, "explanation": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事专注严肃，与“要好”描述的感情关系无关。"}, {"text": "宽大", "is_correct": false, "explanation": "宽大形容空间或态度宽厚，与“要好”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、分明，与“要好”没有反义关系。"}], "correct_answer": "疏远", "explanations": {"疏远": "疏远指彼此感情变淡、不常往来，与“要好”的感情亲密正相反。", "认真": "认真形容做事专注严肃，与“要好”描述的感情关系无关。", "宽大": "宽大形容空间或态度宽厚，与“要好”没有反义关系。", "清楚": "清楚指明白、分明，与“要好”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "要好是两个人感情很好,常在一起。", "primary_collocate": null, "pronunciation": "yào hǎo", "ipa": "jau˥˩ xau˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们俩是最要好的朋友。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和小李从小就很要好。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们两个要好得像姐妹一样。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同桌很要好，天天一起回家。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩很要好，每天一起吃饭。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个要好的同学，我们住在同一个房间。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那两个男孩要好极了，走到哪儿都在一起。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红和小美从小学起就要好，常在一起玩。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在班里，你和谁最要好？", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是要好的邻居，常常一起去买菜。", "target_word": "要好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很要好", "label": "程度"}, {"form": "最要好", "label": "程度"}, {"form": "要好的", "label": "定语形式"}, {"form": "要好了", "label": "体标"}], "register": "通用", "sense_fingerprint": "两人感情好,常常在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50f9bf01-77e1-4860-be55-4cc38b1afce6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": false, "explanation": "语义：“陌生”指彼此不熟悉，与“朋友”的身份相矛盾。"}, {"text": "要好", "is_correct": true, "explanation": "要好形容两人感情好、关系亲密，正好修饰“朋友”，句意通顺。"}, {"text": "敌对", "is_correct": false, "explanation": "语义：“敌对”指互相对立，与“朋友”的关系正好相反。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”多形容身体或物品的坚固，不能修饰表示人际关系的“朋友”。"}], "explanations": {"陌生": "语义：“陌生”指彼此不熟悉，与“朋友”的身份相矛盾。", "要好": "要好形容两人感情好、关系亲密，正好修饰“朋友”，句意通顺。", "敌对": "语义：“敌对”指互相对立，与“朋友”的关系正好相反。", "结实": "搭配：“结实”多形容身体或物品的坚固，不能修饰表示人际关系的“朋友”。"}, "sentence_index": 0, "correct_answer": "要好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑很要好。", "explanation": "这里应该用〈好用〉。好用形容物品使用方便，要好只形容两人之间的感情，不能用于电脑。"}, {"text": "他的成绩很要好。", "explanation": "这里应该用〈优秀〉。优秀形容成绩、能力等表现，要好只描述人与人之间的感情，不能形容成绩。"}, {"text": "我对这个城市很要好。", "explanation": "这里应该用〈熟悉〉。熟悉指对地方或事物了解，要好只描述两人之间的感情，不能用于城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷淡", "is_correct": false, "explanation": "语义：“冷淡”指不热情、疏远，与“走到哪儿都在一起”的亲密情形相矛盾。"}, {"text": "要好", "is_correct": true, "explanation": "要好形容两人关系亲密，与后半句“走到哪儿都在一起”一致。"}, {"text": "独立", "is_correct": false, "explanation": "语义：“独立”指不依赖他人，与“走到哪儿都在一起”的状态不符。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”多形容物体的硬度，不能用来形容两个男孩的关系或状态。"}], "explanations": {"冷淡": "语义：“冷淡”指不热情、疏远，与“走到哪儿都在一起”的亲密情形相矛盾。", "要好": "要好形容两人关系亲密，与后半句“走到哪儿都在一起”一致。", "独立": "语义：“独立”指不依赖他人，与“走到哪儿都在一起”的状态不符。", "坚硬": "搭配：“坚硬”多形容物体的硬度，不能用来形容两个男孩的关系或状态。"}, "sentence_index": 6, "correct_answer": "要好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很要好。", "explanation": "这里应该用〈不错〉。不错用于评价菜肴、物品的质量，要好只形容人与人之间感情深，不能形容菜。"}, {"text": "这个方案很要好。", "explanation": "这里应该用〈可行〉。可行形容方案能够实施，要好只形容两人之间的感情，不能用来形容方案。"}, {"text": "这份报告写得很要好。", "explanation": "这里应该用〈精彩〉。精彩形容内容出色、吸引人，要好只形容两人之间的感情，不能用来评价报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把隔壁的王叔叔要好，从小一起长大。", "corrected_sentence": "我和隔壁的王叔叔要好，从小一起长大。", "error_description": "“要好”表示与某人关系好，要用“和”引出对象，写作“我和隔壁的王叔叔要好”。“我把隔壁的王叔叔要好”中“把”用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她们俩要好地不得了，上课也坐在一起。", "corrected_sentence": "她们俩要好得不得了，上课也坐在一起。", "error_description": "“要好”后面的程度补语要用“得”，写作“要好得不得了”。“地”是状语的标记，不能用在补语的位置，“要好地不得了”中“地”用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd60f9f3-3a27-4305-8168-187120f5ca62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
