INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88813, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "来着放在话的最后,说的是以前发生过的事。", "primary_collocate": null, "pronunciation": "lái zhe", "ipa": "lai˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "你刚才说什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他叫什么名字来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们去哪儿来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的钥匙放哪儿来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚才还在这儿看书来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚才在做什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字怎么写来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师昨天讲什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上还在家睡觉来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们几点见面来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "来着:助词:句末,说以前发生过的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来着", "is_correct": true, "explanation": "目标词：句末语气词，追问或回忆过去的事，读作 lái zhe。"}, {"text": "赖着", "is_correct": false, "explanation": "赖着 lài zhe 第一个音节 lài（第四声）与 lái（第二声）声调不同，意思是赖着不走。"}, {"text": "拦着", "is_correct": false, "explanation": "拦着 lán zhe 第一个音节韵母不同（an 与 ai），意思是阻拦。"}, {"text": "离着", "is_correct": false, "explanation": "离着 lí zhe 第一个音节少了韵母 a，意思是距离某处有一段距离。"}], "explanations": {"来着": "目标词：句末语气词，追问或回忆过去的事，读作 lái zhe。", "赖着": "赖着 lài zhe 第一个音节 lài（第四声）与 lái（第二声）声调不同，意思是赖着不走。", "拦着": "拦着 lán zhe 第一个音节韵母不同（an 与 ai），意思是阻拦。", "离着": "离着 lí zhe 第一个音节少了韵母 a，意思是距离某处有一段距离。"}, "sentence_index": null, "correct_answer": "来着"}, "level_3": {"options": [{"text": "来着", "is_correct": true, "explanation": "来着：句末语气词，追问过去的事，与“刚才”相符。"}, {"text": "吗", "is_correct": false, "explanation": "搭配：“吗”不能与疑问代词“什么”并用，句末不能加“吗”。"}, {"text": "罢", "is_correct": false, "explanation": "语域：“罢”是书面语，口语里不这样用。"}, {"text": "呗", "is_correct": false, "explanation": "搭配：“呗”用于“就……呗”等结构，不接在疑问句末尾。"}], "explanations": {"来着": "来着：句末语气词，追问过去的事，与“刚才”相符。", "吗": "搭配：“吗”不能与疑问代词“什么”并用，句末不能加“吗”。", "罢": "语域：“罢”是书面语，口语里不这样用。", "呗": "搭配：“呗”用于“就……呗”等结构，不接在疑问句末尾。"}, "sentence_index": 0, "correct_answer": "来着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你快点来着。", "explanation": "「来着」只用于回忆过去曾发生的事，不能用于命令或请求；这里应去掉“来着”。"}, {"text": "我每天都吃饭来着。", "explanation": "「来着」回忆某一次具体的事，不用于说习惯性的动作。"}, {"text": "我现在很饿来着。", "explanation": "「来着」回忆过去的事，不能描述此刻的状态；这里应去掉“来着”，说“我现在很饿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88813, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来着", "is_correct": true, "explanation": "目标词：句末语气词，追问或回忆过去的事，读作 lái zhe。"}, {"text": "拉着", "is_correct": false, "explanation": "拉着 lā zhe 第一个音节 lā（第一声）与 lái 声调和韵母都不同，意思是拉扯。"}, {"text": "立着", "is_correct": false, "explanation": "立着 lì zhe 第一个音节声调和韵母都不同，意思是站立着。"}, {"text": "垒着", "is_correct": false, "explanation": "垒着 lěi zhe 第一个音节声调与韵母都不同，意思是堆叠着。"}, {"text": "来者", "is_correct": false, "explanation": "来者 lái zhě 第二个音节 zhě（第三声）与 zhe 声调不同，意思是来的人，多用于书面语。"}], "explanations": {"来着": "目标词：句末语气词，追问或回忆过去的事，读作 lái zhe。", "拉着": "拉着 lā zhe 第一个音节 lā（第一声）与 lái 声调和韵母都不同，意思是拉扯。", "立着": "立着 lì zhe 第一个音节声调和韵母都不同，意思是站立着。", "垒着": "垒着 lěi zhe 第一个音节声调与韵母都不同，意思是堆叠着。", "来者": "来者 lái zhě 第二个音节 zhě（第三声）与 zhe 声调不同，意思是来的人，多用于书面语。"}, "sentence_index": null, "correct_answer": "来着"}, "level_3": {"options": [{"text": "来着", "is_correct": true, "explanation": "来着：句末语气词，追问过去的事，与“这个字怎么写”相符。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，口语里不用。"}, {"text": "吗", "is_correct": false, "explanation": "搭配：“吗”不能与疑问代词“怎么”并用，句末不能加“吗”。"}, {"text": "而已", "is_correct": false, "explanation": "搭配：“而已”表示“只是如此”，不构成疑问句。"}], "explanations": {"来着": "来着：句末语气词，追问过去的事，与“这个字怎么写”相符。", "哉": "语域：“哉”是文言语气词，口语里不用。", "吗": "搭配：“吗”不能与疑问代词“怎么”并用，句末不能加“吗”。", "而已": "搭配：“而已”表示“只是如此”，不构成疑问句。"}, "sentence_index": 6, "correct_answer": "来着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他现在是老师来着。", "explanation": "「来着」回忆过去的事，不能描述现在的身份；这里应去掉“来着”，说“他现在是老师”。"}, {"text": "我现在正在看书来着。", "explanation": "「来着」只用于回忆过去曾发生的事，不能用于描述此刻正在进行的动作。"}, {"text": "明天我们一起吃饭来着。", "explanation": "「来着」回忆过去的事，不能用于说将来的安排；这里应去掉“来着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你刚才说了什么来着了？", "corrected_sentence": "你刚才说了什么来着？", "error_description": "错误在“了”的位置：“来着”已是句末语气词，其后不能再加“了”。正确说法是“你刚才说了什么来着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你上次说要去哪里来着吗？", "corrected_sentence": "你上次说要去哪里来着？", "error_description": "错误在语气词：“来着”已表示追问，句末不能再加疑问语气词“吗”。正确说法是“你上次说要去哪里来着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
