INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词,用于句末,表示过去曾经发生的事,有时用于追问。", "primary_collocate": null, "pronunciation": "lái zhe", "ipa": "lai˧˥ ʈʂɤ˙", "syllable_count": 2, "sentences": [{"text": "他前天去哪儿来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是谁的来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天在哪儿见过你来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们刚才在聊什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的生日是几号来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚才还在找你来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候学过画画来着。", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店叫什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们上周看的电影叫什么来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁昨天给你打电话来着?", "target_word": "来着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "来着:语气助词:句末,表过去曾发生的事,可追问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来着", "is_correct": true, "explanation": "目标词：语气助词，句末表示过去的事，有时用于追问，读作 lái zhe。"}, {"text": "拉着", "is_correct": false, "explanation": "拉着 lā zhe 第一个音节 lā（第一声）与 lái 声调和韵母都不同，意思是拉扯。"}, {"text": "立着", "is_correct": false, "explanation": "立着 lì zhe 第一个音节声调和韵母都不同，意思是站立着。"}, {"text": "来者", "is_correct": false, "explanation": "来者 lái zhě 第二个音节 zhě（第三声）与 zhe 声调不同，意思是来的人，多用于书面语。"}], "explanations": {"来着": "目标词：语气助词，句末表示过去的事，有时用于追问，读作 lái zhe。", "拉着": "拉着 lā zhe 第一个音节 lā（第一声）与 lái 声调和韵母都不同，意思是拉扯。", "立着": "立着 lì zhe 第一个音节声调和韵母都不同，意思是站立着。", "来者": "来者 lái zhě 第二个音节 zhě（第三声）与 zhe 声调不同，意思是来的人，多用于书面语。"}, "sentence_index": null, "correct_answer": "来着"}, "level_3": {"options": [{"text": "来着", "is_correct": true, "explanation": "来着：语气助词，句末追问过去的事，与“前天”相符。"}, {"text": "吗", "is_correct": false, "explanation": "搭配：“吗”不能与疑问代词“哪儿”并用，句末不能加“吗”。"}, {"text": "哉", "is_correct": false, "explanation": "语域：“哉”是文言语气词，口语里不用。"}, {"text": "而已", "is_correct": false, "explanation": "搭配：“而已”不接在疑问词“哪儿”之后。"}], "explanations": {"来着": "来着：语气助词，句末追问过去的事，与“前天”相符。", "吗": "搭配：“吗”不能与疑问代词“哪儿”并用，句末不能加“吗”。", "哉": "语域：“哉”是文言语气词，口语里不用。", "而已": "搭配：“而已”不接在疑问词“哪儿”之后。"}, "sentence_index": 0, "correct_answer": "来着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "快去做作业来着。", "explanation": "「来着」只用于回忆过去的事，不能用于催促或命令；这里应去掉“来着”。"}, {"text": "他现在正在跑步来着。", "explanation": "「来着」回忆过去，不能用于描述此刻正在进行的动作；这里应去掉“来着”。"}, {"text": "明天天气很好来着。", "explanation": "「来着」回忆过去的事，不能用于预测将来的天气；这里应去掉“来着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来着", "is_correct": true, "explanation": "目标词：语气助词，句末表示过去的事，读作 lái zhe。"}, {"text": "赖着", "is_correct": false, "explanation": "赖着 lài zhe 第一个音节 lài（第四声）与 lái（第二声）声调不同，意思是赖着不走。"}, {"text": "拦着", "is_correct": false, "explanation": "拦着 lán zhe 第一个音节韵母不同（an 与 ai），意思是阻拦。"}, {"text": "离着", "is_correct": false, "explanation": "离着 lí zhe 第一个音节少了韵母 a，意思是距离某处有一段距离。"}], "explanations": {"来着": "目标词：语气助词，句末表示过去的事，读作 lái zhe。", "赖着": "赖着 lài zhe 第一个音节 lài（第四声）与 lái（第二声）声调不同，意思是赖着不走。", "拦着": "拦着 lán zhe 第一个音节韵母不同（an 与 ai），意思是阻拦。", "离着": "离着 lí zhe 第一个音节少了韵母 a，意思是距离某处有一段距离。"}, "sentence_index": null, "correct_answer": "来着"}, "level_3": {"options": [{"text": "来着", "is_correct": true, "explanation": "来着：语气助词，句末说过去曾发生的事，与“小时候学过画画”相符。"}, {"text": "罢", "is_correct": false, "explanation": "语域：“罢”是书面语，口语里不这样用。"}, {"text": "呗", "is_correct": false, "explanation": "搭配：“呗”用于“就……呗”等结构，不用于陈述过去的事。"}, {"text": "的", "is_correct": false, "explanation": "语法：句末“的”不能单独用于陈述句，需与“是”搭配或构成名词化结构。"}], "explanations": {"来着": "来着：语气助词，句末说过去曾发生的事，与“小时候学过画画”相符。", "罢": "语域：“罢”是书面语，口语里不这样用。", "呗": "搭配：“呗”用于“就……呗”等结构，不用于陈述过去的事。", "的": "语法：句末“的”不能单独用于陈述句，需与“是”搭配或构成名词化结构。"}, "sentence_index": 6, "correct_answer": "来着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我现在在北京来着。", "explanation": "「来着」回忆过去曾发生的事，不能用于描述此刻的位置；这里应去掉“来着”。"}, {"text": "请你给我打电话来着。", "explanation": "「来着」只用于回忆过去的事，不能用于请求或命令；这里应去掉“来着”。"}, {"text": "他现在很高兴来着。", "explanation": "「来着」回忆过去的事，不能描述此刻的心情；这里应去掉“来着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你昨天买了什么来着了？", "corrected_sentence": "你昨天买了什么来着？", "error_description": "错误在“了”的位置：“来着”已是句末语气词，其后不能再加“了”。正确说法是“你昨天买了什么来着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谁昨天给你打了电话来着吗？", "corrected_sentence": "谁昨天给你打了电话来着？", "error_description": "错误在语气词：“来着”已表示追问，句末不能再加疑问语气词“吗”。正确说法是“谁昨天给你打了电话来着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
