INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家之间缔结的、规定相互权利和义务的书面协议。", "primary_collocate": null, "pronunciation": "tiáo yuē", "ipa": "tʰiɑʊ˧˥ ɥɛ˥", "syllable_count": 2, "sentences": [{"text": "两国政府正式签署了贸易条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该条约规定了双方的权利和义务。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条约经议会批准后才能生效。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项条约于去年六月开始生效。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国代表在首都缔结了友好条约。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条约的内容必须由双方共同遵守。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是国际条约的历史。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方违反条约，另一方可以提出抗议。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份边界条约解决了多年的争端。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判持续数月，条约终于签订。", "target_word": "条约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條約", "label": "繁体"}, {"form": "贸易条约", "label": "复合"}, {"form": "国际条约", "label": "复合"}, {"form": "一项条约", "label": "量词"}], "register": "书面", "sense_fingerprint": "国家间缔结的、规定权利和义务的书面协议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb1a83c7-686e-430e-8a43-46799c4d78f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确答案：条约（tiáo yuē），国家间缔结的书面协议。"}, {"text": "跳跃", "is_correct": false, "explanation": "跳跃（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，意思是跳起来。"}, {"text": "调阅", "is_correct": false, "explanation": "调阅（tiáo yuè）第二字为第四声，与条约的第二字第一声不同，意思是查阅档案。"}, {"text": "跳越", "is_correct": false, "explanation": "跳越（tiào yuè）两个字的声调都与条约不同，意思是跳过去。"}], "explanations": {"条约": "正确答案：条约（tiáo yuē），国家间缔结的书面协议。", "跳跃": "跳跃（tiào yuè）两个字的声调都与条约（tiáo yuē）不同，意思是跳起来。", "调阅": "调阅（tiáo yuè）第二字为第四声，与条约的第二字第一声不同，意思是查阅档案。", "跳越": "跳越（tiào yuè）两个字的声调都与条约不同，意思是跳过去。"}, "sentence_index": null, "correct_answer": "条约"}, "level_3": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确：“条约”是国家间缔结的书面协议，与“两国政府正式签署了贸易……”相符。"}, {"text": "产品", "is_correct": false, "explanation": "搭配：“签署”用于条约、合同等文件，不能签署产品。"}, {"text": "食品", "is_correct": false, "explanation": "搭配：“签署”的对象是文件，不能说签署食品。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是活动，不能被签署，句子说的是签订文件。"}], "explanations": {"条约": "正确：“条约”是国家间缔结的书面协议，与“两国政府正式签署了贸易……”相符。", "产品": "搭配：“签署”用于条约、合同等文件，不能签署产品。", "食品": "搭配：“签署”的对象是文件，不能说签署食品。", "演唱会": "语义：演唱会是活动，不能被签署，句子说的是签订文件。"}, "sentence_index": 0, "correct_answer": "条约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和朋友签了一份借款条约，期限一年。", "explanation": "这里应该用〈协议〉。条约专指国家之间的约定，个人之间的借款约定用协议。"}, {"text": "公司和供应商签了一份采购条约，付款方式很清楚。", "explanation": "这里应该用〈合同〉。企业之间的交易应签合同，条约只用于国家之间。"}, {"text": "这个俱乐部今天修改了一份条约，大家都同意。", "explanation": "这里应该用〈章程〉。俱乐部内部的规则用章程，条约只指国家之间的书面协议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条约", "is_correct": true, "explanation": "正确：“条约”是国家间的书面协议，与“他研究的是国际……的历史”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能作为国际关系历史的研究对象。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是性格，不是国际研究的对象。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是建筑部件，不是历史研究的内容。"}], "explanations": {"条约": "正确：“条约”是国家间的书面协议，与“他研究的是国际……的历史”相符。", "身高": "体貌：“身高”指人的高矮，不能作为国际关系历史的研究对象。", "脾气": "语义：“脾气”是性格，不是国际研究的对象。", "窗户": "语义：“窗户”是建筑部件，不是历史研究的内容。"}, "sentence_index": 6, "correct_answer": "条约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在班会上签了一份条约，保证按时完成作业。", "explanation": "这里应该用〈承诺书〉。条约只用于国家之间，同学个人的书面保证应用承诺书。"}, {"text": "社区门口贴出了一份条约，请大家遵守。", "explanation": "这里应该用〈公约〉。条约专指国家之间的约定，社区内部的共同约定用公约。"}, {"text": "两家人在院子里签了一份条约，互相帮忙看孩子。", "explanation": "这里应该用〈约定〉。条约专指国家之间的书面约定，两家人之间的约定不用条约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国政府正式签署了一只贸易条约。", "corrected_sentence": "两国政府正式签署了一份贸易条约。", "error_description": "量词错误：“只”用于动物等，不能修饰条约。应改为“一份”，即“签署了一份贸易条约”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
