INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "样子是人在某种情绪下表现出来的神态。", "primary_collocate": null, "pronunciation": "yàng zi", "ipa": "jɑŋ˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "看他生气的样子，我不敢说话。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子高兴的样子真可爱。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她着急的样子让大家很担心。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他装出一副很累的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老师来了，他马上做出认真的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你难过的样子，我不想再看到。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗等主人回家时，一副可怜的样子。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思的样子，让我想笑。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说话的样子很温柔。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟害怕的样子，大家都看见了。", "target_word": "样子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "副", "label": "量词"}, {"form": "样儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "人在某种情绪下表现出来的神态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1081a25-9b81-4cdc-b757-e82976d3359f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指人的神态或事物的模样，读 yàng zi。"}, {"text": "燕子", "is_correct": false, "explanation": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。"}, {"text": "养子", "is_correct": false, "explanation": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng 与 yàng 声母不同（x/y），意思是巷子（小路）。"}, {"text": "浪子", "is_correct": false, "explanation": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}], "explanations": {"样子": "正确。“样子”指人的神态或事物的模样，读 yàng zi。", "燕子": "yàn（第四声）与 yàng 韵母不同（an/ang），意思是燕子（一种鸟）。", "养子": "yǎng（第三声）与 yàng（第四声）声调不同，意思是养子（被收养的孩子）。", "巷子": "xiàng 与 yàng 声母不同（x/y），意思是巷子（小路）。", "浪子": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“看他生气的样子”指生气时的神态，与句意一致。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用“看”来表示生气时的神情。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与“生气”时的神态无关，句子是在描写他的神态。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“看”的对象是可见的神情，“味道”不能用“看”来表示。"}], "explanations": {"样子": "正确。“看他生气的样子”指生气时的神态，与句意一致。", "价格": "搭配：“价格”不能用“看”来表示生气时的神情。", "年龄": "语义：“年龄”与“生气”时的神态无关，句子是在描写他的神态。", "味道": "搭配：“看”的对象是可见的神情，“味道”不能用“看”来表示。"}, "sentence_index": 0, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他装出一只很累的样子。", "explanation": "这里应该用〈副〉。指神态的“样子”用量词“副”，不用“只”。"}, {"text": "这首曲子的样子很响亮。", "explanation": "这里应该用〈声音〉。“样子”指神态或外形，不能用来形容声音的洪亮。"}, {"text": "这个木箱的样子很重。", "explanation": "这里应该用〈分量〉。“样子”指外形或神态，不说物体的轻重；表示轻重要用“分量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“样子”指神态或模样，读 yàng zi。"}, {"text": "胖子", "is_correct": false, "explanation": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。"}, {"text": "帐子", "is_correct": false, "explanation": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。"}, {"text": "浪子", "is_correct": false, "explanation": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。"}, {"text": "棒子", "is_correct": false, "explanation": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}], "explanations": {"样子": "正确。“样子”指神态或模样，读 yàng zi。", "胖子": "pàng 与 yàng 声母不同（p/y），意思是胖子（体型胖的人）。", "帐子": "zhàng 与 yàng 只差声母（zh/y），意思是帐子（蚊帐等遮挡用的布罩）。", "浪子": "làng 与 yàng 只差声母（l/y），意思是浪子（行为放荡或不务正业的人）。", "棒子": "bàng 与 yàng 声母不同（b/y），意思是棒子（棍子或玉米）。"}, "sentence_index": null, "correct_answer": "样子"}, "level_3": {"options": [{"text": "样子", "is_correct": true, "explanation": "正确。“一副可怜的样子”指小狗等主人时的神态，与句意一致。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是器具，不能指小狗的神态。"}, {"text": "盔甲", "is_correct": false, "explanation": "语义：“盔甲”是护身器物，与小狗等主人回家的神态无关。"}, {"text": "扑克", "is_correct": false, "explanation": "搭配：“可怜”修饰的应是神态或处境，不能修饰扑克牌。"}], "explanations": {"样子": "正确。“一副可怜的样子”指小狗等主人时的神态，与句意一致。", "眼镜": "语义：“眼镜”是器具，不能指小狗的神态。", "盔甲": "语义：“盔甲”是护身器物，与小狗等主人回家的神态无关。", "扑克": "搭配：“可怜”修饰的应是神态或处境，不能修饰扑克牌。"}, "sentence_index": 6, "correct_answer": "样子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水的样子很高。", "explanation": "这里应该用〈温度〉。“样子”指外形或神态，不用来说明温度高低。"}, {"text": "弟弟害怕的样子很鲜艳。", "explanation": "这里应该用〈颜色〉。“样子”指外形或神态，不用来形容色彩的鲜艳；色彩鲜艳要用“颜色”来说。"}, {"text": "弟弟一条害怕的样子，大家都看见了。", "explanation": "这里应该用量词〈副〉。“条”用于细长的物体，不能修饰神态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他露出一副很高兴样子。", "corrected_sentence": "他露出一副很高兴的样子。", "error_description": "错误：“很高兴样子”；正确：“很高兴的样子”。形容词修饰“样子”时，中间要加结构助词“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她伤心得样子，让我很难受。", "corrected_sentence": "她伤心的样子，让我很难受。", "error_description": "错误：“伤心得样子”；正确：“伤心的样子”。修饰“样子”时用结构助词“的”，“得”用于连接补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ec6af9-0e7e-4859-b170-b915bd6369a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发出是把声音、光、东西从里面送到外面。", "primary_collocate": null, "pronunciation": "fā chū", "ipa": "fa˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "信已经发出去了。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天把包裹发出了。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一亮，就发出红色的光。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗发出低低的叫声。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炉子里发出一股香味。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把快递发出了，明天就到。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱发出很响的声音。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把请柬都发出了。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手电筒发出一道白光。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里发出笑声。", "target_word": "发出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发出了", "label": "体标"}, {"form": "发出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，把声音、光、东西从里面送到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "发出", "is_correct": true, "explanation": "正确：发出（fā chū）指把声音、光、东西从里面送到外面。"}, {"text": "付出", "is_correct": false, "explanation": "fù（第四声）与 fā（第一声）韵母和声调都不同，“付出”意思是付出代价或精力，不是送出。"}, {"text": "翻出", "is_correct": false, "explanation": "fān（第一声）与 fā（第一声）韵尾不同（多了 n），“翻出”意思是翻找出来，不是送出。"}, {"text": "发愁", "is_correct": false, "explanation": "chóu（第二声）与 chū（第一声）韵母不同，“发愁”意思是忧虑，不是送出。"}], "explanations": {"发出": "正确：发出（fā chū）指把声音、光、东西从里面送到外面。", "付出": "fù（第四声）与 fā（第一声）韵母和声调都不同，“付出”意思是付出代价或精力，不是送出。", "翻出": "fān（第一声）与 fā（第一声）韵尾不同（多了 n），“翻出”意思是翻找出来，不是送出。", "发愁": "chóu（第二声）与 chū（第一声）韵母不同，“发愁”意思是忧虑，不是送出。"}, "sentence_index": null, "correct_answer": "发出"}, "level_3": {"options": [{"text": "发出", "is_correct": true, "explanation": "正确：“发出去”指把信从自己这里送到外面，即寄出。"}, {"text": "发财", "is_correct": false, "explanation": "搭配：“发财”指致富，不能用来说“信已经发财去了”。"}, {"text": "发动", "is_correct": false, "explanation": "搭配：“发动”接“车辆、攻势”等，不接“信”。"}, {"text": "发表", "is_correct": false, "explanation": "语义：“发表”指公开刊登或宣布，与寄出信件的意思不符。"}], "explanations": {"发出": "正确：“发出去”指把信从自己这里送到外面，即寄出。", "发财": "搭配：“发财”指致富，不能用来说“信已经发财去了”。", "发动": "搭配：“发动”接“车辆、攻势”等，不接“信”。", "发表": "语义：“发表”指公开刊登或宣布，与寄出信件的意思不符。"}, "sentence_index": 0, "correct_answer": "发出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天公园里发出了一件怪事。", "explanation": "这里应该用〈发生〉。发生指事情出现，发出指声音、光、物品等向外送出，不能用来指事件出现。"}, {"text": "这次培训让他充分发出了潜力。", "explanation": "这里应该用〈发挥〉。“发挥潜力”是固定搭配，“发出”不能接“潜力”。"}, {"text": "这件事发出了大家的注意。", "explanation": "这里应该用〈引起〉。引起指使人注意；发出不能与“注意”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发出", "is_correct": true, "explanation": "正确：“发出很响的声音”是说冰箱向外传出很响的声音。"}, {"text": "发射", "is_correct": false, "explanation": "语义：“发射”指射出导弹、火箭等物体，冰箱不能发射声音。"}, {"text": "发现", "is_correct": false, "explanation": "语义：“发现”指察觉或找到，冰箱不能“发现”声音。"}, {"text": "发展", "is_correct": false, "explanation": "搭配：“发展”接抽象事物，不接“声音”。"}], "explanations": {"发出": "正确：“发出很响的声音”是说冰箱向外传出很响的声音。", "发射": "语义：“发射”指射出导弹、火箭等物体，冰箱不能发射声音。", "发现": "语义：“发现”指察觉或找到，冰箱不能“发现”声音。", "发展": "搭配：“发展”接抽象事物，不接“声音”。"}, "sentence_index": 6, "correct_answer": "发出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位科学家发出了一种新药。", "explanation": "这里应该用〈发明〉。发明指创造出新事物；发出用于声音、光等向外传出，不能指制造出新药。"}, {"text": "他把怒气发出在球场上。", "explanation": "这里应该用〈发泄〉。发泄指把情绪宣泄出来；发出不能接“怒气”这类情绪。"}, {"text": "这个想法发出了很大的影响。", "explanation": "这里应该用〈产生〉。产生指出现某种影响；发出用于声音、光等，不能接“影响”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天把合同发出去了了。", "corrected_sentence": "我昨天把合同发出去了。", "error_description": "错误：“了”重复。“发出去了”句末已带“了”，不能再加一个“了”，写成“发出去了了”是错的。正确应为“我昨天把合同发出去了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把邀请函发出着去了。", "corrected_sentence": "我把邀请函发出去了。", "error_description": "错误：“着”表示动作持续或状态，不能插在“发出”和“去”之间。“发出去”是已完成的动作，正确应为“我把邀请函发出去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小事", "is_correct": true, "explanation": "小事指不重要的事，与“要事”（很重要、必须做的事）构成反义。"}, {"text": "书桌", "is_correct": false, "explanation": "书桌是家具，与“要事”没有反义关系。"}, {"text": "树林", "is_correct": false, "explanation": "树林是自然景物，与“要事”没有反义关系。"}, {"text": "花瓶", "is_correct": false, "explanation": "花瓶是器物，与“要事”没有反义关系。"}], "correct_answer": "小事", "explanations": {"小事": "小事指不重要的事，与“要事”（很重要、必须做的事）构成反义。", "书桌": "书桌是家具，与“要事”没有反义关系。", "树林": "树林是自然景物，与“要事”没有反义关系。", "花瓶": "花瓶是器物，与“要事”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "琐事", "is_correct": true, "explanation": "琐事指细小零碎的事，与“要事”（很重要、必须做的事）构成反义。"}, {"text": "冰箱", "is_correct": false, "explanation": "冰箱是家电，与“要事”没有反义关系。"}, {"text": "草地", "is_correct": false, "explanation": "草地是场所，与“要事”没有反义关系。"}, {"text": "钥匙", "is_correct": false, "explanation": "钥匙是随身物品，与“要事”没有反义关系。"}], "correct_answer": "琐事", "explanations": {"琐事": "琐事指细小零碎的事，与“要事”（很重要、必须做的事）构成反义。", "冰箱": "冰箱是家电，与“要事”没有反义关系。", "草地": "草地是场所，与“要事”没有反义关系。", "钥匙": "钥匙是随身物品，与“要事”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "要事是很重要、必须做的事。", "primary_collocate": null, "pronunciation": "yào shì", "ipa": "iɑʊ˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这件要事今天必须做完。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天先做要事，再做别的事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板有要事找你，请快一点。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在有要事，晚点给你打电话。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，工作是最大的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会不是小事，是一件要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，学习是你现在的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别忘了今天的要事。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了一件要事，早早起床了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把明天的要事都写好了。", "target_word": "要事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件要事", "label": "量词"}], "register": "书面", "sense_fingerprint": "要事：必须做的重要事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d475774-63da-4f28-b9ba-360faaf19fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确答案。要事 yào shì，指很重要、必须做的事。"}, {"text": "要是", "is_correct": false, "explanation": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。"}, {"text": "要使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“必须做的事”无关。"}, {"text": "又是", "is_correct": false, "explanation": "yòu 与 yào 韵母不同，意思是“又是”，与“必须做的事”无关。"}], "explanations": {"要事": "正确答案。要事 yào shì，指很重要、必须做的事。", "要是": "后一个音节 shì 读轻声，与 shì（第四声）声调不同，意思是“如果”。", "要使": "shǐ（第三声）与 shì（第四声）声调不同，意思是“使得”，与“必须做的事”无关。", "又是": "yòu 与 yào 韵母不同，意思是“又是”，与“必须做的事”无关。"}, "sentence_index": null, "correct_answer": "要事"}, "level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“这件要事今天必须做完”，要事指必须完成的重要事情。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是愿望，不是可以“做完”的事，与“今天必须”的要求冲突。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“做完”不能用于天空。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“做完”不能用于歌声。"}], "explanations": {"要事": "正确：“这件要事今天必须做完”，要事指必须完成的重要事情。", "梦想": "语义：梦想是愿望，不是可以“做完”的事，与“今天必须”的要求冲突。", "天空": "搭配：“做完”不能用于天空。", "歌声": "搭配：“做完”不能用于歌声。"}, "sentence_index": 0, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在学校闯了要事，被老师叫去了。", "explanation": "这里应该用〈大祸〉。“闯”后面接“祸”，要事指需要办理的重要事情，不能说“闯要事”。"}, {"text": "他犯了一个要事，很后悔。", "explanation": "这里应该用〈错误〉。“犯”后面接错误、罪过等，要事指需要办理的重要事情，不能说“犯要事”。"}, {"text": "要事你晚点有空，就给我打个电话吧。", "explanation": "这里应该用〈要是〉。这里表示假设，要是是连词；要事是名词，不能放在句首表示条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要事", "is_correct": true, "explanation": "正确：“学习是你现在的要事”，要事指现阶段必须做的重要事情。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食物，不能说“学习是你现在的饼干”。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是自然现象，与“学习”不能等同，句意不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：窗帘是物品，不能作为“学习”这类活动的对象。"}], "explanations": {"要事": "正确：“学习是你现在的要事”，要事指现阶段必须做的重要事情。", "饼干": "语义：饼干是食物，不能说“学习是你现在的饼干”。", "雨水": "语义：雨水是自然现象，与“学习”不能等同，句意不通。", "窗帘": "搭配：窗帘是物品，不能作为“学习”这类活动的对象。"}, "sentence_index": 6, "correct_answer": "要事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一张要事要办。", "explanation": "这里应该用〈件〉。“张”用于纸张等平面的东西，事情要用“件”。"}, {"text": "他有一把要事要办。", "explanation": "这里应该用〈件〉。“把”用于有柄的器具，事情不能用“把”来计量。"}, {"text": "他有一座要事要办。", "explanation": "这里应该用〈件〉。“座”用于山、楼等大型建筑，事情不能用“座”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本要事明天必须交完。", "corrected_sentence": "这件要事明天必须交完。", "error_description": "量词错误：“要事”是事情，应用“件”。“本”用于书籍等，不能用于事情。正确说法是“这件要事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他今天有两条要事要办。", "corrected_sentence": "他今天有两件要事要办。", "error_description": "量词错误：“要事”是事情，应用“件”。“条”用于细长的东西，不能用于事情。正确说法是“两件要事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
