INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88861, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离是从一个地方走开,或者两个地方隔开一段路。", "primary_collocate": null, "pronunciation": "lí", "ipa": "li³⁵", "syllable_count": 1, "sentences": [{"text": "他十八岁就离家去北京工作了。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校不远。", "target_word": "离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "火车下午三点离站。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人离乡几十年了。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司离地铁站很近。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她早上八点离家去上班。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里离海边只有两公里。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子第一次离家，有点儿想妈妈。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校离公园不太远。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你家离机场远不远？", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "离开某地;与某地相隔一段路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "离", "is_correct": true, "explanation": "「离」读 lí（第二声），意思是离开某地，或两地相隔一段距离。"}, {"text": "里", "is_correct": false, "explanation": "「里」（第三声）与「离」（第二声）声调不同，意思是里面。"}, {"text": "力", "is_correct": false, "explanation": "「力」（第四声）与「离」（第二声）声调不同，意思是力量。"}, {"text": "泥", "is_correct": false, "explanation": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}], "explanations": {"离": "「离」读 lí（第二声），意思是离开某地，或两地相隔一段距离。", "里": "「里」（第三声）与「离」（第二声）声调不同，意思是里面。", "力": "「力」（第四声）与「离」（第二声）声调不同，意思是力量。", "泥": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}, "sentence_index": null, "correct_answer": "离"}, "level_3": {"options": [{"text": "走", "is_correct": false, "explanation": "配价：「走」不能直接带处所宾语「家」表示离开，要说「走出家门」。"}, {"text": "离", "is_correct": true, "explanation": "「离家」指离开家，与「去北京工作」的离开语境相符。"}, {"text": "进", "is_correct": false, "explanation": "语义：「进家」是进入家里，和「去北京」的离开方向相反。"}, {"text": "出", "is_correct": false, "explanation": "语义：「出家」指当和尚或修道，与去北京工作不符。"}], "explanations": {"走": "配价：「走」不能直接带处所宾语「家」表示离开，要说「走出家门」。", "离": "「离家」指离开家，与「去北京工作」的离开语境相符。", "进": "语义：「进家」是进入家里，和「去北京」的离开方向相反。", "出": "语义：「出家」指当和尚或修道，与去北京工作不符。"}, "sentence_index": 0, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他离我说了声谢谢。", "explanation": "「离」不能表示对某人说话，应该用〈对〉，说「他对我说了声谢谢」。"}, {"text": "他离我走过来。", "explanation": "「离」表示分开或相隔，不能表示朝某人走近，应该用〈朝〉，说「他朝我走过来」。"}, {"text": "他离北京工作了。", "explanation": "「离」强调离开某地，这里是前往某地工作，应该用〈去〉，说「他去北京工作了」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88861, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "是", "is_correct": false, "explanation": "语义：「是」表示判断，「这里是海边」与「只有两公里」的距离说法不相容。"}, {"text": "离", "is_correct": true, "explanation": "「离」表示相隔一段距离，正好引出「只有两公里」。"}, {"text": "送", "is_correct": false, "explanation": "配价：「送」需要带被送的对象，不能与处所和距离搭配。"}, {"text": "分", "is_correct": false, "explanation": "搭配：「分」表示分开，不能用来说明与海边的距离。"}], "explanations": {"是": "语义：「是」表示判断，「这里是海边」与「只有两公里」的距离说法不相容。", "离": "「离」表示相隔一段距离，正好引出「只有两公里」。", "送": "配价：「送」需要带被送的对象，不能与处所和距离搭配。", "分": "搭配：「分」表示分开，不能用来说明与海边的距离。"}, "sentence_index": 6, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他离火车去北京。", "explanation": "「离」不能表示凭借交通工具，应该用〈坐〉，说「他坐火车去北京」。"}, {"text": "他离北京来。", "explanation": "「离」不能直接与「来」搭配表示来源，这里应该用〈从〉，说「他从北京来」。"}, {"text": "他离朋友借了钱。", "explanation": "「离」不能表示向某人借，这里应该用〈向〉，说「他向朋友借了钱」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下个月离走北京。", "corrected_sentence": "他下个月离开北京。", "error_description": "「离」后面的补语应是「开」，构成「离开」，「离走」不成词。正确说法是「他下个月离开北京」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家离超市离近。", "corrected_sentence": "我家离超市很近。", "error_description": "「近」前面要用程度副词「很」，动词「离」不能用来修饰形容词「近」。错误句中「很」被误写成「离」，正确说法是「我家离超市很近」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
