INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分开;距离。", "primary_collocate": null, "pronunciation": "lí", "ipa": "li³⁵", "syllable_count": 1, "sentences": [{"text": "现在离考试只有三天了。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院离这儿很远。", "target_word": "离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书店离我家只有五分钟。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城离大海很近。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们俩离得太远，不能常见面。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼离了水就活不了。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子离不了妈妈。", "target_word": "离", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "离春节还有一个星期。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新家离公司太远，每天要坐一个小时车。", "target_word": "离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在离下课还有十分钟。", "target_word": "离", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分开;相距", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "离", "is_correct": true, "explanation": "「离」读 lí（第二声），意思是分开，或与某处相距一段距离。"}, {"text": "礼", "is_correct": false, "explanation": "「礼」（第三声）与「离」（第二声）声调不同，意思是礼貌。"}, {"text": "利", "is_correct": false, "explanation": "「利」（第四声）与「离」（第二声）声调不同，意思是利益。"}, {"text": "泥", "is_correct": false, "explanation": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}], "explanations": {"离": "「离」读 lí（第二声），意思是分开，或与某处相距一段距离。", "礼": "「礼」（第三声）与「离」（第二声）声调不同，意思是礼貌。", "利": "「利」（第四声）与「离」（第二声）声调不同，意思是利益。", "泥": "「泥」（ní）与「离」（lí）声母不同，n 与 l 不同，意思是泥土。"}, "sentence_index": null, "correct_answer": "离"}, "level_3": {"options": [{"text": "缺", "is_correct": false, "explanation": "语义：「缺」表示缺少，与表示时间距离的说法不符。"}, {"text": "离", "is_correct": true, "explanation": "「离」表示相距的时间，正好和「只有三天」相配。"}, {"text": "过", "is_correct": false, "explanation": "语义：「过」表示经过，「现在过考试」说不通。"}, {"text": "差", "is_correct": false, "explanation": "搭配：「差」要说成「还差三天」或「差三天考试」，不能说「现在差考试只有三天了」。"}], "explanations": {"缺": "语义：「缺」表示缺少，与表示时间距离的说法不符。", "离": "「离」表示相距的时间，正好和「只有三天」相配。", "过": "语义：「过」表示经过，「现在过考试」说不通。", "差": "搭配：「差」要说成「还差三天」或「差三天考试」，不能说「现在差考试只有三天了」。"}, "sentence_index": 0, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他离老师说了一句话。", "explanation": "「离」不能表示对某人说话，应该用〈对〉，说「他对老师说了一句话」。"}, {"text": "他离我借了钱。", "explanation": "「离」不能表示向某人借，这里应该用〈向〉，说「他向我借了钱」。"}, {"text": "这两张桌子离在一起，很方便。", "explanation": "「离」表示分开或相隔，不表示靠在一起，应该用〈挨〉，说「两张桌子挨在一起，很方便」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舍", "is_correct": false, "explanation": "搭配：「舍」要带「得」才表示不忍，「舍不了」不成词。"}, {"text": "离", "is_correct": true, "explanation": "「离不了」表示不能分开，与「妈妈」的依赖关系相符。"}, {"text": "抛", "is_correct": false, "explanation": "语义：「抛」指扔掉，「孩子抛不了妈妈」没有意义。"}, {"text": "散", "is_correct": false, "explanation": "语义：「散」指分散，与人之间的依赖关系说不通。"}], "explanations": {"舍": "搭配：「舍」要带「得」才表示不忍，「舍不了」不成词。", "离": "「离不了」表示不能分开，与「妈妈」的依赖关系相符。", "抛": "语义：「抛」指扔掉，「孩子抛不了妈妈」没有意义。", "散": "语义：「散」指分散，与人之间的依赖关系说不通。"}, "sentence_index": 6, "correct_answer": "离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他离老师走过来。", "explanation": "「离」表示分开或相隔，不能表示朝某人走近，应该用〈朝〉，说「他朝老师走过来」。"}, {"text": "我离老师拿了一本书。", "explanation": "「离」不能表示从某人那里拿东西，这里应该用〈从〉，说「我从老师那儿拿了一本书」。"}, {"text": "这块石头离在地上。", "explanation": "「离」表示分开或相隔，不能表示物体放在某处，应该用〈在〉或〈放〉，说「这块石头放在地上」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "离开放假还有两个星期。", "corrected_sentence": "离放假还有两个星期。", "error_description": "表示相距时，「离」后面直接接时间点或事件，不能加「开」。「离开放假」中的「开」多余，「离开」指离去某处，与此处的时间距离不符。正确说法是「离放假还有两个星期」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子离没开妈妈。", "corrected_sentence": "孩子离不开妈妈。", "error_description": "「离不开」中的否定要用「不」，「离没开」是错误的否定形式。正确说法是「离不开妈妈」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
