INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外出游览的人。", "primary_collocate": null, "pronunciation": "yóu kè", "ipa": "joʊ˧˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "今天景区里有很多游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位游客在山上拍了很多照片。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们坐着船看湖边的风景。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一位游客问我去博物馆怎么走。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客买票以后才能进入公园。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，游客都躲到了店里。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游带着游客参观了老城。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇每年都吸引上百万游客。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位游客把手机忘在了车上。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客可以在门口的服务中心拿地图。", "target_word": "游客", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "外国游客", "label": "复合"}, {"form": "遊客", "label": "繁体"}], "register": "中性", "sense_fingerprint": "外出游览参观景点的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：景区里不会成批出现冰箱，与“今天景区里有很多”的情境不符。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指外出游览的人，景区里有很多，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不可数，不说“很多空气”。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：景区里不会有很多钢琴，句意不通。"}], "explanations": {"冰箱": "语义：景区里不会成批出现冰箱，与“今天景区里有很多”的情境不符。", "游客": "“游客”指外出游览的人，景区里有很多，符合句意。", "空气": "搭配：“空气”不可数，不说“很多空气”。", "钢琴": "语义：景区里不会有很多钢琴，句意不通。"}, "sentence_index": 0, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家医院的游客每天都要给病人量血压。", "explanation": "这里应该用〈护士〉。“游客”指外出游览的人，给病人量血压的应说〈护士〉。"}, {"text": "我们公司的游客每天都要打卡上班。", "explanation": "这里应该用〈员工〉。“游客”指外出游览的人，每天打卡上班的应说〈员工〉。"}, {"text": "我姐姐是这家饭店的游客，每天负责做菜。", "explanation": "这里应该用〈厨师〉。“游客”指外出游览的人，负责做菜的应说〈厨师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "货物", "is_correct": false, "explanation": "语义：导游不会带着货物去参观老城，句意不通。"}, {"text": "游客", "is_correct": true, "explanation": "“游客”指外出游览的人，导游可以带着他们参观老城。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能参观老城，与“带着……参观”的情境不符。"}, {"text": "氧气", "is_correct": false, "explanation": "搭配：“氧气”不能用“带着……参观”，搭配不当。"}], "explanations": {"货物": "语义：导游不会带着货物去参观老城，句意不通。", "游客": "“游客”指外出游览的人，导游可以带着他们参观老城。", "石头": "语义：“石头”不能参观老城，与“带着……参观”的情境不符。", "氧气": "搭配：“氧气”不能用“带着……参观”，搭配不当。"}, "sentence_index": 6, "correct_answer": "游客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我父亲是这家工厂的游客，已经干了三十年。", "explanation": "这里应该用〈工人〉。“游客”指外出游览的人，在工厂长期干活的应说〈工人〉。"}, {"text": "游客负责每天打扫服务中心。", "explanation": "这里应该用〈清洁工〉。“游客”指外出游览的人，每天负责打扫的应说〈清洁工〉，不能说“游客负责打扫”。"}, {"text": "讲解老城历史的游客很有经验。", "explanation": "这里应该用〈导游〉。“游客”是来玩的人，讲解工作的人是〈导游〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个游客们在湖边坐了很久。", "corrected_sentence": "一个游客在湖边坐了很久。", "error_description": "错误在“们”。“一个游客”已是数量短语，后面不能再加“们”，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只游客在门口问路。", "corrected_sentence": "这位游客在门口问路。", "error_description": "错误在量词。“只”一般用于动物，指人的“游客”应用“位”或“个”，应说“这位游客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上午", "is_correct": true, "explanation": "正确答案。上午与下午以正午为界，是一对反义词。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚指天黑后的时段，与下午不构成反义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "黎明指天刚亮的时候，与下午不构成反义关系。"}, {"text": "星期六", "is_correct": false, "explanation": "星期六是一周中的一天，与下午不构成反义关系。"}], "correct_answer": "上午", "explanations": {"上午": "正确答案。上午与下午以正午为界，是一对反义词。", "夜晚": "夜晚指天黑后的时段，与下午不构成反义关系。", "黎明": "黎明指天刚亮的时候，与下午不构成反义关系。", "星期六": "星期六是一周中的一天，与下午不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上午", "is_correct": true, "explanation": "正确答案。上午与下午以正午为界，是一对反义词。"}, {"text": "早晨", "is_correct": false, "explanation": "早晨指天刚亮到上午的时段，与下午是同一天的前后时段，不构成反义。"}, {"text": "半夜", "is_correct": false, "explanation": "半夜指深夜，与下午不构成反义关系。"}, {"text": "星期一", "is_correct": false, "explanation": "星期一是一周中的一天，与下午不构成反义关系。"}], "correct_answer": "上午", "explanations": {"上午": "正确答案。上午与下午以正午为界，是一对反义词。", "早晨": "早晨指天刚亮到上午的时段，与下午是同一天的前后时段，不构成反义。", "半夜": "半夜指深夜，与下午不构成反义关系。", "星期一": "星期一是一周中的一天，与下午不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "下午是中午以后到天黑以前的时间。", "primary_collocate": null, "pronunciation": "xià wǔ", "ipa": "ɕja⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "下午太阳很大，别出去了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她下午三点才吃午饭。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们下午去看电影，好不好？", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午孩子们在院子里玩。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末的下午我常常睡觉。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午的风有点儿凉。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王今天下午请假了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上午我工作，下午我休息。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他下午回来，晚上又走了。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天下午四点，老师都会给我们发作业。", "target_word": "下午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "中午后到天黑前的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。下午 xià wǔ 指中午以后到天黑以前的时间。"}, {"text": "下雨", "is_correct": false, "explanation": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。"}, {"text": "下雾", "is_correct": false, "explanation": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。"}, {"text": "夏雨", "is_correct": false, "explanation": "夏 与 下 同音；雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是夏天的雨。"}], "explanations": {"下午": "正确答案。下午 xià wǔ 指中午以后到天黑以前的时间。", "下雨": "雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是下雨。", "下雾": "雾 wù 与 午 wǔ 声调不同（第四声/第三声），意思是起雾。", "夏雨": "夏 与 下 同音；雨 yǔ 与 午 wǔ 韵母不同（ü/u），意思是夏天的雨。"}, "sentence_index": null, "correct_answer": "下午"}, "level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「下午太阳很大」中，下午表示中午以后的时段。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：深夜是夜里，太阳不会很大，句子与「太阳很大」矛盾。"}, {"text": "凌晨", "is_correct": false, "explanation": "语义：凌晨是天亮前，太阳还没出来，与「太阳很大」矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "配价：教室是地点，不能表示时间，「教室太阳很大」不通。"}], "explanations": {"下午": "正确答案。「下午太阳很大」中，下午表示中午以后的时段。", "深夜": "语义：深夜是夜里，太阳不会很大，句子与「太阳很大」矛盾。", "凌晨": "语义：凌晨是天亮前，太阳还没出来，与「太阳很大」矛盾。", "教室": "配价：教室是地点，不能表示时间，「教室太阳很大」不通。"}, "sentence_index": 0, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的下午十点，我们还在湖边散步。", "explanation": "这里应该用〈夜里〉。下午到天黑为止，晚上十点已是夜里。"}, {"text": "我下午九点去上班。", "explanation": "这里应该用〈晚上〉。下午只到天黑前，晚上九点已不属于下午。"}, {"text": "下午十一点的街道很安静。", "explanation": "这里应该用〈深夜〉。下午只到天黑前，深夜十一点的街道要说深夜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下午", "is_correct": true, "explanation": "正确答案。「小王今天下午请假了」中，下午是今天的一个时段。"}, {"text": "公司", "is_correct": false, "explanation": "配价：公司是地点，不能直接作时间状语，「小王今天公司请假了」不通。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是地点，不表示时间，句子不通。"}, {"text": "饭桌", "is_correct": false, "explanation": "语义：饭桌是家具，不表示时间，句子不通。"}], "explanations": {"下午": "正确答案。「小王今天下午请假了」中，下午是今天的一个时段。", "公司": "配价：公司是地点，不能直接作时间状语，「小王今天公司请假了」不通。", "病房": "语义：病房是地点，不表示时间，句子不通。", "饭桌": "语义：饭桌是家具，不表示时间，句子不通。"}, "sentence_index": 6, "correct_answer": "下午"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天下午十一点还在看书。", "explanation": "这里应该用〈晚上〉。下午指正午到天黑前，十一点要说晚上。"}, {"text": "我下午七点起床上学。", "explanation": "这里应该用〈晚上〉。下午到天黑为止，七点已是晚上。"}, {"text": "下午八点的街道很热闹。", "explanation": "这里应该用〈晚上〉。下午到天黑为止，八点已是晚上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只下午我们去游泳吧。", "corrected_sentence": "这个下午我们去游泳吧。", "error_description": "错误：时段名词「下午」用了量词「只」。「只」用于动物等，应说「这个下午」，量词「个」用于时段。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们下午两出发。", "corrected_sentence": "他们下午两点出发。", "error_description": "错误：时刻缺少「点」。「下午两」不能单独表示时刻，应说「下午两点」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
