INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从正午十二点到日落之前的时间。", "primary_collocate": null, "pronunciation": "xià wǔ", "ipa": "ɕja⁵¹ u²¹⁴", "syllable_count": 2, "sentences": [{"text": "我下午要去图书馆。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天下午天气很好。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天下午两点开会。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下午我们一起去公园玩吧。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天下午都在家学习。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下午的课四点结束。", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天下午我见了一个老朋友。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "星期五下午学校不上课。", "target_word": "下午", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你下午有时间吗？", "target_word": "下午", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天下午妈妈要带我去看医生。", "target_word": "下午", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "正午到日落前的时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLU