INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88911, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可选是可以自己挑的，可以要也可以不要。", "primary_collocate": null, "pronunciation": "kě xuǎn", "ipa": "kʰɤ˨˩˦ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆车的颜色是可选的，你可以自己挑。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机套是可选的，不买也可以。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买电脑时，鼠标是可选的，你可以要，也可以不要。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个套餐的饮料是可选的，不喝也行。", "target_word": "可选", "complexity_tier": "T3", "furigana": "zhè gè tào cān de yǐn liào shì kě xuǎn de, bù hē yě xíng.", "sentence_source": "generated"}, {"text": "这件衣服的扣子颜色是可选的，你喜欢哪个就选哪个。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的早餐是可选的，要不要由你决定。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个套餐里的汤是可选的，你可以不要。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买沙发时，靠垫是可选的，不要也没关系。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机的包是可选的，你想要就加钱买。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房的加湿器是可选的，不想要就告诉我们。", "target_word": "可选", "complexity_tier": "T3", "furigana": "zhè jiān fáng de jiā shī qì shì kě xuǎn de, bù xiǎng yào jiù gào sù wǒ men.", "sentence_source": "generated"}], "morphological_forms": [{"form": "可选项", "label": "复合"}, {"form": "可選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "额外的东西可以自己挑，要不要都行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "固定", "is_correct": false, "explanation": "语义：“固定”指不能更改，与“你可以自己挑”矛盾。"}, {"text": "可选", "is_correct": true, "explanation": "“可选”指可以自己挑、可要可不要，与“你可以自己挑”相符。"}, {"text": "统一", "is_correct": false, "explanation": "语义：“统一”指颜色都一样，没有挑选的余地，与句意不符。"}, {"text": "单一", "is_correct": false, "explanation": "搭配：“单一”多修饰种类、成分，说“颜色是单一的”不自然，且与“你可以自己挑”矛盾。"}], "explanations": {"固定": "语义：“固定”指不能更改，与“你可以自己挑”矛盾。", "可选": "“可选”指可以自己挑、可要可不要，与“你可以自己挑”相符。", "统一": "语义：“统一”指颜色都一样，没有挑选的余地，与句意不符。", "单一": "搭配：“单一”多修饰种类、成分，说“颜色是单一的”不自然，且与“你可以自己挑”矛盾。"}, "sentence_index": 0, "correct_answer": "可选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体育课是可选的，每个人都必须上。", "explanation": "这里应该用〈必修〉。“可选”指可以选也可以不选，人人必上的课程要用〈必修〉，此处与“每个人都必须上”矛盾。"}, {"text": "这道大题是可选的，每个考生都必须作答。", "explanation": "这里应该用〈必答〉。“可选”指可以不做，要求每个考生都作答的题目应说〈必答〉，与“都必须作答”矛盾。"}, {"text": "这次安全演练是可选的，所有员工都必须参加。", "explanation": "这里应该用〈强制性〉。“可选”指可以不做，要求所有员工参加的演练是强制性的，不能用“可选”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "必需", "is_correct": false, "explanation": "语义：“必需”指不可缺少，汤不能不要，与“你可以不要”矛盾。"}, {"text": "必备", "is_correct": false, "explanation": "语义：“必备”指必须具备，与“你可以不要”矛盾。"}, {"text": "可选", "is_correct": true, "explanation": "“可选”指可有可无，汤可以不要，与句意相符。"}, {"text": "强制", "is_correct": false, "explanation": "搭配：“强制”多用于规定、措施，不说“汤是强制的”，且与“你可以不要”矛盾。"}], "explanations": {"必需": "语义：“必需”指不可缺少，汤不能不要，与“你可以不要”矛盾。", "必备": "语义：“必备”指必须具备，与“你可以不要”矛盾。", "可选": "“可选”指可有可无，汤可以不要，与句意相符。", "强制": "搭配：“强制”多用于规定、措施，不说“汤是强制的”，且与“你可以不要”矛盾。"}, "sentence_index": 6, "correct_answer": "可选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差的行程是可选的，每天的安排都不能变。", "explanation": "这里应该用〈固定〉。“可选”指可以挑选、可有可无；行程不能变动时要用〈固定〉。"}, {"text": "这份作业题是可选的，所有学生都要交。", "explanation": "这里应该用〈必做〉。“可选”指可以不做，要求所有学生都交的作业应说〈必做〉，与“都要交”矛盾。"}, {"text": "这份报告的结论是可选的，我们必须写清楚。", "explanation": "这里应该用〈必需〉。“可选”指可以不写，结论是报告必不可少的内容，应说〈必需〉，与“必须写清楚”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款手机的壳很可选的，你可以自己挑。", "corrected_sentence": "这款手机的壳是可选的，你可以自己挑。", "error_description": "错误在“是”误用为“很”。“可选”作谓语、表示“可以选可不选”时通常用“是……的”结构，“很可选的”不自然，应说“是可选的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间房的加湿器的可选的，不想用就跟我们说。", "corrected_sentence": "这间房的加湿器是可选的，不想用就跟我们说。", "error_description": "错误在“的”。“可选”作谓语时要用“是”，应说“是可选的”；“加湿器的可选的”把“的”接在“可选”前，不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
