INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88912, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以选择的；非必须的。", "primary_collocate": null, "pronunciation": "kě xuǎn", "ipa": "kʰɤ˨˩˦ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这门课是可选的，不是每个人都要上。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业里的最后一题是可选的，不做也行。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加晚会是可选的，没有人会要求你去。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "表格里这一项是可选的，可以不写。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的口语部分是可选的，不考也没关系。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的活动是可选的，你不想去就不用去。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的游泳课是可选的，想学的同学才报名。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一步是可选的，不做也不会有问题。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填写电话号码是可选的，不想写就不写。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这本书是可选的，不一定要读。", "target_word": "可选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可选项", "label": "复合"}, {"form": "可選", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不是必须做的，可以选择做或不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6bd2660c-ae34-4344-9312-89f626c1f5f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "必修", "is_correct": false, "explanation": "语义：“必修”指必须学，与“不是每个人都要上”矛盾。"}, {"text": "可选", "is_correct": true, "explanation": "“可选”指可以选也可以不选，与“不是每个人都要上”相符。"}, {"text": "必需", "is_correct": false, "explanation": "语义：“必需”指不可缺少，与“不是每个人都要上”矛盾。"}, {"text": "普遍", "is_correct": false, "explanation": "搭配：“普遍”多修饰现象、情况，不说“课是普遍的”，且与句意相反。"}], "explanations": {"必修": "语义：“必修”指必须学，与“不是每个人都要上”矛盾。", "可选": "“可选”指可以选也可以不选，与“不是每个人都要上”相符。", "必需": "语义：“必需”指不可缺少，与“不是每个人都要上”矛盾。", "普遍": "搭配：“普遍”多修饰现象、情况，不说“课是普遍的”，且与句意相反。"}, "sentence_index": 0, "correct_answer": "可选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "身份证号是可选的，办手续时必须填写。", "explanation": "这里应该用〈必填〉。“可选”指可以不填，要求必须写时要用〈必填〉。"}, {"text": "这门考试的口语部分是可选的，老师说所有人都要考。", "explanation": "这里应该用〈必考〉。“可选”指可以不考，所有人都要考的部分应说〈必考〉，与“都要考”矛盾。"}, {"text": "这份资料是可选的，老师要求全班都要读。", "explanation": "这里应该用〈必读〉。“可选”指可以不读，老师要求全班都读的资料应说〈必读〉，与“都要读”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "统一", "is_correct": false, "explanation": "语义：“统一”指一样、无从挑选，与“想学的同学才报名”矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "语义：“固定”指不能变动，与“想学的同学才报名”相矛盾。"}, {"text": "可选", "is_correct": true, "explanation": "“可选”指可以选也可以不选，游泳课想学的人才报名，与句意相符。"}, {"text": "强制", "is_correct": false, "explanation": "搭配：“强制”多用于规定、措施，不用来形容课程，且与“想学的同学才报名”矛盾。"}], "explanations": {"统一": "语义：“统一”指一样、无从挑选，与“想学的同学才报名”矛盾。", "固定": "语义：“固定”指不能变动，与“想学的同学才报名”相矛盾。", "可选": "“可选”指可以选也可以不选，游泳课想学的人才报名，与句意相符。", "强制": "搭配：“强制”多用于规定、措施，不用来形容课程，且与“想学的同学才报名”矛盾。"}, "sentence_index": 6, "correct_answer": "可选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议的时间是可选的，全体人员必须准时到场。", "explanation": "这里应该用〈固定〉。“可选”指可以挑选、可有可无；会议时间不能改动时要用〈固定〉。"}, {"text": "这个环节是可选的，所有人都必须经过。", "explanation": "这里应该用〈必经〉。“可选”指可以不做，每个人都必须经过的环节应说〈必经〉，与“都必须经过”矛盾。"}, {"text": "这份报告的结论是可选的，我们必须写清楚。", "explanation": "这里应该用〈必需〉。“可选”指可以不写，结论是报告必不可少的内容，应说〈必需〉，与“必须写清楚”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个活动是不可选的，不参加也没关系。", "corrected_sentence": "这个活动是可选的，不参加也没关系。", "error_description": "错误在“可选”前多加了“不”，变成“不能选”，与“不参加也没关系”矛盾。应去掉“不”，说“是可选的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项内容更可选的，不写也没关系。", "corrected_sentence": "这项内容是可选的，不写也没关系。", "error_description": "错误在“更”。“可选”表示“可以选可不选”，作谓语时通常用“是……的”结构，“更可选的”不自然，应说“是可选的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09579fbd-7caa-497e-a4d2-97be732c68f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
