INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88917, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "了得是说特别厉害。", "primary_collocate": null, "pronunciation": "liǎo de", "ipa": "ljɑʊ̯˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "他的功夫真了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位厨师的手艺实在了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的记性可真了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的口才了得,谁也说不过她。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子画画的本事了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张的酒量真是了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个球员的速度了得。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他算账的本领了得,一分钱也不会错。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的人气了得,天天都有人排队。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的耐心真了得,一天都不生气。", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "作谓语,称赞本领、能力等特别厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 算账 (Zipf 3.38), 本领 (Zipf 3.8), 一分钱 (Zipf 3.69)']::text[], '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88917, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确答案：了得（liǎo de），表示特别厉害。"}, {"text": "聊得", "is_correct": false, "explanation": "声调不同：liáo（第二声）与 liǎo（第三声）声调不同，聊得是“谈得来、聊天”的意思，不是“了得”。"}, {"text": "老得", "is_correct": false, "explanation": "韵母不同：lǎo 与 liǎo 只差介音 i，老得是“变老”的意思，如“老得快”，不是“了得”。"}, {"text": "鸟的", "is_correct": false, "explanation": "声母不同：niǎo（n）与 liǎo（l）声母不同，鸟的是“属于鸟的”的意思，不是“了得”。"}], "explanations": {"了得": "正确答案：了得（liǎo de），表示特别厉害。", "聊得": "声调不同：liáo（第二声）与 liǎo（第三声）声调不同，聊得是“谈得来、聊天”的意思，不是“了得”。", "老得": "韵母不同：lǎo 与 liǎo 只差介音 i，老得是“变老”的意思，如“老得快”，不是“了得”。", "鸟的": "声母不同：niǎo（n）与 liǎo（l）声母不同，鸟的是“属于鸟的”的意思，不是“了得”。"}, "sentence_index": null, "correct_answer": "了得"}, "level_3": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确：“真了得”是称赞本领特别厉害，与“功夫”搭配。"}, {"text": "红", "is_correct": false, "explanation": "体貌：红是颜色，不能用来评价功夫的高低，“功夫真红”不成话。"}, {"text": "多", "is_correct": false, "explanation": "搭配：多说数量，不能与“功夫”搭配来表示程度，“功夫真多”不通。"}, {"text": "贵", "is_correct": false, "explanation": "语义：贵说价格高，与称赞本领的语义不合，“功夫真贵”不通。"}], "explanations": {"了得": "正确：“真了得”是称赞本领特别厉害，与“功夫”搭配。", "红": "体貌：红是颜色，不能用来评价功夫的高低，“功夫真红”不成话。", "多": "搭配：多说数量，不能与“功夫”搭配来表示程度，“功夫真多”不通。", "贵": "语义：贵说价格高，与称赞本领的语义不合，“功夫真贵”不通。"}, "sentence_index": 0, "correct_answer": "了得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子半夜还没回家，这还了得！", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问或感叹，与本题“特别厉害”的义项不同，句子不是这个用法。"}, {"text": "水管坏了没人修，那还了得？", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问，与本题“特别厉害”的义项不同，句子不是这个用法。"}, {"text": "他居然把公司的钱偷走了，这还了得！", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问或感叹，与本题称赞本领的义项不同，句子不是这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确：“速度了得”是称赞速度特别快。"}, {"text": "烫", "is_correct": false, "explanation": "语义：烫说温度高，不能形容速度的高低，“速度烫”不通。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：厚描述物体的厚薄，不能用来形容速度。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“速度硬”不成搭配，硬形容质地，不能用来评价速度。"}], "explanations": {"了得": "正确：“速度了得”是称赞速度特别快。", "烫": "语义：烫说温度高，不能形容速度的高低，“速度烫”不通。", "厚": "体貌：厚描述物体的厚薄，不能用来形容速度。", "硬": "搭配：“速度硬”不成搭配，硬形容质地，不能用来评价速度。"}, "sentence_index": 6, "correct_answer": "了得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生在课堂上打架，这还了得！", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问或感叹，与本题“特别厉害”的义项不同，句子不是这个用法。"}, {"text": "司机喝了酒还开车，这还了得？", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问，与本题“特别厉害”的义项不同，句子不是这个用法。"}, {"text": "全班都在抄作业，这还了得！", "explanation": "此处“了得”是“事情严重、不能容忍”的另一义项，多用于反问或感叹，与本题称赞能力的义项不同，句子不是这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的画功真很了得。", "corrected_sentence": "他的画功真了得。", "error_description": "“真”已表示程度，与“很”不能叠用；多加的“很”不通，正确是“他的画功真了得。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的反应速度真很了得。", "corrected_sentence": "她的反应速度真了得。", "error_description": "“真”与“很”都表示程度，不能叠用。正确是“真了得”，多加“很”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
