INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88918, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容事情很严重、不能容忍,多用于反问或否定。", "primary_collocate": null, "pronunciation": "liǎo de", "ipa": "ljɑʊ̯˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "学生在课堂上打架,这还了得!", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要是人人都不守规矩,那还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子半夜还没回家,这还了得!", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他居然敢骗老师,这还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水管坏了没人修,那还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果大家都迟到,那还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩一个人去河边玩,这还了得!", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机喝了酒还开车,这还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说他偷了钱?这还了得!", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人在公司里偷钱,这还了得?", "target_word": "了得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "多用于“这还了得”之类的反问,表示事情严重、不能容忍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc02136-5e86-444f-863a-a1c145c1bb27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确答案：了得（liǎo de），表示事情很严重、不能容忍。"}, {"text": "聊得", "is_correct": false, "explanation": "声调不同：liáo（第二声）与 liǎo（第三声）声调不同，聊得是“谈得来、聊天”的意思，不是“了得”。"}, {"text": "老得", "is_correct": false, "explanation": "韵母不同：lǎo 与 liǎo 只差介音 i，老得是“变老”的意思，如“老得快”，不是“了得”。"}, {"text": "鸟的", "is_correct": false, "explanation": "声母不同：niǎo（n）与 liǎo（l）声母不同，鸟的是“属于鸟的”的意思，不是“了得”。"}], "explanations": {"了得": "正确答案：了得（liǎo de），表示事情很严重、不能容忍。", "聊得": "声调不同：liáo（第二声）与 liǎo（第三声）声调不同，聊得是“谈得来、聊天”的意思，不是“了得”。", "老得": "韵母不同：lǎo 与 liǎo 只差介音 i，老得是“变老”的意思，如“老得快”，不是“了得”。", "鸟的": "声母不同：niǎo（n）与 liǎo（l）声母不同，鸟的是“属于鸟的”的意思，不是“了得”。"}, "sentence_index": null, "correct_answer": "了得"}, "level_3": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确：“这还了得”是反问，表示事情严重、不能容忍。"}, {"text": "严重", "is_correct": false, "explanation": "搭配：“这还严重”不成话，严重只描述事情本身，放进反问“这还……”里不通。"}, {"text": "可怕", "is_correct": false, "explanation": "语义：可怕指令人害怕，“这还可怕”把反问的“不能容忍”换成了“令人害怕”，意思不通。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：轻松表示不费力，与“学生在课堂上打架”的严重语境相反，“这还轻松”不通。"}], "explanations": {"了得": "正确：“这还了得”是反问，表示事情严重、不能容忍。", "严重": "搭配：“这还严重”不成话，严重只描述事情本身，放进反问“这还……”里不通。", "可怕": "语义：可怕指令人害怕，“这还可怕”把反问的“不能容忍”换成了“令人害怕”，意思不通。", "轻松": "语义：轻松表示不费力，与“学生在课堂上打架”的严重语境相反，“这还轻松”不通。"}, "sentence_index": 0, "correct_answer": "了得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子画画的本事了得。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是绘画本事，与本题“事情严重、多用于反问”的义项不同，句子不是这个用法。"}, {"text": "他的功夫真了得。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是能力，与本题“事情严重、多用于反问”的义项不同。"}, {"text": "他算账的本领了得，一分钱也不会错。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是算账本领，与本题“事情严重、多用于反问”的义项不同，句子不是这个用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了得", "is_correct": true, "explanation": "正确：“这还了得”表示事情严重、不能容忍，用于感叹。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：整齐形容排列规整，与“这还……”的反问不搭，“这还整齐”不成话。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：高兴指心情好，与“一个人去河边玩”的危险情境不合，“这还高兴”不通。"}, {"text": "亮", "is_correct": false, "explanation": "语义：亮指光线强或明亮，无法表示事情严重，“这还亮”意思不通。"}], "explanations": {"了得": "正确：“这还了得”表示事情严重、不能容忍，用于感叹。", "整齐": "搭配：整齐形容排列规整，与“这还……”的反问不搭，“这还整齐”不成话。", "高兴": "语义：高兴指心情好，与“一个人去河边玩”的危险情境不合，“这还高兴”不通。", "亮": "语义：亮指光线强或明亮，无法表示事情严重，“这还亮”意思不通。"}, "sentence_index": 6, "correct_answer": "了得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的口才了得，谁也说不过她。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是口才，与本题“事情严重、多用于反问”的义项不同，句子不是这个用法。"}, {"text": "那个球员的速度了得。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是速度，与本题“事情严重、多用于反问”的义项不同，句子不是这个用法。"}, {"text": "他的口语了得，三年就能跟外国人聊天。", "explanation": "此处“了得”是“本领特别厉害”的另一义项，句子称赞的是口语能力，与本题“事情严重、多用于反问”的义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "要是大家都乱扔垃圾，那还很了得？", "corrected_sentence": "要是大家都乱扔垃圾，那还了得？", "error_description": "“还了得”是固定的反问格式，中间不能插入程度副词“很”；多出的“很”不通，删去即为“那还了得？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有人在考场上作弊，还这了得！", "corrected_sentence": "有人在考场上作弊，这还了得！", "error_description": "“这”与“还”的语序颠倒。正确是“这还了得”，“还”在“这”之后；写成“还这了得”不成话。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5082b760-e43d-4b80-9727-9a2f2261a9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
