INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88927, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "传是把东西或话，从一个人手里送到另一个人。", "primary_collocate": null, "pronunciation": "chuán", "ipa": "ʈʂʰwan˧˥", "syllable_count": 1, "sentences": [{"text": "请把盐传给我。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把球传给了小李。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，请把作业往后传。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸请你传给后面的同学。", "target_word": "传", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把花一个一个往下传。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一个苹果传给了弟弟。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手机传给了坐在旁边的人。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想看，就把照片传一传吧。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把这本书传给他看看。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个盒子传到前面去。", "target_word": "传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传了", "label": "体标（了）"}, {"form": "传过", "label": "体标（过）"}, {"form": "传一传", "label": "重叠"}, {"form": "傳", "label": "繁体"}], "register": "通用", "sense_fingerprint": "传：把东西或话交给下一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d43d41e-913a-4915-873f-c2b33d22f696') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88927, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传", "is_correct": true, "explanation": "传：chuán（第二声），把东西交给别人，即本义的读音。"}, {"text": "穿", "is_correct": false, "explanation": "穿（chuān，第一声）与传（chuán，第二声）声调不同，意思是穿（衣服）。"}, {"text": "串", "is_correct": false, "explanation": "串（chuàn，第四声）与传（chuán，第二声）声调不同，意思是成串的东西。"}, {"text": "喘", "is_correct": false, "explanation": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。"}, {"text": "床", "is_correct": false, "explanation": "床（chuáng）与传（chuán）韵母不同（ang 与 an），声调相同，意思是床。"}], "explanations": {"传": "传：chuán（第二声），把东西交给别人，即本义的读音。", "穿": "穿（chuān，第一声）与传（chuán，第二声）声调不同，意思是穿（衣服）。", "串": "串（chuàn，第四声）与传（chuán，第二声）声调不同，意思是成串的东西。", "喘": "喘（chuǎn，第三声）与传（chuán，第二声）声调不同，意思是呼吸急促。", "床": "床（chuáng）与传（chuán）韵母不同（ang 与 an），声调相同，意思是床。"}, "sentence_index": null, "correct_answer": "传"}, "level_3": {"options": [{"text": "传", "is_correct": true, "explanation": "传：把东西交给别人，与“请把盐……给我”搭配。"}, {"text": "洒", "is_correct": false, "explanation": "语义：“洒”指液体或细小颗粒散落，不能把盐洒给别人。"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”是夺取，不能表示把盐递给别人。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”指猛力扔下，不能说把盐摔给别人。"}], "explanations": {"传": "传：把东西交给别人，与“请把盐……给我”搭配。", "洒": "语义：“洒”指液体或细小颗粒散落，不能把盐洒给别人。", "抢": "语义：“抢”是夺取，不能表示把盐递给别人。", "摔": "搭配：“摔”指猛力扔下，不能说把盐摔给别人。"}, "sentence_index": 0, "correct_answer": "传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙传在桌子上。", "explanation": "这里应该用〈放〉。“传”是把东西交给人，不能表示把东西放在某处。"}, {"text": "他把信传到了北京。", "explanation": "这里应该用〈寄〉。“传”是人与人之间一手交给另一手，不能表示通过邮局把信寄到外地。"}, {"text": "他把病人传到了医院。", "explanation": "这里应该用〈送〉。“传”用于东西在人手之间交递，不能表示把人运送到某地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88927, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "传", "is_correct": true, "explanation": "传：chuán（第二声），把东西交给别人，即本义的读音。"}, {"text": "川", "is_correct": false, "explanation": "川（chuān，第一声）与传（chuán，第二声）声调不同，意思是河流。"}, {"text": "窗", "is_correct": false, "explanation": "窗（chuāng，第一声）与传韵母不同（ang 与 an），声调也不同，意思是窗户。"}, {"text": "转", "is_correct": false, "explanation": "转（zhuǎn，第三声）与传声母不同（zh 与 ch），声调也不同，意思是转动。"}, {"text": "创", "is_correct": false, "explanation": "创（chuàng，第四声）与传韵母不同（ang 与 an），声调也不同，意思是创造。"}], "explanations": {"传": "传：chuán（第二声），把东西交给别人，即本义的读音。", "川": "川（chuān，第一声）与传（chuán，第二声）声调不同，意思是河流。", "窗": "窗（chuāng，第一声）与传韵母不同（ang 与 an），声调也不同，意思是窗户。", "转": "转（zhuǎn，第三声）与传声母不同（zh 与 ch），声调也不同，意思是转动。", "创": "创（chuàng，第四声）与传韵母不同（ang 与 an），声调也不同，意思是创造。"}, "sentence_index": null, "correct_answer": "传"}, "level_3": {"options": [{"text": "传", "is_correct": true, "explanation": "传：把东西交给别人，与“把手机……给了”搭配。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是用力打击使物体破碎，与把手机交给人的意思不合。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指扯裂，不能用来表示把手机递给别人。"}, {"text": "藏", "is_correct": false, "explanation": "语义：“藏”是隐藏，与把东西交给别人的意思相反。"}], "explanations": {"传": "传：把东西交给别人，与“把手机……给了”搭配。", "砸": "语义：“砸”是用力打击使物体破碎，与把手机交给人的意思不合。", "撕": "语义：“撕”指扯裂，不能用来表示把手机递给别人。", "藏": "语义：“藏”是隐藏，与把东西交给别人的意思相反。"}, "sentence_index": 6, "correct_answer": "传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在黑板上传了一个字。", "explanation": "这里应该用〈写〉。“传”是交递东西，不能表示书写。"}, {"text": "妈妈把衣服传干净了。", "explanation": "这里应该用〈洗〉。“传”不表示清洗，“传干净”不成立。"}, {"text": "他把门传上了。", "explanation": "这里应该用〈锁〉。“传”没有关闭或锁住的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "麻烦你把筷子传我。", "corrected_sentence": "麻烦你把筷子传给我。", "error_description": "“传”后缺少“给”，应说“传给我”。“传给”表示把东西交到人手里，接受者要用“给”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把这个盒子传后面去。", "corrected_sentence": "请把这个盒子传到后面去。", "error_description": "“传”后缺少“到”，应说“传到后面去”。移动的终点要用“到”引出，“传后面去”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f73dc04b-ded6-45d9-ba7c-004d3eeef747') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
