INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88932, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身上长有羽毛、一般会飞的动物。", "primary_collocate": null, "pronunciation": "niǎo", "ipa": "niau˨˩˦", "syllable_count": 1, "sentences": [{"text": "清晨，一只鸟站在屋顶上叫。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鸟一般生活在水边。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢拍鸟，每个周末都去山里。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，有些鸟飞到南方过冬。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的嘴很尖，可以吃小虫。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟睡在树枝上，一动也不动。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家养了一只会说话的鸟。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，鸟都回到树上休息。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子抬头看着天上的鸟。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的鸟飞得很高，有的鸟飞得很低。", "target_word": "鸟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "小鸟", "label": "复合"}, {"form": "鸟儿", "label": "复合"}, {"form": "鳥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长羽毛、一般会飞的动物（泛指鸟类）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc56002-944b-43b7-8635-5d8d261e4bd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88932, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟 niǎo（第三声）指身上长有羽毛、一般会飞的动物。"}, {"text": "角", "is_correct": false, "explanation": "jiǎo 与 niǎo 声母不同（j/n），意思是角、角落。"}, {"text": "脚", "is_correct": false, "explanation": "jiǎo 与 niǎo 声母不同（j/n），意思是脚。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 没有 i 音，与 niǎo 不同，意思是大脑。"}], "explanations": {"鸟": "鸟 niǎo（第三声）指身上长有羽毛、一般会飞的动物。", "角": "jiǎo 与 niǎo 声母不同（j/n），意思是角、角落。", "脚": "jiǎo 与 niǎo 声母不同（j/n），意思是脚。", "脑": "nǎo 没有 i 音，与 niǎo 不同，意思是大脑。"}, "sentence_index": null, "correct_answer": "鸟"}, "level_3": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟一般会飞，“一只鸟站在屋顶上叫”符合语境。"}, {"text": "猪", "is_correct": false, "explanation": "语义：猪不会站在屋顶上叫，与“站在屋顶上”不合。"}, {"text": "羊", "is_correct": false, "explanation": "体貌：羊的体型无法站上屋顶，与“站在屋顶上”不合。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不会站在屋顶上叫，与语境不合。"}], "explanations": {"鸟": "鸟一般会飞，“一只鸟站在屋顶上叫”符合语境。", "猪": "语义：猪不会站在屋顶上叫，与“站在屋顶上”不合。", "羊": "体貌：羊的体型无法站上屋顶，与“站在屋顶上”不合。", "鱼": "语义：鱼不会站在屋顶上叫，与语境不合。"}, "sentence_index": 0, "correct_answer": "鸟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一张鸟。", "explanation": "这里应该用〈只〉。“张”用于平面的东西，鸟要用“只”。"}, {"text": "这只鸟每天清晨喔喔叫个不停。", "explanation": "这里应该用〈公鸡〉。“喔喔”是公鸡的叫声，鸟叫要说“叫”或“唱”，不能这样说。"}, {"text": "这只鸟见到陌生人就汪汪叫。", "explanation": "这里应该用〈狗〉。“汪汪”是狗的叫声，鸟叫要说“叫”或“唱”，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88932, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟 niǎo（第三声）指身上长有羽毛、一般会飞的动物。"}, {"text": "小", "is_correct": false, "explanation": "xiǎo 与 niǎo 声母不同（x/n），意思是小的。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo 与 niǎo 声母不同（q/n），意思是灵巧。"}, {"text": "表", "is_correct": false, "explanation": "biǎo 与 niǎo 声母不同（b/n），意思是手表。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo 与 niǎo 声母不同（m/n），意思是秒。"}], "explanations": {"鸟": "鸟 niǎo（第三声）指身上长有羽毛、一般会飞的动物。", "小": "xiǎo 与 niǎo 声母不同（x/n），意思是小的。", "巧": "qiǎo 与 niǎo 声母不同（q/n），意思是灵巧。", "表": "biǎo 与 niǎo 声母不同（b/n），意思是手表。", "秒": "miǎo 与 niǎo 声母不同（m/n），意思是秒。"}, "sentence_index": null, "correct_answer": "鸟"}, "level_3": {"options": [{"text": "鸟", "is_correct": true, "explanation": "鸟会说话，“我家养了一只会说话的鸟”符合语境。"}, {"text": "碗", "is_correct": false, "explanation": "语义：碗不会说话，与“会说话的”不合。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋没有说话的能力，与“会说话的”不合。"}, {"text": "手套", "is_correct": false, "explanation": "体貌：手套没有嘴巴等器官，不能说话。"}], "explanations": {"鸟": "鸟会说话，“我家养了一只会说话的鸟”符合语境。", "碗": "语义：碗不会说话，与“会说话的”不合。", "鞋": "语义：鞋没有说话的能力，与“会说话的”不合。", "手套": "体貌：手套没有嘴巴等器官，不能说话。"}, "sentence_index": 6, "correct_answer": "鸟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鸟在厨房做饭。", "explanation": "这里应该用〈厨师〉。做饭的是人，鸟不能在厨房做饭。"}, {"text": "鸟在河里航行。", "explanation": "这里应该用〈船〉。航行的是船，鸟不能在河里航行。"}, {"text": "鸟能上网。", "explanation": "这里应该用〈电脑〉。上网是电脑或手机的功能，鸟不能上网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋顶上的那条鸟飞走了。", "corrected_sentence": "屋顶上的那只鸟飞走了。", "error_description": "“鸟”的量词应用“只”，不能用“条”。错误在“那条”，应为“那只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鸟屋檐下做窝。", "corrected_sentence": "鸟在屋檐下做窝。", "error_description": "地点状语前缺少介词“在”，应说“在屋檐下做窝”，不能说“屋檐下做窝”。错误在“在”的缺失。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b9496b7-2f92-48cc-a528-bf8074e8a4fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
