INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全家住着三个代人。", "corrected_sentence": "全家住着三代人。", "error_description": "错误：“三个代人”；正确：“三代人”。计数“代”时，数字后直接接“代”，不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要为一下代着想。", "corrected_sentence": "我们要为下一代着想。", "error_description": "错误：“一下代”；正确：“下一代”。“下一”是固定组合，指后面的一辈，不能颠倒成“一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
