INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "停是不再动了，停在那里。", "primary_collocate": null, "pronunciation": "tíng", "ipa": "tʰiŋ˧˥", "syllable_count": 1, "sentences": [{"text": "那辆白色的车停在楼下。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟停在树枝上唱歌。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船停在河边，没有动。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拖拉机停在田边的树下。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把自行车停在这里。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货车停在仓库门口，一直没走。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车停了一晚上。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共汽车停在路边，人们下了车。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶停在花上，一动也不动。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯停在五楼，门没有开。", "target_word": "停", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停了", "label": "体标"}, {"form": "停着", "label": "体标"}, {"form": "停过", "label": "体标"}, {"form": "停止", "label": "复合"}, {"form": "停车", "label": "复合"}], "register": "中性", "sense_fingerprint": "停：不再动，停放在某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d475774-63da-4f28-b9ba-360faaf19fef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指不再动，停放在某处。"}, {"text": "听", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。"}, {"text": "挺", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 tíng 韵母不同（o/i），意思是相同。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 tíng 韵母不同（e/i），意思是疼痛。"}, {"text": "零", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是数字零。"}], "explanations": {"停": "正确答案：停（tíng）指不再动，停放在某处。", "听": "tīng（第一声）与 tíng（第二声）声调不同，意思是用耳朵接收声音。", "挺": "tǐng（第三声）与 tíng（第二声）声调不同，意思是笔直或很。", "同": "tóng 与 tíng 韵母不同（o/i），意思是相同。", "疼": "téng 与 tíng 韵母不同（e/i），意思是疼痛。", "零": "líng 与 tíng 声母不同（l/t），意思是数字零。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：车不再移动，停放在楼下，与语境相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，车不能飞。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”用于人或动物，不能说车坐在楼下。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与车停放的情境无关。"}], "explanations": {"停": "停：车不再移动，停放在楼下，与语境相符。", "飞": "语义：“飞”指在空中移动，车不能飞。", "坐": "搭配：“坐”用于人或动物，不能说车坐在楼下。", "唱": "语义：“唱”指发出歌声，与车停放的情境无关。"}, "sentence_index": 0, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那幅画停在墙上。", "explanation": "这里应该用〈挂〉。停指车、船、鸟等停留在某处，画要挂在墙上。"}, {"text": "书停在桌子上。", "explanation": "这里应该用〈放〉。停只用于车、船、鸟等停留，书要说放在桌子上。"}, {"text": "商品停在货架上。", "explanation": "这里应该用〈摆〉。停不用于商品的陈列，商品要说摆在货架上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88959, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "停", "is_correct": true, "explanation": "正确答案：停（tíng）指不再动，停放在某处。"}, {"text": "厅", "is_correct": false, "explanation": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。"}, {"text": "艇", "is_correct": false, "explanation": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。"}, {"text": "灵", "is_correct": false, "explanation": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是糖果。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}], "explanations": {"停": "正确答案：停（tíng）指不再动，停放在某处。", "厅": "tīng（第一声）与 tíng（第二声）声调不同，意思是大厅。", "艇": "tǐng（第三声）与 tíng（第二声）声调不同，意思是小船。", "灵": "líng 与 tíng 声母不同（l/t），意思是灵巧或灵魂。", "糖": "táng 与 tíng 韵母不同（a/i），意思是糖果。", "堂": "táng 与 tíng 韵母不同（a/i），意思是厅堂。"}, "sentence_index": null, "correct_answer": "停"}, "level_3": {"options": [{"text": "停", "is_correct": true, "explanation": "停：车停放了一晚上，与语境相符。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”指人居住或留宿，车不能说住一晚上。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与车无关。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔记录文字，车不能写。"}], "explanations": {"停": "停：车停放了一晚上，与语境相符。", "住": "搭配：“住”指人居住或留宿，车不能说住一晚上。", "吃": "语义：“吃”指把食物咽下，与车无关。", "写": "语义：“写”指用笔记录文字，车不能写。"}, "sentence_index": 6, "correct_answer": "停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把垃圾停在门口。", "explanation": "这里应该用〈扔〉。停只用于车、船、鸟等停留，垃圾要说扔掉或放在门口。"}, {"text": "这棵树停在河边。", "explanation": "这里应该用〈长〉。停指车、船或鸟等移动后停留，树是固定的植物，应说长在河边。"}, {"text": "行李停在车站门口。", "explanation": "这里应该用〈堆〉。停指车、船或鸟等停留，行李要说堆放在车站门口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1265da35-edd4-42f1-ac4f-48b280bb1715') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used