INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家元首和国家权力机关由选举产生的国家。", "primary_collocate": null, "pronunciation": "gòng hé guó", "ipa": "kʊŋ˥˩ xɤ˧˥ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "共和国的国家元首由选举产生。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个年轻的共和国。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个共和国去年举行了选举。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共和国的人民选出自己的总统。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家成为共和国已经很多年了。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一个共和国长大。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共和国的总统换人了。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法国是一个共和国。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个共和国有自己的法律。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "共和国的权力机关也由选举产生。", "target_word": "共和国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共和國", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "元首和权力机关由选举产生的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b561781c-ab85-4690-8dcd-c94501bb469d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学校", "is_correct": false, "explanation": "语义：学校不是国家，没有国家元首，“国家元首”只能指国家的最高代表。"}, {"text": "共和国", "is_correct": true, "explanation": "正确：共和国的国家元首由选举产生，符合这个义项。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司没有国家元首，“国家元首”只能指国家的最高代表。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“国家元首”只能和国家搭配，城市不能有国家元首。"}], "explanations": {"学校": "语义：学校不是国家，没有国家元首，“国家元首”只能指国家的最高代表。", "共和国": "正确：共和国的国家元首由选举产生，符合这个义项。", "公司": "语义：公司没有国家元首，“国家元首”只能指国家的最高代表。", "城市": "搭配：“国家元首”只能和国家搭配，城市不能有国家元首。"}, "sentence_index": 0, "correct_answer": "共和国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "共和国的皇帝是世袭的。", "explanation": "这里应该用〈帝国〉。共和国的元首由选举产生，皇帝世袭的国家要说帝国。"}, {"text": "美国实行共和国，各州有很大的权力。", "explanation": "这里应该用〈联邦制〉。“实行”后面接制度，共和国是国家，不能说“实行共和国”。"}, {"text": "这座共和国的总统很年轻。", "explanation": "这里应该用〈个〉。共和国是国家，不用“座”，“座”多用于山、桥、建筑等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "搭配：医院的负责人是院长，不说“总统”，“总统”只用于国家。"}, {"text": "共和国", "is_correct": true, "explanation": "正确：共和国的总统可以换人，符合这个义项。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：工厂的负责人是厂长，不能用“总统”来指代。"}, {"text": "球队", "is_correct": false, "explanation": "语义：球队没有总统，球队的负责人是队长或教练，与句子不符。"}], "explanations": {"医院": "搭配：医院的负责人是院长，不说“总统”，“总统”只用于国家。", "共和国": "正确：共和国的总统可以换人，符合这个义项。", "工厂": "搭配：工厂的负责人是厂长，不能用“总统”来指代。", "球队": "语义：球队没有总统，球队的负责人是队长或教练，与句子不符。"}, "sentence_index": 6, "correct_answer": "共和国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "共和国的权力掌握在国王手中。", "explanation": "这里应该用〈君主国〉。共和国的权力机关由选举产生，国王掌权的国家要说君主国。"}, {"text": "这个共和国的董事长由股东选举产生。", "explanation": "这里应该用〈公司〉。共和国指国家，不能指公司；由股东选举产生董事长的是公司。"}, {"text": "这个国家的制度是共和国。", "explanation": "这里应该用〈民主制〉。“制度”指政治体制，共和国是国家，不能说“制度是共和国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法国是一本共和国，国家元首由选举产生。", "corrected_sentence": "法国是一个共和国，国家元首由选举产生。", "error_description": "错误在量词：“共和国”是国家，应用量词“个”，“本”只用于书等物品。正确形式为“一个共和国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所共和国的总统每四年选一次。", "corrected_sentence": "这个共和国的总统每四年选一次。", "error_description": "错误在量词：“所”用于学校、医院、房屋等机构或建筑，“共和国”是国家，应用量词“个”。正确形式为“这个共和国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
