INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以米为长度基本单位、千克为质量基本单位的度量衡制度。", "primary_collocate": null, "pronunciation": "mǐ zhì", "ipa": "mi˨˩˦ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "米制是一种以米和千克为基础的度量衡制度。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制最早是在法国开始使用的。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多国家都实行米制。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制的长度单位是米。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制的质量单位是千克。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家都用米制做实验。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制让各国的计量更容易统一。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲了米制的历史。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制比英制更容易换算。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米制在世界上用得很广。", "target_word": "米制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "米制单位", "label": "复合"}], "register": "中性", "sense_fingerprint": "以米和千克为基本单位的度量衡制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：以米和千克为基本单位的度量衡制度。"}, {"text": "米市", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。"}, {"text": "蜜制", "is_correct": false, "explanation": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。"}, {"text": "米纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。"}, {"text": "理智", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}], "explanations": {"米制": "米制：以米和千克为基本单位的度量衡制度。", "米市": "zhì 与 shì 声母不同（zh 与 sh），意思是米市，指卖米的市场。", "蜜制": "mì（第四声）与 mǐ（第三声）声调不同，意思是用蜂蜜浸渍或腌制。", "米纸": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是用米做成的纸。", "理智": "lǐ 与 mǐ 声母不同（l 与 m），意思是冷静而有判断力。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“米制是一种以米和千克为基础的度量衡制度”。"}, {"text": "英制", "is_correct": false, "explanation": "语义：“英制”以英尺、磅为基础，与“以米和千克为基础”相反。"}, {"text": "市制", "is_correct": false, "explanation": "语义：“市制”以尺、斤为基础，与句中“以米和千克为基础”矛盾。"}, {"text": "英里", "is_correct": false, "explanation": "搭配：“英里”是一个长度单位，不是度量衡制度，不能作主语。"}], "explanations": {"米制": "正确：“米制是一种以米和千克为基础的度量衡制度”。", "英制": "语义：“英制”以英尺、磅为基础，与“以米和千克为基础”相反。", "市制": "语义：“市制”以尺、斤为基础，与句中“以米和千克为基础”矛盾。", "英里": "搭配：“英里”是一个长度单位，不是度量衡制度，不能作主语。"}, "sentence_index": 0, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用米制做了一张木桌。", "explanation": "“米制”是度量衡制度，不是材料，不能用来做桌子。"}, {"text": "奶奶每天用米制熬粥。", "explanation": "这里的“米制”不是度量衡制度，是“大米”的意思，熬粥说的“米”不能用“米制”。"}, {"text": "我们班买了一包米制，放在讲台上。", "explanation": "这里的“米制”不是度量衡制度，是大米的意思；装在包里的大米要说〈大米〉，“米制”不能指大米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "米制", "is_correct": true, "explanation": "米制：以米和千克为基本单位的度量衡制度。"}, {"text": "美制", "is_correct": false, "explanation": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。"}, {"text": "体制", "is_correct": false, "explanation": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。"}, {"text": "礼制", "is_correct": false, "explanation": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}], "explanations": {"米制": "米制：以米和千克为基本单位的度量衡制度。", "美制": "měi（第三声）与 mǐ（第三声）韵母不同（ei 与 i），意思是美国制造。", "体制": "tǐ 与 mǐ 声母不同（t 与 m），意思是组织或制度的结构。", "礼制": "lǐ 与 mǐ 声母不同（l 与 m），意思是古代的礼仪制度。"}, "sentence_index": null, "correct_answer": "米制"}, "level_3": {"options": [{"text": "米制", "is_correct": true, "explanation": "正确：“米制让各国的计量更容易统一”，主语是度量衡制度。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是度量制度，不能让计量统一。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，与计量统一无关。"}, {"text": "英寸", "is_correct": false, "explanation": "搭配：“英寸”是长度单位，不是能让计量统一的制度。"}], "explanations": {"米制": "正确：“米制让各国的计量更容易统一”，主语是度量衡制度。", "天气": "语义：“天气”不是度量制度，不能让计量统一。", "桌子": "语义：“桌子”是家具，与计量统一无关。", "英寸": "搭配：“英寸”是长度单位，不是能让计量统一的制度。"}, "sentence_index": 6, "correct_answer": "米制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "米制是质量的基本单位。", "explanation": "这里应该用〈千克〉。“米制”是整个度量衡制度，不是单个质量单位。"}, {"text": "我们用米制这个单位称鸡蛋。", "explanation": "这里应该用〈克〉作单位。“米制”不能当作单个单位使用。"}, {"text": "我们用米制这个单位量布料。", "explanation": "这里应该用〈米〉作单位。“米制”是度量办法，不是长度单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "许多国家都在用一把米制。", "corrected_sentence": "许多国家都在用米制。", "error_description": "量词错误：“米制”是度量衡制度，不能用“把”（“把”用于有柄的器具），应直接说“用米制”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一把米制，大家都在用。", "corrected_sentence": "这是一种米制，大家都在用。", "error_description": "量词错误：“米制”是度量衡制度，不能用“把”，应说“一种米制”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": true, "explanation": "出发指离开起点，与“到达”互为反义。"}, {"text": "停留", "is_correct": false, "explanation": "停留指在某处暂时待着，与“到达”的“走到”没有对立关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停下来放松，与“到达”不构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "等待指在原地期待某事，与“到达”不是反义关系。"}], "correct_answer": "出发", "explanations": {"出发": "出发指离开起点，与“到达”互为反义。", "停留": "停留指在某处暂时待着，与“到达”的“走到”没有对立关系。", "休息": "休息指停下来放松，与“到达”不构成反义关系。", "等待": "等待指在原地期待某事，与“到达”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出发", "is_correct": true, "explanation": "出发指离开起点，与“到达”互为反义。"}, {"text": "停靠", "is_correct": false, "explanation": "停靠指车船暂时停在某处，与“到达”不是反义关系。"}, {"text": "逗留", "is_correct": false, "explanation": "逗留指在某地多待一会儿，与“到达”没有对立关系。"}, {"text": "守候", "is_correct": false, "explanation": "守候指在原地等待，与“到达”不构成反义。"}], "correct_answer": "出发", "explanations": {"出发": "出发指离开起点，与“到达”互为反义。", "停靠": "停靠指车船暂时停在某处，与“到达”不是反义关系。", "逗留": "逗留指在某地多待一会儿，与“到达”没有对立关系。", "守候": "守候指在原地等待，与“到达”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到达是走到了要去的地方。", "primary_collocate": null, "pronunciation": "dào dá", "ipa": "taʊ̯˥˩ ta˧˥", "syllable_count": 2, "sentences": [{"text": "我们坐了两个小时的车，终于到达了山脚下。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车几点到达北京？", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一个到达了终点。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机已经到达上海了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你到达学校后给我打电话。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了一个下午，才到达那个小村子。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她到达的时候，会议已经开始了。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到达车站了吗？", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到达山顶以后，我们坐下来休息。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有到达过那么远的地方。", "target_word": "到达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到达了", "label": "完成体"}, {"form": "到达过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "走到要去的地方，如山顶、终点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达某个地点，与“坐了两个小时的车”和“山脚下”的句意相符。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”要说“从…出发”或“向…出发”，不能直接带“山脚下”作宾语。"}, {"text": "骑", "is_correct": false, "explanation": "语义：前文说“坐了车”，“骑”与之矛盾，而且“骑”的宾语应是马或车，不是地点。"}, {"text": "登上", "is_correct": false, "explanation": "搭配：“登上”指爬到高处，与位置低的“山脚下”不搭配。"}], "explanations": {"到达": "到达表示抵达某个地点，与“坐了两个小时的车”和“山脚下”的句意相符。", "出发": "配价：“出发”要说“从…出发”或“向…出发”，不能直接带“山脚下”作宾语。", "骑": "语义：前文说“坐了车”，“骑”与之矛盾，而且“骑”的宾语应是马或车，不是地点。", "登上": "搭配：“登上”指爬到高处，与位置低的“山脚下”不搭配。"}, "sentence_index": 0, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我的成绩到达了九十分。", "explanation": "这里应该用〈达到〉。到达指走到某个地点，成绩、分数等数量要用达到。"}, {"text": "两家公司终于到达了合作协议。", "explanation": "这里应该用〈达成〉。到达指走到某处，协议要用达成。"}, {"text": "她努力工作，终于到达了自己的梦想。", "explanation": "这里应该用〈实现〉。到达指走到某个地点，梦想要用实现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到达", "is_correct": true, "explanation": "到达表示抵达，符合“她……的时候，会议已经开始了”的时间关系。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：“结束”多以事情、活动作主语，不说“她结束”，句子不通。"}, {"text": "散会", "is_correct": false, "explanation": "配价：“散会”的主语应是会议，不能以“她”作主语。"}, {"text": "闭幕", "is_correct": false, "explanation": "语义：“闭幕”指活动终了，与“会议已经开始了”的状态不符，而且不能以人作主语。"}], "explanations": {"到达": "到达表示抵达，符合“她……的时候，会议已经开始了”的时间关系。", "结束": "搭配：“结束”多以事情、活动作主语，不说“她结束”，句子不通。", "散会": "配价：“散会”的主语应是会议，不能以“她”作主语。", "闭幕": "语义：“闭幕”指活动终了，与“会议已经开始了”的状态不符，而且不能以人作主语。"}, "sentence_index": 6, "correct_answer": "到达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上到达了老朋友。", "explanation": "这里应该用〈遇到〉。到达指走到某个地点，遇见人要用遇到。"}, {"text": "我终于到达了老师。", "explanation": "这里应该用〈见到〉。到达指走到某处，见人要用见到。"}, {"text": "他终于到达了任务。", "explanation": "这里应该用〈完成〉。到达指走到某地，任务要用完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天下午到达了机场。", "corrected_sentence": "我们明天下午到达机场。", "error_description": "错误在“到达”后面的“了”。“明天下午”是将来的时间，动作还没有发生，不能用“到达了”，应去掉“了”，说“我们明天下午到达机场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车八点在到达车站。", "corrected_sentence": "火车八点到达车站。", "error_description": "错误在“到达”前面的“在”。“到达”是瞬时动词，不能用“在”表示进行，应去掉“在”，说“火车八点到达车站”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
