INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88989, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同事是在同一个地方一起上班的人。", "primary_collocate": null, "pronunciation": "tóng shì", "ipa": "tʰʊŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他和同事在一个办公室。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，同事请我吃饭。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位是我的同事，他在财务部工作。", "target_word": "同事", "complexity_tier": "T3", "furigana": "zhè wèi shì wǒ de tóng shì, tā zài cái wù bù gōng zuò.", "sentence_source": "generated"}, {"text": "我的同事住在公司旁边。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们给他开了生日会。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的同事会说三种语言。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太了解新同事。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常和同事聊天。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天同事给我打电话了。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟同事去过那家饭馆。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老同事", "label": "复合"}, {"form": "新同事", "label": "复合"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "一起上班的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb1a83c7-686e-430e-8a43-46799c4d78f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同事", "is_correct": true, "explanation": "同事：在同一个地方一起上班的人。"}, {"text": "同时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，“同时”意思是同一时候，与“同事”不是同一个词。"}, {"text": "从事", "is_correct": false, "explanation": "cóng（第二声）与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。"}, {"text": "重视", "is_correct": false, "explanation": "chóng 与 tóng 声母不同（ch 与 t），“重视”意思是看重、认为重要。"}], "explanations": {"同事": "同事：在同一个地方一起上班的人。", "同时": "shí（第二声）与 shì（第四声）声调不同，“同时”意思是同一时候，与“同事”不是同一个词。", "从事": "cóng（第二声）与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。", "重视": "chóng 与 tóng 声母不同（ch 与 t），“重视”意思是看重、认为重要。"}, "sentence_index": null, "correct_answer": "同事"}, "level_3": {"options": [{"text": "同事", "is_correct": true, "explanation": "“同事”指一起上班的人，可以和“他”在一个办公室。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人，不能和“他”待在办公室里。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物体，不能和“他”在一个办公室里。"}, {"text": "办法", "is_correct": false, "explanation": "搭配：“在一个办公室”的对象应是人或具体的物，“办法”是抽象的，不能在办公室里。"}], "explanations": {"同事": "“同事”指一起上班的人，可以和“他”在一个办公室。", "石头": "语义：“石头”不是人，不能和“他”待在办公室里。", "窗户": "语义：“窗户”是物体，不能和“他”在一个办公室里。", "办法": "搭配：“在一个办公室”的对象应是人或具体的物，“办法”是抽象的，不能在办公室里。"}, "sentence_index": 0, "correct_answer": "同事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同事每天给我做饭，我每个月付他工资。", "explanation": "这里应该用〈保姆〉。“同事”指在同一个地方上班的人，不会受我雇用、拿我的工资，给我做饭并领我工资的应是“保姆”。"}, {"text": "我的同事每天和我坐同一张课桌。", "explanation": "这里应该用〈同桌〉。“同桌”指坐同一张课桌的人，“同事”指一起上班的人。"}, {"text": "我的同事每天在院子里汪汪叫。", "explanation": "这里应该用〈小狗〉。“同事”指人，不会汪汪叫，这里应指小狗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88989, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "同事", "is_correct": true, "explanation": "同事：在同一个地方一起上班的人。"}, {"text": "从事", "is_correct": false, "explanation": "cóng 与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。"}, {"text": "红事", "is_correct": false, "explanation": "hóng（第二声）与 tóng 声母不同（h 与 t），“红事”意思是喜庆的事，如婚礼。"}, {"text": "农事", "is_correct": false, "explanation": "nóng 与 tóng 声母不同（n 与 t），“农事”意思是农业上的事情。"}], "explanations": {"同事": "同事：在同一个地方一起上班的人。", "从事": "cóng 与 tóng 声母不同（c 与 t），“从事”意思是做某种工作。", "红事": "hóng（第二声）与 tóng 声母不同（h 与 t），“红事”意思是喜庆的事，如婚礼。", "农事": "nóng 与 tóng 声母不同（n 与 t），“农事”意思是农业上的事情。"}, "sentence_index": null, "correct_answer": "同事"}, "level_3": {"options": [{"text": "同事", "is_correct": true, "explanation": "“同事”指人，可以是“新同事”，符合“我不太了解新……”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“新窗户”与“了解”搭配不自然，一般不说“不太了解新窗户”。"}, {"text": "新闻", "is_correct": false, "explanation": "重复：“新闻”前已有“新”，“新新闻”不成词，不能填入。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“新时间”不是常用搭配，“了解”的对象应是人或具体的事情。"}], "explanations": {"同事": "“同事”指人，可以是“新同事”，符合“我不太了解新……”。", "窗户": "搭配：“新窗户”与“了解”搭配不自然，一般不说“不太了解新窗户”。", "新闻": "重复：“新闻”前已有“新”，“新新闻”不成词，不能填入。", "时间": "搭配：“新时间”不是常用搭配，“了解”的对象应是人或具体的事情。"}, "sentence_index": 6, "correct_answer": "同事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的同事把我养大了。", "explanation": "这里应该用〈父母〉。“同事”指在同一个地方上班的人，不会把我养大，抚养子女的应是“父母”。"}, {"text": "我的同事今年上小学了。", "explanation": "这里应该用〈孩子〉。“同事”指在同一个地方上班的人，不会去上小学，说“上小学”的应是“孩子”。"}, {"text": "我的同事今年两岁，还不会说话。", "explanation": "这里应该用〈宝宝〉。“同事”指上班的成年人，两岁还不会说话的应是“宝宝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三个同事们一起去吃饭了。", "corrected_sentence": "我们三个同事一起去吃饭了。", "error_description": "错误形式：“三个同事们”。“们”不能跟在数量词后面。正确形式：“三个同事”，去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一只同事下个月要结婚。", "corrected_sentence": "她有一位同事下个月要结婚。", "error_description": "错误形式：“一只同事”。“同事”指人，量词应用“位”或“个”，不用“只”（“只”多用于动物）。正确形式：“一位同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f73ae22-1669-4914-9226-4ed503bdb8af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
