INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在同一单位工作的人。", "primary_collocate": null, "pronunciation": "tóng shì", "ipa": "tʰʊŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我和同事一起吃午饭。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的新同事。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都在开会。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同事每天骑车上班。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的同事帮了我很多。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跟同事关系很好。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同事今天生病了。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事送了我一本书。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是同事，也是朋友。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我和同事去爬山了。", "target_word": "同事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老同事", "label": "复合"}, {"form": "新同事", "label": "复合"}, {"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "同一单位工作的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb1a83c7-686e-430e-8a43-46799c4d78f4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_erro